    {
      "path": "plugins/dsh-domain-bridge/lib/bridge.js",
      "content": "/**\n * dsh-domain-bridge — domain reachability layer v0.8.0\n *   (declaration-first + session factory + four-level pause + wake wiring + model dispatch\n *    + slash commands)\n *\n * Commands (6, Host-side; a command is a thin orchestrator over the tools below):\n *   /register [system|project [名称]|domain <域> [takeover]]   register this session's role\n *   /initialize [check]                                        complete the run skeleton (never overwrite)\n *   /handoff [model=…][preset=…][perm=…][target=new]           create a successor and transfer duty\n *   /retire [原因]                                              end this session's duty (keeps history)\n *   /pause self|project|global [原因]                           pause by authority\n *   /pause-all <self|project|global> <原因> [--confirm]         emergency pause (confirm + audit)\n *\n * Tools (11):\n *   list_domain_sessions()                         online top-level sessions + onDuty flags + every declaration\n *   send_to_domain(target, message, mode, ...)     deliver by domain (declaration first) or by session id\n *   claim_domain(domain, project?, note?, force?)  this session claims a domain seat (on-duty declaration)\n *   release_domain(domain, note?)                  this session releases its own declaration\n *   list_domain_owners()                           read-only view of every on-duty declaration\n *   create_domain_session(domain, task, ...)       open a real top-level session and enqueue a startup task\n *   set_domain_state(domain, state, scope?, ...)   pause / resume ONE of four scopes (policy axis)\n *   withdraw_domain_message(id, domain?, force?)   withdraw one queued message of a paused target\n *   list_models(session?)                          host model catalog (+ one session's selection)\n *   set_model(target?, provider, model, ...)       change ONE session's model for the next request\n *   set_default_model(provider, model, ...)        change the HOST GLOBAL DEFAULT (never restored)\n *\n * 变更史与设计依据（v0.2 → v0.6.1：每个版本的读码结论、真机踩坑、决策记录）见 CHANGELOG.md。\n */\n\nimport { VERSION, resolveRuntime, stateRoot } from './core/shared.js'\nimport { warn, registerTool } from './core/tools.js'\nimport { buildSendTool } from './core/messaging.js'\nimport { buildSetDomainStateTool, buildWithdrawMessageTool, buildListDomainQueueTool } from './core/pause.js'\nimport { buildListTool, buildClaimTool, buildReleaseTool, buildListOwnersTool } from './core/declaration.js'\nimport { buildListModelsTool, buildSetModelTool, buildSetDefaultModelTool, buildCreateSessionTool } from './core/session-factory.js'\nimport { runInitialize } from './core/bootstrap.js'\nimport { buildCommandDefs, registerCommandDefinitions } from './core/commands.js'\nimport { registerMenuRoutes } from './core/menu.js'\nimport { registerHubRoutes } from './core/hub.js'\n\nexport * from './core/shared.js'\nexport * from './core/tools.js'\nexport * from './core/messaging.js'\nexport * from './core/pause.js'\nexport * from './core/declaration.js'\nexport * from './core/session-factory.js'\nexport * from './core/registrations.js'\nexport * from './core/bootstrap.js'\nexport * from './core/commands.js'\nexport * from './core/menu.js'\nexport * from './core/hub.js'\n\nexport default {\n  name: 'domain-bridge',\n  // sessionController / workspaceRegistry are deliberately NOT injected: a missing service must\n  // degrade into an honest {created:false, reason} + pinned report, never into a loader failure.\n  // See getSessionController() and getWorkspaceRegistry().\n  inject: ['tools', 'agents'],\n  apply(ctx, rawConfig) {\n    try {\n      // portable: every machine-specific path comes from the portable runtime layer\n      // (deployment config > <home>/config.json > env > <home> defaults). A missing/broken home or\n      // config degrades to empty/candidate paths that the readers already treat as \"no data\", so\n      // apply still registers all 11 tools and reports \"0 domains\" instead of throwing.\n      const runtime = resolveRuntime(rawConfig)\n      const config = {\n        home: runtime.home,\n        configFile: runtime.configFile,\n        indexFile: runtime.indexFile,\n        domainsFile: runtime.domainsFile,\n        ownerCli: runtime.ownerCli,\n        // v0.3.3: 新建域会话建完立刻设的权限档名（部署里可用 read-only / workspace-write /\n        // danger-full-access；'' / 'none' / 'keep' / 'skip' ＝ 不动，保持宿主默认）。\n        // 写成 !== undefined 而不是 ||，这样配置里显式写 '' 才算「关掉」，不会被默认值顶掉。\n        // v0.6.4（安全默认）：缺省值由 danger-full-access 收窄为 workspace-write。后台域会话无人值守\n        // 仍不会卡在「等人点同意」，但不再默认拿到全盘写权限；要 danger-full-access 必须自己显式配置。\n        domainSessionPreset:\n          rawConfig && rawConfig.domainSessionPreset !== undefined\n            ? rawConfig.domainSessionPreset\n            : 'workspace-write',\n        // v0.6.0：新建域会话建完铺的模型（部署配置 > <home>/config.json > null＝不铺）。\n        // 非法值在 resolveRuntime 里归一成 null，永不抛错。\n        domainSessionModel: runtime.domainSessionModel,\n        // v0.4.0：政策轴（暂停）＋ 队列的落盘目录。默认＝`<home>/state`（见 defaultStateDir：\n        // 运行期数据不写进插件包目录，也不写进项目的 _registry 树）。写成 !== undefined 而不是 ||，\n        // 这样配置里显式写 '' 才会退回默认值。\n        stateDir: rawConfig && rawConfig.stateDir !== undefined ? rawConfig.stateDir : '',\n        // v0.8.15：会话工作台（hub / 拓扑 / 三维网络）的静态资源目录。缺省 `<home>/space`；\n        // GUI 本体由 GUI 域独立维护（纯 HTML/CSS/JS），插件只按白名单把文件发出去（见 core/hub.js）。\n        spaceDir: rawConfig && rawConfig.spaceDir !== undefined ? String(rawConfig.spaceDir) : '',\n      }\n\n      // v0.7.0: build each definition ONCE, register it, and hand the SAME object to the command\n      // layer — so /register, /handoff, /retire, /pause call the exact governance code the model\n      // calls. A command is an orchestrator, never a second implementation.\n      const defs = {\n        list: buildListTool(ctx, config),\n        send: buildSendTool(ctx, config),\n        claim: buildClaimTool(ctx, config),\n        release: buildReleaseTool(ctx, config),\n        owners: buildListOwnersTool(ctx, config),\n        create: buildCreateSessionTool(ctx, config),\n        pause: buildSetDomainStateTool(ctx, config),\n        withdraw: buildWithdrawMessageTool(ctx, config),\n        listQueue: buildListDomainQueueTool(ctx, config),\n        listModels: buildListModelsTool(ctx, config),\n        setModel: buildSetModelTool(ctx, config),\n        setDefaultModel: buildSetDefaultModelTool(ctx),\n      }\n      // v0.4.0：「已暂停」的人工控制入口 + 队列撤回入口；v0.6.0 模型分派；v0.6.1 全局默认模型入口。\n      // 宿主没有对应 API 时工具照常注册、如实回 api-unavailable —— 注册本身永不抛。\n      for (const definition of Object.values(defs)) registerTool(ctx, definition)\n      // v0.7.0：六条宿主斜杠命令（/register /initialize /handoff /retire /pause /pause-all）。\n      // v0.8.0：同一批定义既注册成命令，也挂到 popup 菜单路由上——一个实现，两个入口。\n      // ⚠️ 0.8.1 修复：`ctx.get('commands')` / `ctx.get('webServer')` 在**未注入**时拿不到服务，\n      // 于是命令没注册上（输入 /register 无反应）、菜单路由没挂上（弹出菜单后 404）。\n      // 正确姿势是 `ctx.inject([...], child => ...)`，与 free-search 的 webServer 用法一致。\n      const commandDefs = buildCommandDefs(ctx, { config, defs, runInitialize })\n      // 两个服务必须注入在**同一个子作用域**里：菜单路由的执行阶段还要用 commands（执行命令）\n      // 与 agents（拿调用者），跨作用域取不到。\n      // v0.8.5 修根因：**这个回调必须 return 一个 disposer**。宿主只会收集 apply 的返回值；\n      // 以前两个 register* 的 disposer 全被丢掉 ⇒ 插件在同一个进程里重载（HMR/停用再启用/装新版）\n      // 时旧路由留在 webServer 的 exact 表里、新路由注册抛 duplicate 又被空 catch 吞掉，\n      // 结果是 /run 与 /health 永远打到**已经失效的旧实例**上（真机症状：/run 报\n      // `cannot get required service \"commands\" in inactive context`、/health 空体 400），\n      // 六条命令的弹窗点了什么都不发生，直到重启 dsh。\n      ctx.inject(['commands', 'webServer'], (bridgeCtx) => {\n        const disposers = []\n        try {\n          const dispose = registerCommandDefinitions(bridgeCtx, commandDefs)\n          if (typeof dispose === 'function') disposers.push(dispose)\n        } catch (error) {\n          warn(`command registration failed: ${error?.message || String(error)}`)\n        }\n        try {\n          const dispose = registerMenuRoutes(bridgeCtx, { config, defs, runInitialize, commandDefs })\n          if (typeof dispose === 'function') disposers.push(dispose)\n          warn('command menu routes registered (/api/dsh-domain-bridge/{health,menu,run})')\n        } catch (error) {\n          warn(`menu routes failed: ${error?.message || String(error)}`)\n        }\n        // v0.8.15：工作台静态页（白名单 6 个固定路径；文件缺席回诚实的空态，不是 500）。\n        try {\n          const dispose = registerHubRoutes(bridgeCtx, config)\n          if (typeof dispose === 'function') disposers.push(dispose)\n          warn('hub routes registered (/api/dsh-domain-bridge/hub[,/view/*])')\n        } catch (error) {\n          warn(`hub routes failed: ${error?.message || String(error)}`)\n        }\n        return () => {\n          for (const dispose of disposers) {\n            try {\n              dispose()\n            } catch {\n              /* a dispose failure must never block the rest */\n            }\n          }\n        }\n      })\n      warn(\n        `loaded v${VERSION} (tools: list_domain_sessions, send_to_domain, claim_domain, release_domain, ` +\n          `list_domain_owners, create_domain_session, set_domain_state, withdraw_domain_message, ` +\n          `list_domain_queue, ` +\n          `list_models, set_model, set_default_model; ` +\n          `home: ${config.home || '(none)'}; ` +\n          `config: ${runtime.configFile || '(none)'}${runtime.configError ? ` [read failed: ${runtime.configError}]` : ''}; ` +\n          `indexFile: ${config.indexFile} [${runtime.indexFileSource}]; ` +\n          `domainsFile: ${config.domainsFile} [${runtime.domainsFileSource}]; ` +\n          `ownerCli: ${config.ownerCli || '(none)'} [${runtime.ownerCliSource}]; ` +\n          `domainSessionModel: ` +\n          (config.domainSessionModel\n            ? `${config.domainSessionModel.provider}/${config.domainSessionModel.model}` +\n              (config.domainSessionModel.reasoningEffort ? ` (effort=${config.domainSessionModel.reasoningEffort})` : '') +\n              ` [${runtime.domainSessionModelSource}]`\n            : `(none) [${runtime.domainSessionModelSource}]`) +\n          `; ` +\n          `stateDir: ${stateRoot(config.stateDir)})`,\n      )\n    } catch (error) {\n      // apply 永不抛错：宁可少几个工具，也不能让加载器硬失败。\n      warn(`apply failed: ${error?.message || String(error)}`)\n    }\n  },\n}"
    },
    {
      "path": "plugins/dsh-domain-bridge/lib/core/tools.js",
      "content": "/**\n * dsh-domain-bridge — tool registration plumbing: the handler shell shared by all 11 tools and its lossless-output choke point.\n *\n * Split out of the single-file lib/bridge.js in v0.6.3 (pure move: no behaviour change).\n * The package entry point stays lib/bridge.js, which re-exports this module.\n */\n\nimport { PLUGIN } from './shared.js'\n\nexport function warn(message) {\n  try {\n    console.warn(`[${PLUGIN}] ${message}`)\n  } catch {\n    /* 连 console 都不该成为失败点 */\n  }\n}\n\n/** 两 realm 兼容注册：harness 优先（动态沙箱），否则走静态包的 ctx.tools.register。永不抛。 */\nexport function registerTool(ctx, definition) {\n  try {\n    if (\n      typeof harness !== 'undefined' &&\n      harness &&\n      typeof harness.defineTool === 'function' &&\n      typeof harness.registerTool === 'function'\n    ) {\n      return harness.registerTool(ctx, harness.defineTool(definition))\n    }\n    if (ctx && ctx.tools && typeof ctx.tools.register === 'function') {\n      return ctx.tools.register(definition)\n    }\n    warn(`no tool registration API available; \"${definition.name}\" not registered`)\n  } catch (error) {\n    warn(`tool registration failed for \"${definition.name}\": ${error?.message || String(error)}`)\n  }\n  return () => {}\n}\n\n/** Internal sentinel: \"this value must be DELETED by its parent\" (never leaves the plugin). */\nexport const DROP = Symbol('dsh-domain-bridge.drop')\n\n/**\n * Tool outputs must survive `JSON.parse(JSON.stringify(v))` unchanged.\n *\n * Real-machine evidence (2026-10-11, v0.3.0): list_domain_owners returned a top-level\n * `hint: undefined`, the host rejected the WHOLE call with\n * `tool \"list_domain_owners\" returned invalid output: value is not lossless JSON`\n * and never named the offending field. `JSON.stringify` drops `undefined` keys, so the\n * normalized round trip is lossy - the host validates exactly that.\n *\n * `undefined` is not the only lossy value, so normalize every JSON-hostile one here:\n *   undefined / function / symbol  -> key deleted (arrays: null)\n *   NaN / +-Infinity               -> null      (stringify also writes null, but the round trip must EQUAL)\n *   -0                             -> 0         (stringify writes 0, and -0 !== 0 in a strict deep compare)\n *   bigint                         -> decimal string (stringify THROWS on bigint)\n *   Date                           -> ISO string, invalid Date -> null\n *   Map / Set                      -> plain object (string keys) / array\n *   circular reference             -> null      (stringify THROWS on cycles)\n */\nexport function losslessValue(value, stack) {\n  if (value === undefined || typeof value === 'function' || typeof value === 'symbol') return DROP\n  if (value === null || typeof value === 'string' || typeof value === 'boolean') return value\n  if (typeof value === 'number') {\n    if (!Number.isFinite(value)) return null\n    return Object.is(value, -0) ? 0 : value\n  }\n  if (typeof value === 'bigint') return value.toString()\n  if (value instanceof Date) return Number.isFinite(value.getTime()) ? value.toISOString() : null\n  // Only an ANCESTOR can be a cycle; a plain shared object is duplicated, exactly like stringify.\n  if (stack.includes(value)) return null\n  stack.push(value)\n  try {\n    if (Array.isArray(value)) {\n      return value.map((item) => {\n        const next = losslessValue(item, stack)\n        // Sparse slots, undefined, functions and symbols all become null, exactly like stringify.\n        return next === DROP ? null : next\n      })\n    }\n    if (value instanceof Map) {\n      const out = {}\n      for (const [key, item] of value) {\n        const next = losslessValue(item, stack)\n        out[String(key)] = next === DROP ? null : next\n      }\n      return out\n    }\n    if (value instanceof Set) {\n      return [...value].map((item) => {\n        const next = losslessValue(item, stack)\n        return next === DROP ? null : next\n      })\n    }\n    const out = {}\n    for (const key of Object.keys(value)) {\n      let next\n      try {\n        next = losslessValue(value[key], stack)\n      } catch {\n        // An exotic getter threw: losing one field beats killing the whole tool call.\n        next = null\n      }\n      if (next !== DROP) out[key] = next\n    }\n    return out\n  } finally {\n    stack.pop()\n  }\n}\n\n/** Recursively drop/normalize every value JSON cannot round-trip losslessly. Never throws. */\nexport function pruneUndefined(value) {\n  try {\n    const next = losslessValue(value, [])\n    return next === DROP ? null : next\n  } catch {\n    // A last-resort guard: an unprunable value must still not break the host contract.\n    return null\n  }\n}\n\nexport function tool(name, description, parameters, execute) {\n  return {\n    name,\n    description,\n    // 函数调用要求 object-rooted schema；这里统一包装。\n    parameters: { type: 'object', properties: parameters },\n    output: {\n      schema: { type: 'object', additionalProperties: true },\n      render(_args, value) {\n        return [{ type: 'text', text: JSON.stringify(value, null, 2) }]\n      },\n    },\n    // Single choke point for lossless output: EVERY tool goes through pruneUndefined() on the way\n    // out, so no individual branch (now or later) can make the host reject a whole call.\n    async execute(args, exec) {\n      return pruneUndefined(await execute.call(this, args, exec))\n    },\n  }\n}\n\n/** 会话 id → 域/使命 的只读映射。索引缺失、格式变了都不抛，只降级为\"无域标注\"。 */\n"
    },
    {
      "path": "plugins/dsh-domain-bridge/lib/core/shared.js",
      "content": "/**\n * dsh-domain-bridge — shared constants, portable runtime paths and the small generic helpers.\n *\n * Split out of the single-file lib/bridge.js in v0.6.3 (pure move: no behaviour change).\n * The package entry point stays lib/bridge.js, which re-exports this module.\n */\n\nimport fs from 'node:fs'\nimport os from 'node:os'\nimport path from 'node:path'\nimport { createHash } from 'node:crypto'\n\nexport const PLUGIN = 'dsh-domain-bridge'\nexport const VERSION = '0.8.16'\n/**\n * v0.3.6 审计 traceId（项目规则 vibe-audit-logger-lite）：本次三处行为日志共用它，\n * 完整故事线落在 projectlog/2026-10-12-域桥v0.3.6-F1F2F4交接防混乱.md。\n */\nexport const TRACE_ID = 'bridge-v036-1012'\n/** v0.4.0 审计 traceId（同上规则）：暂停/入队/恢复重投/撤回的行为日志共用它。 */\nexport const TRACE_ID_V040 = 'bridge-v040-1013'\n/** v0.4.1 审计 traceId（同上规则）：拉活接线解析/拒绝拉活/恢复时尝试唤醒共用它。 */\nexport const TRACE_ID_V041 = 'bridge-v041-1013'\n/** v0.4.2 审计 traceId（同上规则）：四级暂停的 OR 判定/global 防误触/恢复重评共用它。 */\nexport const TRACE_ID_V042 = 'bridge-v042-1014'\n/** v0.6.1 审计 traceId（同上规则）：全局默认模型的读写（set_default_model 入口/结果）共用它。 */\nexport const TRACE_ID_V061 = 'bridge-v061-1017'\n/**\n * portable install (v0.4.2) — everything machine-specific is resolved at load time, never baked\n * into this file:\n *   home        = DSH_DOMAIN_BRIDGE_HOME  ||  <os.homedir()>/.dsh/dsh-domain-bridge\n *   indexFile   = deployment config → <home>/config.json → DSH_DOMAIN_BRIDGE_INDEX → <home>/registry.json\n *   domainsFile = deployment config → <home>/config.json → DSH_DOMAIN_BRIDGE_DOMAINS → <home>/domains.json\n *   ownerCli    = deployment config → <home>/config.json → DSH_DOMAIN_BRIDGE_OWNER_CLI → '' (generic wording)\n * The two defaults live in the runtime home (which starts out empty ⇒ 0 domains, no throw), and the\n * package directory is never written to. `stateDir` defaults to <home>/state.\n */\nexport const HOME_ENV = 'DSH_DOMAIN_BRIDGE_HOME'\nexport const INDEX_ENV = 'DSH_DOMAIN_BRIDGE_INDEX'\nexport const DOMAINS_ENV = 'DSH_DOMAIN_BRIDGE_DOMAINS'\nexport const OWNER_CLI_ENV = 'DSH_DOMAIN_BRIDGE_OWNER_CLI'\n/** Name of the optional per-machine file inside `home`. */\nexport const HOME_CONFIG_NAME = 'config.json'\n/** Default filenames inside `home` (self-sufficient: an absent/empty file is a normal \"no data\"). */\nexport const HOME_INDEX_NAME = 'registry.json'\nexport const HOME_DOMAINS_NAME = 'domains.json'\n\n\n// --------------------------------------------------------------- v0.4.0/v0.4.2: two axes + lifecycle + scopes\n\n/**\n * 政策轴的**四级作用域**（v0.4.2）：\n *   `domain`  ＝「项目:域」——域名册里的一个 key（**要求已有一条在任声明**，v0.4.0 的语义一字不改）\n *   `session` ＝ 完整会话 id（`session-<uuid>`）＝中文说的「主（单会话暂停）」\n *   `project` ＝ 项目名小写（某会话 cwd 的目录名小写，与 claim_domain 短名补全同一约定）\n *   `global`  ＝ 保留键 `*`（唯一）\n * 机器面字面量**只能**是这四个（中文只在文档/回执里出现）。\n */\nexport const SCOPE_DOMAIN = 'domain'\nexport const SCOPE_SESSION = 'session'\nexport const SCOPE_PROJECT = 'project'\nexport const SCOPE_GLOBAL = 'global'\nexport const PAUSE_SCOPES = [SCOPE_DOMAIN, SCOPE_SESSION, SCOPE_PROJECT, SCOPE_GLOBAL]\n/** global 的保留键（唯一）。 */\nexport const GLOBAL_KEY = '*'\n/** 工具参数 `scope` 接受的中文别名（机器面仍归一到上面四个字面量）。 */\nexport const SCOPE_ALIASES = {\n  domain: SCOPE_DOMAIN,\n  域: SCOPE_DOMAIN,\n  session: SCOPE_SESSION,\n  主: SCOPE_SESSION,\n  会话: SCOPE_SESSION,\n  project: SCOPE_PROJECT,\n  项目: SCOPE_PROJECT,\n  global: SCOPE_GLOBAL,\n  全局: SCOPE_GLOBAL,\n}\n/** 政策轴上\"这个 scope 没有「在线/离线」这回事\"时用的两个词（project / global 的对外状态）。 */\nexport const STATE_POLICY_PAUSED = '已暂停'\nexport const STATE_POLICY_ACTIVE = '活动'\n\n/**\n * 派生状态（**算出来**的，永不落盘、永不当作事实来源）。见 CHANGELOG.md v0.4.0 段：\n *   两个轴（在线/离线 × 活动/已暂停）+ 生命周期（在用/已终结）。\n * 判据（`deriveDomainState`）：\n *   · 域名册里还有这条声明 ⇒ 「在线|离线 · 活动|已暂停」（按 isSessionOnline + paused）\n *   · 声明没了 且 有墓碑（terminatedAt） ⇒ 「已终结」\n *   · 声明没了 也没墓碑 ⇒ null＝\"不在册\"，**不猜**\n */\nexport const STATE_ONLINE_ACTIVE = '在线·活动'\nexport const STATE_ONLINE_PAUSED = '在线·已暂停'\nexport const STATE_OFFLINE_ACTIVE = '离线·活动'\nexport const STATE_OFFLINE_PAUSED = '离线·已暂停'\nexport const STATE_TERMINATED = '已终结'\nexport const DERIVED_STATE_NAMES = [\n  STATE_ONLINE_ACTIVE,\n  STATE_ONLINE_PAUSED,\n  STATE_OFFLINE_ACTIVE,\n  STATE_OFFLINE_PAUSED,\n  STATE_TERMINATED,\n]\n/** list_* 里展示的**五态字典**（让五个派生状态在任何一次 list 调用里都抬眼可见）。 */\nexport const DERIVED_STATE_LEGEND = [\n  { name: STATE_ONLINE_ACTIVE, axes: { online: true, paused: false }, meaning: '有活 Agent，政策轴上活动：正常在岗。' },\n  { name: STATE_ONLINE_PAUSED, axes: { online: true, paused: true }, meaning: '有活 Agent，但该域已被按下暂停：插件介导的投递被拦、消息入队。' },\n  { name: STATE_OFFLINE_ACTIVE, axes: { online: false, paused: false }, meaning: '没有活 Agent，政策轴上活动：窗口已关/没加载，离线不排队（除非显式 wake）。' },\n  { name: STATE_OFFLINE_PAUSED, axes: { online: false, paused: true }, meaning: '没有活 Agent，且该域已被按下暂停：消息入队，等人手动唤起。' },\n  { name: STATE_TERMINATED, axes: { online: null, paused: null }, meaning: '在任声明已释放（生命周期终结）：域名册里不再有它；只有经本插件 release_domain 终结的域才有这条墓碑。' },\n]\n\n\nexport function loadIndex(indexFile) {\n  const empty = { generatedAt: null, bySession: new Map(), error: null }\n  try {\n    const text = fs.readFileSync(indexFile, 'utf8')\n    const json = JSON.parse(text)\n    const bySession = new Map()\n    for (const mission of json.missions || []) {\n      const sid = mission.sessionId\n      if (!sid) continue\n      const entry = bySession.get(sid) || { domains: new Set(), missions: [] }\n      if (mission.domain) entry.domains.add(String(mission.domain))\n      entry.missions.push({\n        number: mission.number ?? null,\n        status: mission.status ?? null,\n        feature: mission.feature ?? null,\n      })\n      bySession.set(sid, entry)\n    }\n    return { generatedAt: json.generatedAt ?? null, bySession, error: null }\n  } catch (error) {\n    return { ...empty, error: error?.message || String(error) }\n  }\n}\n\nexport function emptyIndex() {\n  return { generatedAt: null, bySession: new Map(), error: null }\n}\n\n/** 索引里的短名口径：session-<uuid> → sess-<uuid 前 8 位>（与 _registry\\INDEX.md 一致）。 */\nexport function shortId(id) {\n  if (typeof id !== 'string') return null\n  const stripped = id.replace(/^session-/, '')\n  return `sess-${stripped.slice(0, 8)}`\n}\n\n/** One row per live top-level session: index labels + whether it holds an on-duty declaration. */\nexport function describe(agent, index, duties) {\n  try {\n    const header = agent?.session?.header || {}\n    const idx = index || emptyIndex()\n    const entry = idx.bySession ? idx.bySession.get(agent?.id) : null\n    const dutyList = duties && agent?.id ? duties.get(agent.id) : null\n    const duty = dutyList && dutyList.length ? dutyList[0] : null\n    return {\n      id: agent?.id ?? null,\n      shortId: shortId(agent?.id),\n      domains: entry ? [...entry.domains] : [],\n      missions: entry ? entry.missions.map((m) => m.number).filter(Boolean) : [],\n      onDuty: Boolean(duty),\n      dutyDomain: duty ? (duty.domain ?? null) : null,\n      dutyDomainKey: duty ? (duty.key ?? null) : null,\n      dutyDomainKeys: dutyList ? dutyList.map((item) => item.key) : [],\n      cwd: header.cwd ?? null,\n      preset: header.agentPreset ?? null,\n      topLevel: header.parentSession === undefined,\n      origin: header.origin ?? null,\n      seeded: header.isSeeded ?? null,\n    }\n  } catch (error) {\n    return { id: agent?.id ?? null, shortId: shortId(agent?.id), error: error?.message || String(error) }\n  }\n}\n\nexport function liveTopLevel(ctx, index, duties) {\n  const agents = ctx?.agents?.list?.() ?? []\n  return agents\n    .map((agent) => ({ agent, info: describe(agent, index, duties) }))\n    .filter((row) => row.info.topLevel === true)\n}\n\n// --------------------------------------------------------------- declaration book (domains.json)\n\n/**\n * Read-only load of the declaration book. Missing file, unreadable file, malformed JSON and\n * wrong shapes all degrade to \"no declaration\" without throwing (the CLI treats a missing\n * file the same way: \"nobody claimed anything\", not an error).\n */\nexport function dutyMap(declarations) {\n  const map = new Map()\n  for (const entry of declarations?.entries || []) {\n    const sid = entry.sessionId\n    if (!sid) continue\n    const list = map.get(sid) || []\n    list.push(entry)\n    map.set(sid, list)\n  }\n  return map\n}\n\n/** Is that session id currently live? Rows first, then agents.get(), then agents.list(). Never throws. */\nexport function isSessionOnline(ctx, id, rows) {\n  if (!id) return false\n  if (Array.isArray(rows) && rows.some((row) => row?.info?.id === id)) return true\n  try {\n    const getter = ctx?.agents?.get\n    if (typeof getter === 'function') return Boolean(getter.call(ctx.agents, id))\n    const list = ctx?.agents?.list?.() ?? []\n    return list.some((agent) => agent?.id === id)\n  } catch {\n    return false\n  }\n}\n\nexport function textOf(value) {\n  return typeof value === 'string' ? value.trim() : ''\n}\n\nexport function envText(name) {\n  try {\n    return textOf(process.env && process.env[name])\n  } catch {\n    return ''\n  }\n}\n\n/**\n * Runtime home for per-machine data: `DSH_DOMAIN_BRIDGE_HOME` wins, else `<homedir>/.dsh/<plugin>`.\n * Returning '' (no homedir at all) is a degraded state, never an exception: readers treat an empty\n * path as \"no file\", which is exactly the \"0 domains, no throw\" behaviour the loader needs.\n */\nexport function bridgeHome() {\n  const fromEnv = envText(HOME_ENV)\n  if (fromEnv) return fromEnv\n  try {\n    const home = os.homedir()\n    return home ? path.join(home, '.dsh', PLUGIN) : ''\n  } catch {\n    return ''\n  }\n}\n\n/**\n * Optional per-machine config `<home>/config.json` with `indexFile` / `domainsFile` / `ownerCli`.\n * Missing file = normal. Unreadable/malformed file degrades to \"no file config\" (env + defaults\n * still apply) and is reported in the loaded log line - it must never stop plugin loading.\n */\nexport function readHomeConfig(home) {\n  const file = home ? path.join(home, HOME_CONFIG_NAME) : ''\n  const out = { file, fileExisted: false, error: null, values: {} }\n  if (!file) return out\n  let raw\n  try {\n    raw = fs.readFileSync(file, 'utf8')\n  } catch (error) {\n    if (!(error && error.code === 'ENOENT')) out.error = error?.message || String(error)\n    return out\n  }\n  out.fileExisted = true\n  try {\n    const json = JSON.parse(raw)\n    if (json && typeof json === 'object' && !Array.isArray(json)) out.values = json\n    else out.error = 'config.json 顶层不是对象'\n  } catch (error) {\n    out.error = error?.message || String(error)\n  }\n  return out\n}\n\n/**\n * v0.6.0 `domainSessionModel` normalization: `{provider, model, reasoningEffort?}` with two\n * non-empty strings required. Anything else (wrong type, array, missing half, blank strings) is\n * treated as \"not configured\" - this function never throws, because config is not allowed to stop\n * the plugin from loading.\n */\nexport function normalizeModelConfig(value) {\n  try {\n    if (!value || typeof value !== 'object' || Array.isArray(value)) return null\n    const provider = textOf(value.provider)\n    const model = textOf(value.model)\n    if (!provider || !model) return null\n    const reasoningEffort = textOf(value.reasoningEffort)\n    return { provider, model, ...(reasoningEffort ? { reasoningEffort } : {}) }\n  } catch {\n    return null\n  }\n}\n\n/**\n * Effective runtime settings. Resolution order per key:\n *   1. explicit deployment config (cordis.patch.yml / apply(rawConfig)) when non-empty\n *   2. `<home>/config.json`\n *   3. environment variable\n *   4. default inside `<home>` (ownerCli defaults to '' = generic wording, no invented path)\n * Step 1 stays first so an existing deployment's explicit paths keep winning and so the test\n * harness can mount the plugin with its own fixtures without reading the machine's config.json.\n * Never throws: a broken layer simply falls through to the next one.\n *\n * v0.6.0 adds `domainSessionModel` (an OBJECT, not a path): deployment config wins, then\n * `<home>/config.json`, then \"not configured\". Invalid shapes are silently absent, never an error.\n */\nexport function resolveRuntime(rawConfig) {\n  const home = bridgeHome()\n  const homeConfig = readHomeConfig(home)\n  const deployment = rawConfig && typeof rawConfig === 'object' ? rawConfig : {}\n  const pick = (key, envName, fallback) => {\n    const fromDeployment = textOf(deployment[key])\n    if (fromDeployment) return { value: fromDeployment, source: 'deployment-config' }\n    const fromHome = textOf(homeConfig.values[key])\n    if (fromHome) return { value: fromHome, source: homeConfig.file }\n    const fromEnv = envText(envName)\n    if (fromEnv) return { value: fromEnv, source: `env:${envName}` }\n    return { value: fallback, source: 'default' }\n  }\n  const index = pick('indexFile', INDEX_ENV, home ? path.join(home, HOME_INDEX_NAME) : '')\n  const domains = pick('domainsFile', DOMAINS_ENV, home ? path.join(home, HOME_DOMAINS_NAME) : '')\n  const ownerCli = pick('ownerCli', OWNER_CLI_ENV, '')\n  const model = (() => {\n    const fromDeployment = normalizeModelConfig(deployment.domainSessionModel)\n    if (fromDeployment) return { value: fromDeployment, source: 'deployment-config' }\n    const fromHome = normalizeModelConfig(homeConfig.values.domainSessionModel)\n    if (fromHome) return { value: fromHome, source: homeConfig.file }\n    return { value: null, source: 'default' }\n  })()\n  return {\n    home,\n    configFile: homeConfig.file,\n    configFileExisted: homeConfig.fileExisted,\n    configError: homeConfig.error,\n    indexFile: index.value,\n    indexFileSource: index.source,\n    domainsFile: domains.value,\n    domainsFileSource: domains.source,\n    ownerCli: ownerCli.value,\n    ownerCliSource: ownerCli.source,\n    // v0.6.0：create_domain_session 建完给新会话铺的模型；null = 不铺（继承全局默认）。\n    domainSessionModel: model.value,\n    domainSessionModelSource: model.source,\n  }\n}\n\n/** Human-facing reference to the external CLI: the configured path, else the bare script name. */\nexport function ownerCliRef(config) {\n  return textOf(config && config.ownerCli) || 'domain-owner.mjs'\n}\n\n// ------------------------------- v0.4.0 domain state store (policy axis) + persisted inbox (queue)\n\n/**\n * Default state directory: `<home>/state`. Runtime data must not live inside the package directory\n * (a reinstall/upgrade would drop it, and one shared copy cannot serve two machines). It is still\n * deliberately NOT inside the project's `_registry` tree - that is human-owned data. `stateDir`\n * remains a config key, so a deployment can point it anywhere.\n */\nexport function defaultStateDir() {\n  try {\n    const home = bridgeHome()\n    return home ? path.join(home, 'state') : null\n  } catch {\n    return null\n  }\n}\n\nexport function stateRoot(stateDir) {\n  const given = String(stateDir ?? '').trim()\n  return given || defaultStateDir() || ''\n}\n\nexport function stateDirs(stateDir) {\n  const base = stateRoot(stateDir)\n  return { base, domains: path.join(base, 'domains'), inbox: path.join(base, 'inbox') }\n}\n\n/**\n * `项目:域` -> one safe FILE NAME. Windows forbids `:` in file names, and a raw key could carry\n * separators or a `..` climb, so: keep [a-z0-9_.-], drop leading dots, cap at 60 chars, and append\n * a short sha1 of the raw key so two different keys can never collide on the same file.\n */\nexport function safeKeyName(key) {\n  const raw = String(key ?? '').toLowerCase().trim()\n  const flat = raw.replace(/[^a-z0-9_.-]+/g, '_').replace(/^[._-]+/, '').slice(0, 60)\n  let hash = 'hashless'\n  try {\n    hash = createHash('sha1').update(raw, 'utf8').digest('hex').slice(0, 8)\n  } catch {\n    hash = 'hashless'\n  }\n  return 'k-' + (flat || 'domain') + '-' + hash\n}\n\nexport function stateFileFor(stateDir, key, scope) {\n  return path.join(stateDirs(stateDir).domains, stateFileName(key, scope) + '.json')\n}\n\n/**\n * 一个 key 属于哪个 scope？**只按键形状判**（用来给落盘文件分命名空间）：\n *   `session-<uuid>` ⇒ session；其余（含 `项目:域` 与保留键 `*`）⇒ domain。\n * 可判的依据：键的唯一产地——session 键是从宿主拿到的完整会话 id（一律 `session-` 开头），\n * 域键一律 `项目:域`；队列只按这两类**被投递目标自身的键**分片（v0.4.2 冻结口径），\n * 所以\"键形状 ⇒ scope\"在本插件里是单向可判的。显式给 scope 的地方一律以显式值为准。\n */\nexport function queueScopeOf(key) {\n  return /^session-/.test(String(key ?? '').trim().toLowerCase()) ? SCOPE_SESSION : SCOPE_DOMAIN\n}\n\n/**\n * 落盘文件名：**一 scope 一键一文件**（v0.4.2）。\n *   · domain 级**沿用 v0.4.1 的 `k-<flat>-<sha1>`**（历史状态文件不能因为升级失联）；\n *   · 其余三级加 scope 前缀（`session-k-…` / `project-k-…` / `global-k-…`）\n *     ⇒ 同一个 key 字符串出现在两个 scope 下也**结构上不可能**互相覆盖。\n *   （这条是刻意的加强：数量级上几乎不会撞，但\"撞了会静默覆盖别人的记录\"是不该留的失败模式。）\n */\nexport function stateFileName(key, scope) {\n  const base = safeKeyName(key)\n  const real = String(scope ?? '').trim().toLowerCase() || SCOPE_DOMAIN\n  return real === SCOPE_DOMAIN ? base : `${real}-${base}`\n}\n\nexport function inboxFileFor(stateDir, key, scope) {\n  const real = String(scope ?? '').trim().toLowerCase() || queueScopeOf(key)\n  return path.join(stateDirs(stateDir).inbox, stateFileName(key, real) + '.jsonl')\n}\n\n/** The empty/unknown state record: every key always present, so results stay lossless JSON. */\nexport function isFullSessionId(value) {\n  return /^session-[0-9a-z-]+$/i.test(String(value ?? '').trim())\n}\n\n/** 看起来是在说会话（`sess-…` / `session-…`）——用来决定\"这里要不要报 unresolved\"。 */\nexport function isSessionIdLike(value) {\n  return /^sess/i.test(String(value ?? '').trim())\n}\n\n/**\n * 宿主 Web 服务的 origin（`http://127.0.0.1:<port>`），拿不到就 `null`。\n * 只有\"给人点开一个本地页面\"这类场景需要它（例如 /handoff 的分步表单）；\n * 取服务一律先 `ctx.get` 再属性读，两条路都不许抛——失效 fiber 上属性读会直接抛。\n */\nexport function webOrigin(ctx) {\n  let server = null\n  try {\n    if (ctx && typeof ctx.get === 'function') server = ctx.get('webServer')\n  } catch {\n    server = null\n  }\n  if (!server) {\n    try {\n      server = ctx ? ctx.webServer ?? null : null\n    } catch {\n      server = null\n    }\n  }\n  if (!server) return null\n  try {\n    if (typeof server.getOrigin === 'function') return String(server.getOrigin())\n  } catch {\n    /* fall back to the port form */\n  }\n  try {\n    if (server.port) return `${server.protocol || 'http:'}//127.0.0.1:${server.port}`\n  } catch {\n    /* treat as unavailable */\n  }\n  return null\n}\n\n/**\n * session 键解析（只读、不猜）：\n *   · 完整会话 id（`session-<uuid>`）⇒ **原样接受**（**不要求它现在在线**：这正是\"按下的会话\n *     重启之后还能解开\"的前提）；\n *   · 短号 / 片段 ⇒ 只在**唯一命中**一条已知会话时接受（已知＝在线顶层会话 ∪ 域名册里的声明会话）。\n */\nexport function messageOf(error) {\n  try {\n    return error?.message || String(error)\n  } catch {\n    return 'unknown error'\n  }\n}\n\n/**\n * The one and only envelope builder for everything this plugin delivers.\n * send_to_domain and create_domain_session BOTH go through here - never paste a second copy,\n * because the footer is the receiver's only built-in reply instruction.\n */\nexport function dirLabelOf(value) {\n  try {\n    const text = String(value ?? '').replace(/[\\\\/]+$/, '')\n    return path.basename(text) || text\n  } catch {\n    return String(value ?? '')\n  }\n}\n\n/**\n * Point one domain's on-duty declaration at a freshly created session.\n * Same file schema, same atomic replace and same \"never overwrite somebody else\" rule as\n * claim_domain / domain-owner.mjs - it only takes the owner session id as a parameter instead\n * of assuming the caller. `force` is deliberately NOT exposed here: a brand new session must\n * never silently displace a sitting owner.\n */\n"
    },
    {
      "path": "plugins/dsh-domain-bridge/lib/core/messaging.js",
      "content": "/**\n * dsh-domain-bridge — send_to_domain delivery, the persisted inbox queue and the pause-gate reading.\n *\n * Split out of the single-file lib/bridge.js in v0.6.3 (pure move: no behaviour change).\n * The package entry point stays lib/bridge.js, which re-exports this module.\n */\n\nimport fs from 'node:fs'\nimport path from 'node:path'\nimport { randomUUID } from 'node:crypto'\nimport { PLUGIN, TRACE_ID, TRACE_ID_V041, TRACE_ID_V042, loadIndex, shortId, describe, liveTopLevel, dutyMap, stateDirs, queueScopeOf, inboxFileFor, isSessionIdLike, messageOf } from './shared.js'\nimport { warn, tool } from './tools.js'\n// 唯一名 tmp + rename 重试的写盘通道：**复用 registrations.js 的那一份**（勿在本模块另写一套）。\n// 固定名 `<file>.tmp` 在两进程并发重写同一队列时会静默丢写（审计 P1-02 已复现）。\n// withDomainsLock：同一个模块里的跨进程 `.lock` 通道，本模块把它改名成 withFileLock 复用（见下）。\nimport { writeAtomicUnique, withDomainsLock } from './registrations.js'\nimport { pausedScopesOf, pausedScopesWords, pausedTargetOf, primaryPauseHit, pausedFactsOf, pausedSendHint } from './pause.js'\nimport { loadDeclarations, readOwnersBook, resolveTarget } from './declaration.js'\nimport { offlineCandidateId, resolveWakeWiring, resumeSession } from './session-factory.js'\n\nexport const INBOX_PENDING = 'pending'\nexport const INBOX_DELIVERED = 'delivered'\nexport const INBOX_FAILED = 'failed'\nexport const INBOX_WITHDRAWN = 'withdrawn'\n/**\n * F-18（2026-10-24）：`delivering` = **投递中的中间态**（租约），不是第四个终态。\n *\n * 契约变化（INV-05 必须照这个读）：终态**仍然只有** `delivered` / `failed` / `withdrawn`；\n * `delivering` 只在一段**有上限的窗口**内出现（`claimInboxDelivery()` 拿到租约 ⇒ 投递 ⇒\n * `updateInboxStatus()` 落到终态）。它存在的唯一理由是让\"同一份 pending 快照被两路 drain 各投一次\"\n * 变成\"后到的那一路读到租约就跳过\"；顺带让**崩溃**留下的记录可被下一次 drain 按 TTL 重新认领\n * （`DELIVERING_STALE_MS`，超时即视为\"上一个投递者已经死了\"）。\n * 因此：`pending` 计数**不再包含**正在投的那条（窗口极短）；`withdraw_domain_message` 在窗口内\n * 会回 `not-pending`（不假装撤回）；崩溃恢复由下一次 drain 负责，不靠人。\n */\nexport const INBOX_DELIVERING = 'delivering'\n\n/**\n * `delivering` 租约的存活上限：**5 分钟**。超过它还没落终态 ⇒ 认定投递者已崩溃（或写终态连续失败），\n * 下一次 drain 会重新认领并重投。取值理由：一次 agent.followup/inject 是同步入队（毫秒级），\n * 5 分钟远大于任何正常投递 + 状态写盘时间，又短到不会让消息长期悬着。\n */\nexport const DELIVERING_STALE_MS = 5 * 60 * 1000\n\n/**\n * 跨进程 `.lock` 通道（读-改-写用）。**与 registrations.js:171-238 同一份实现，不复制**：\n * `withDomainsLock(domainsFile, fn)` 的语义本来就只是\"给一个文件路径，按 `<file>.lock` 用 `wx`\n * 独占（已存在必 EEXIST）+ 锁内 pid 判死接管 + `finally` 释放\"，与\"域名册\"无关，所以这里只做\n * 一次改名导出（照抄 65 行锁逻辑会分叉——同源注释挡不住分叉）。\n *\n * 契约（与 withDomainsLock 逐字相同）：回 `{ok, value, reason, error}`，**永不抛**；\n * `fn` 抛错 ⇒ `{ok:false, reason:'function-threw'}`，锁照样在 finally 释放。\n * **不可重入**：同一进程对同一个文件嵌套取锁会等到超时（15 次 × 20ms ⇒ `reason:'locked'`），\n * 所以处理函数体内**绝不允许**再取同一把锁（见 updateInboxStatus / writeDomainStateAtomic）。\n * 遗留：竞争告警文案沿用 registrations.js 的「域名册锁」字样（同一个函数；改文案要动\n * registrations.js，本次任务不允许）。\n */\nexport function withFileLock(file, fn) {\n  let locked = withDomainsLock(file, fn)\n  // Windows 实测补丁：`wx` 撞上\"对方**刚**删掉的那把锁\"时报 EPERM/EACCES，而 registrations.js 的\n  // lockContention() 只在\"此刻还看得见锁文件\"时才算争用 ⇒ 极小概率把一次正常争用误判成\n  // `lock-failed`（2×20 条队列实测遇到 1/40：EPERM … open '<inbox>.lock'）。这里只对**这一类\n  // 瞬时 IO 错**做有界重试（≤3 次 × 25ms）；锁的实现/语义仍是 registrations.js 那一份，没有第二套。\n  for (let attempt = 0; attempt < 3 && !locked.ok && locked.reason === 'lock-failed' && transientLockError(locked.error); attempt++) {\n    sleepMs(25)\n    locked = withDomainsLock(file, fn)\n  }\n  return locked\n}\n\n/** 只认 Windows 上\"抢锁时目录项正在变\"这一类瞬时错误（EPERM/EACCES/EBUSY）；别的错照实回。 */\nfunction transientLockError(error) {\n  return /EPERM|EACCES|EBUSY/i.test(String(error ?? ''))\n}\n\n/** 同步小睡（不烧 CPU）：与 registrations.js 的 sleepSync 同款，只有几行，不构成第二套锁。 */\nfunction sleepMs(ms) {\n  if (!(ms > 0)) return\n  try {\n    Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms)\n  } catch {\n    const end = Date.now() + ms\n    while (Date.now() < end) {\n      /* 兜底忙等：正常路径不会走到这里 */\n    }\n  }\n}\n\n/** JSONL read: one object per line; a broken line is skipped, never fatal. */\nexport function readInboxLines(file) {\n  let text\n  try {\n    text = fs.readFileSync(file, 'utf8')\n  } catch (error) {\n    return { records: [], existed: false, error: error && error.code === 'ENOENT' ? null : error?.message || String(error) }\n  }\n  const records = []\n  let broken = 0\n  for (const line of text.split('\\n')) {\n    const trimmed = line.trim()\n    if (!trimmed) continue\n    try {\n      const parsed = JSON.parse(trimmed)\n      if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) records.push(parsed)\n      else broken++\n    } catch {\n      broken++\n    }\n  }\n  return { records, existed: true, error: broken ? `${broken} 行读不懂（已跳过）` : null }\n}\n\nexport function loadInbox(stateDir, key) {\n  const file = inboxFileFor(stateDir, key)\n  const read = readInboxLines(file)\n  const records = read.records.map((record) => ({ ...record, key: record.key ?? String(key) }))\n  return {\n    file,\n    existed: read.existed,\n    error: read.error,\n    records,\n    total: records.length,\n    pending: records.filter((record) => record.status === INBOX_PENDING).length,\n  }\n}\n\n/** Append ONE message line. O_APPEND keeps concurrent enqueues from clobbering each other. */\nexport function appendInboxRecord(stateDir, key, record) {\n  const file = inboxFileFor(stateDir, key)\n  try {\n    fs.mkdirSync(path.dirname(file), { recursive: true })\n    fs.appendFileSync(file, JSON.stringify(record) + '\\n', 'utf8')\n    return { ok: true, file, error: null }\n  } catch (error) {\n    return { ok: false, file, error: messageOf(error) }\n  }\n}\n\n/**\n * Rewrite the whole queue atomically (status changes only; append stays the hot path).\n * **自己不加锁**：整表替换必须与调用方的\"先读\"处在同一个临界区里，所以只由\n * `updateInboxStatus()` 在 `withFileLock(<inbox file>)` 内调用。裸调本函数 = 丢更新（已复现）。\n */\nexport function rewriteInbox(stateDir, key, records) {\n  const file = inboxFileFor(stateDir, key)\n  const body = records.map((record) => JSON.stringify(record)).join('\\n') + (records.length ? '\\n' : '')\n  try {\n    // 唯一名 tmp（`<file>.<pid>.<rand>.tmp`）+ rename 重试 ≤10 次 × 10ms：与\n    // registrations.js:281-308 的 writeAtomicUnique **同款，勿各写一套**。\n    // 旧写法（固定名 `<file>.tmp` + 单次 rename）在并发重写同一队列时会 ENOENT 或\n    // 静默覆盖别人的整表（审计 P1-02 已复现）。\n    const written = writeAtomicUnique(file, body)\n    return { ok: true, file, bytes: written.bytes }\n  } catch (error) {\n    return { ok: false, file, error: messageOf(error) }\n  }\n}\n\n/**\n * pending -> delivered|failed|withdrawn, in place. Returns the updated record (or a reason).\n *\n * **锁包住整段 read-modify-write**（load → 改 status → rewrite），锁粒度＝**每个队列文件一把**\n * （`<inbox>.lock`，不搞全局一把锁：多会话互不拖慢）。只锁 rewrite 无效——两个进程各拿一份旧\n * 快照、后写覆盖先写（审计 P1-02 第二半实测：40 条只落到 31，两进程各自都回 ok:20/failed:0）。\n * 拿不到锁 ⇒ 如实回 `reason:'locked'`，**绝不绕过锁裸写**。\n */\nexport function updateInboxStatus(stateDir, key, id, status, extra) {\n  const file = inboxFileFor(stateDir, key)\n  const locked = withFileLock(file, () => {\n    const inbox = loadInbox(stateDir, key)\n    const index = inbox.records.findIndex((record) => record.id === id)\n    if (index === -1) return { ok: false, reason: 'not-found', file: inbox.file }\n    const before = inbox.records[index]\n    const next = { ...before, ...(extra || {}), status }\n    inbox.records[index] = next\n    const written = rewriteInbox(stateDir, key, inbox.records)\n    if (!written.ok) return { ok: false, reason: 'write-failed', error: written.error, file: inbox.file }\n    return { ok: true, file: inbox.file, before, record: next }\n  })\n  if (locked.ok) return locked.value\n  return { ok: false, reason: locked.reason === 'locked' ? 'locked' : 'lock-failed', error: locked.error, file }\n}\n\n/**\n * 这条记录是不是**别人留下的、已经过期的** `delivering` 租约（＝上一个投递者崩了 / 写终态连续失败）。\n *\n * 判据只有一条：`status === 'delivering'` 且 `deliveringAt` 早于 `staleMs`（默认 5 分钟）。\n * `deliveringAt` 缺失或读不懂 ⇒ 一律当**过期**（宁可重投一次，也不让消息悬着——重复优于丢消息，\n * 与 drain 既有的 statusWriteFailures 口径一致）。\n * `status` 不是 delivering ⇒ 永远 false（pending 不是\"过期租约\"，它是正经的待投）。\n */\nexport function isStaleDelivering(record, nowMs, staleMs) {\n  if (!record || record.status !== INBOX_DELIVERING) return false\n  const at = Date.parse(String(record.deliveringAt ?? ''))\n  if (!Number.isFinite(at)) return true\n  const limit = Number.isFinite(Number(staleMs)) ? Number(staleMs) : DELIVERING_STALE_MS\n  const now = Number.isFinite(Number(nowMs)) ? Number(nowMs) : Date.now()\n  return now - at >= limit\n}\n\n/**\n * F-18：**原子认领**一条记录去投递（pending ⇒ delivering），锁内 read-modify-write。\n *\n * 这是\"谁负责投这一条\"的唯一裁决点，等价于一次 CAS：投递前先把它从 `pending` 推到 `delivering`，\n * 另一路（同进程的第二次 drain、或另一个进程的下一次 drain）再进来时读到 `delivering`/终态就\n * 回 `{ok:false, reason:'not-pending'}` —— 于是**同一条消息只会被投一次**。\n *\n * `expect` 语义（有意写死，不给调用方放宽）：\n *   · `pending`            ⇒ 认领成功；\n *   · `delivering` 且过期  ⇒ 认领成功（`reclaimed:true`，接管崩溃遗留的租约）；\n *   · `delivering` 未过期  ⇒ `not-pending`（别人正在投，别抢）；\n *   · delivered/failed/withdrawn ⇒ `not-pending`（已有终态，绝不重投）。\n *\n * 拿不到锁 ⇒ 如实回 `reason:'locked' | 'lock-failed'`，**绝不绕过锁裸写**（与 updateInboxStatus 同款）。\n * 永不抛错。\n */\nexport function claimInboxDelivery(stateDir, key, id, options) {\n  const opts = options && typeof options === 'object' ? options : {}\n  const staleMs = Number.isFinite(Number(opts.staleMs)) ? Number(opts.staleMs) : DELIVERING_STALE_MS\n  const by = typeof opts.by === 'string' && opts.by ? opts.by : null\n  const nowMs = Date.now()\n  const file = inboxFileFor(stateDir, key)\n  const locked = withFileLock(file, () => {\n    const inbox = loadInbox(stateDir, key)\n    const index = inbox.records.findIndex((record) => record.id === id)\n    if (index === -1) return { ok: false, reason: 'not-found', file: inbox.file }\n    const before = inbox.records[index]\n    const reclaiming = before.status === INBOX_DELIVERING\n    if (before.status !== INBOX_PENDING && !isStaleDelivering(before, nowMs, staleMs)) {\n      return { ok: false, reason: 'not-pending', status: before.status ?? null, file: inbox.file }\n    }\n    const next = { ...before, status: INBOX_DELIVERING, deliveringAt: new Date(nowMs).toISOString(), deliveringBy: by }\n    inbox.records[index] = next\n    const written = rewriteInbox(stateDir, key, inbox.records)\n    if (!written.ok) return { ok: false, reason: 'write-failed', error: written.error, file: inbox.file }\n    return { ok: true, file: inbox.file, before, record: next, reclaimed: reclaiming }\n  })\n  if (locked.ok) return locked.value\n  return { ok: false, reason: locked.reason === 'locked' ? 'locked' : 'lock-failed', error: locked.error, file }\n}\n\n/** Every queue file in the store, keyed by lower-cased domain key (dir read, degrades). */\nexport function loadInboxes(stateDir) {\n  const dir = stateDirs(stateDir).inbox\n  const out = { dir, byKey: new Map(), error: null, degraded: [] }\n  let names = []\n  try {\n    names = fs.readdirSync(dir)\n  } catch (error) {\n    if (!error || error.code !== 'ENOENT') out.error = error?.message || String(error)\n    return out\n  }\n  for (const name of names.sort()) {\n    if (!String(name).endsWith('.jsonl')) continue\n    const read = readInboxLines(path.join(dir, name))\n    // 有读不懂的行 ⇒ 如实列出来（降级不静默），但能读的行照样用。\n    if (read.error) out.degraded.push({ file: String(name), error: read.error })\n    for (const record of read.records) {\n      if (!record || typeof record !== 'object' || Array.isArray(record)) continue\n      const key = typeof record.key === 'string' && record.key ? record.key : null\n      if (!key) continue\n      const bucket = out.byKey.get(key.toLowerCase()) || []\n      bucket.push(record)\n      out.byKey.set(key.toLowerCase(), bucket)\n    }\n  }\n  return out\n}\n\n/**\n * 一条被暂停拦下的消息 → 队列记录。**冻结**当时的 mode 与信封正文：恢复重投时逐字重放，\n * 不在恢复那一刻重新组信封（否则接收方看到的正文会随当天的措辞漂移）。\n * ⚠️ `content` 存的是**完整信封**（domainEnvelope 的产物），`source.kind` 由 domainMessage()\n *    在重投时重新组装为本插件名——**绝不是 'plugin'**（那会让接收方下一轮直接失败）。\n */\nexport function queuedRecord({ self, key, mode, envelope, text, replyTo, at, pausedByScopes }) {\n  return {\n    id: randomUUID(),\n    at: at ?? new Date().toISOString(),\n    key: String(key ?? ''),\n    // v0.4.2：`scope` 记的是**这条队列所属目标自身的 scope**（域键 ⇒ domain；会话 id ⇒ session），\n    // **不是**\"当初被哪一级拦下\"——能不能投只看它目标当下的 OR 判定（与由谁拦下无关）。\n    // 当初的拦截级别另存 `pausedByScopes`（纯取证，不参与判定）。\n    scope: queueScopeOf(key),\n    from: self?.id ?? null,\n    mode,\n    replyTo: replyTo ?? null,\n    content: String(envelope ?? ''),\n    message: String(text ?? ''),\n    status: INBOX_PENDING,\n    pausedByScopes: Array.isArray(pausedByScopes) ? pausedByScopes : [],\n    deliveredAt: null,\n    failedReason: null,\n    withdrawnAt: null,\n    withdrawnBy: null,\n  }\n}\n\n// --- derived state (算出来的；永不落盘) ---\n\n/**\n * 派生状态：**两个轴 + 生命周期**。见 CHANGELOG.md v0.4.0 段。\n * 这是全插件**唯一**一处把两个轴揉成一个对外字符串的地方——拦截判定、list 展示、\n * 回执文案都从这里取值，避免\"各处各写一套\"。\n */\nexport function domainEnvelope({ self, text, replyKey, mode, label }) {\n  const who = self?.id ?? '未知会话'\n  const domains = self?.domains?.length ? `（域 ${self.domains.join('/')}）` : ''\n  return [\n    `【${label} · 来自 ${who}${domains}】`,\n    String(text ?? ''),\n    '',\n    `（投递方式：${PLUGIN} ${mode}｜回复请用 send_to_domain，target=${replyKey}）`,\n  ].join('\\n')\n}\n\n/**\n * Build the outbound v4 user message. The ONLY construction site in this plugin.\n *\n * ⚠️ v4 格式**拒收** `kind:'plugin'`（退役的包装形态）。用它会让**接收方会话**在下一轮\n *    直接失败：\"format v4 message requires a producer-owned source kind\"\n *    （2026-10-10 实测踩到：发送方返回 delivered:true，接收方却连续两轮\"本轮运行失败\"，\n *     且因拒收发生在追加写入之前 ⇒ 接收方日志里**不留残骸**，事后极难定位）。\n *    v4 接纳规则（dsh-session-format-v3-to-v4 → message-sources.js → source()）：\n *    `kind` 必须是非空字符串、且不等于 'plugin'。这里用自己的生产者名做\"直接来源\"，\n *    并附结构化发件人，接收方可据此分辨\"会话投的\"与\"人敲的\"。\n * ⚠️ 必须交一条**完整的 v4 用户消息**：`id` + `role` + `content` + `source`，四个都要。\n *    官方入口（dsh-api-session-controller）是 `createUserMessage({content, source})`，\n *    来源 `@deepseek-ai/dsh-llm`：`{...input, role:'user', id: randomUUID()}` 再 deepFreeze。\n *    ⚠️ v0.1.1 只传了 `{content, source}` ⇒ **延期损坏**：当场能跑（内存里的消息不校验），\n *    但只要该会话被**重新加载**（重启 dsh / 重开窗口），核心 `adoptSessionEvent`\n *    就会拒收整条会话：「session event at seq N lacks an identified message」，\n *    表现为**会话打不开**（2026-10-10 实测污染 2 个会话：cc70bb51 seq 949/1019、\n *    817a3969 seq 42；2026-10-11 已按本形状修复这两个存档）。\n *    不 import `createUserMessage`：静态包新增顶层 import 一旦解析失败会让**宿主起不来**\n *    （体系 P15 红线：apply 抛错会让加载器硬失败）；改用 `node:crypto` 自造 id，产物与它逐字段一致。\n */\nexport function domainMessage({ self, envelope }) {\n  return {\n    id: randomUUID(),\n    role: 'user',\n    content: [{ type: 'text', text: envelope }],\n    source: { kind: PLUGIN, senderSessionId: self?.id ?? null },\n  }\n}\n\n// --------------------------------------------------------------- delivery (single exit)\n\n/**\n * 唯一的投递出口：send_to_domain 与 v0.3.6 的「停机通知」都走这里，**不另造一套**。\n * `mode` 三选一（其余一律按 followup 处理，与 v0.3.3 的 else 分支一致）：\n *   steer  = 插到最近 step 边界（会唤醒）\n *   inject = 只塞上下文，不唤醒、不跑模型、零成本\n *   followup = 排一条普通下一轮 prompt 并唤醒\n * payload 必须是 domainMessage() 造出的**完整 v4 用户消息**（形状警示见 domainMessage 的注释）。\n * 本函数**不吞异常**：send_to_domain 的抛错行为与 v0.3.3 逐字一致；需要降级的调用方自己包 try。\n */\nexport function deliverToAgent(agent, mode, payload) {\n  if (mode === 'steer') {\n    if (typeof agent?.steer !== 'function') return { ok: false, reason: 'steer-unsupported' }\n    agent.steer(payload)\n    return { ok: true, reason: null }\n  }\n  if (mode === 'inject') {\n    if (typeof agent?.inject !== 'function') return { ok: false, reason: 'inject-unsupported' }\n    agent.inject(payload)\n    return { ok: true, reason: null }\n  }\n  if (typeof agent?.followup !== 'function') return { ok: false, reason: 'followup-unsupported' }\n  agent.followup(payload)\n  return { ok: true, reason: null }\n}\n\n// ------------------------------------------- v0.4.0 resume: replay the queue of a paused domain\n\n/**\n * 恢复（`set_domain_state(state='active')`）时把队列里 pending 的消息按**原 mode** 重新投递。\n *\n * 三条硬规矩：\n *  ① **唤醒是\"允许尝试\"，不是\"绝不碰\"**（v0.4.1 改）：目标没有活 Agent 时先**尝试**拉活，\n *     但拉活必须**带接线**（`resolveWakeWiring` + `resumeSession`）。v0.4.0 之所以写成\"绝不 resume\"，\n *     是因为当时裸 resume（只有 `{resumeSessionId}`）拉起来的会话跑回合 100ms 内就崩\n *     （`prompt variable \"{{model}}\" has no value for this assembly (section \"deployment:persona-prefix\")`）——\n *     那是**权宜之计**，v0.4.1 把接线补上后改成：**人显式调 active 时允许尝试唤醒**；\n *     唤不起来（没接线 / resume 失败 / 拉起来也没有 Agent）⇒ 消息**保留 pending** 并如实回报。\n *     ⚠️ 这不改变「暂停的域不会被**别人**自动叫醒」：只有人显式把域设回 `active` 才走这条。\n *  ② 信封用的是**入队时冻结**的那一份，v4 形状统一由 domainMessage() 组装（source.kind 是本插件名，\n *     绝不是 'plugin'）；投递出口复用 deliverToAgent()，不另造一套。\n *  ③ 每条只落一次状态：成功 ⇒ delivered；没有对应方法/抛错 ⇒ failed（带原因）；离线 ⇒ 保持 pending。\n */\nexport const RESOLVE_FAILURE_HINTS = {\n  'missing-target': 'target 必填：域（asr / misas:asr）或会话 id（sess-xxxxxxxx 或完整 id）。',\n  'ambiguous-session-id': '这个 id 片段命中多个在线会话，本工具不猜：请改用**完整** session id 再发一次。',\n  'multiple-online-for-domain':\n    '同一域有多个在线会话：按体系口径这是违规状态，请人工裁决（并回一个负责人），本工具不擅自挑一个。',\n  unreachable: '该域/会话当前没有在线窗口（离线不排队）。可先用 list_domain_sessions 看谁在线。',\n}\n\nexport function buildSendTool(ctx, config) {\n  return tool(\n    'send_to_domain',\n    '把一条消息**投递**给一个在线会话。target 填**域**（如 asr）或**会话 id**（sess-xxxxxxxx 或完整 id）。解析顺序：① 会话 id 直接寻址；② **在任声明优先**——该域有声明且声明会话在线就投给它（matchedBy=\"declaration\"）；③ 命中声明但声明会话离线 ⇒ **不投递**，reason=\"declared-owner-offline\"，回报声明人 + 索引标注为该域且在线的人，由调用者决定；④ 该域没有声明 ⇒ 退回索引标注（matchedBy=\"index-label\"，并提示补声明）；⑤ 索引标注有多个在线 ⇒ 报警，不擅自挑一个。默认 mode=\"followup\"：等于往对方窗口里放一条普通消息，会唤醒对方开一轮；对方正在跑时用 mode=\"steer\" 做中途纠偏；mode=\"inject\" 只塞上下文不唤醒（**＝入队：不跑回合；对方要等到\"下一次有人用到它\"的那一轮才会看到**）。**目标离线不排队、明确报不可达**；要走通离线目标必须显式传 wake，且 **wake 只认完整 session id（短号 sess-xxxxxxxx 拉不活）**。dryRun=true 只解析与回报，不真投递。wake（v0.3.4 起，**默认关**＝保持「离线不排队」）：wake 传 probe 只把目标从「存档里有、但没加载」拉活并回报结果，**不投递任何消息、不跑任何一轮**（用于真机验证）；wake 传 true **已启用（v0.3.6）**＝先拉活再投，**投下去之后发生什么取决于 mode**：mode=inject ⇒ **零成本入队**（进对方 inbox、**不跑回合**，等它下一次有人用到的那一轮才被读到，可能一直没人读）；mode=followup/steer ⇒ **真唤醒并跑一轮**（有成本、当场就动）。只有显式传 wake 才生效。⚠️ **入队不持久**：未读的 inject 消息在 **dsh 退出/重启时会被整体取消**（2026-10-12 真机：三个不同会话的待读注入在同一秒全部 `canceled`、当时没有任何 turn 启动）⇒ 要保证对方真的处理，请用 `mode=followup`。⚠️⚠️ **v0.4.1 起这个坑已修（`{{model}}` 唤醒 bug）**：v0.3.4~v0.4.0 拉活时**裸传** `{resumeSessionId}`，拉起来的会话 `agent.options.model` 是 `undefined`，而 deployment persona 段写着 `{{model}}` ⇒ `turn/start` 后 **100 ms 内** `turn/end{kind:\"error\"}`、什么都没干。现在拉活会把接线一起接好：**provider/model 分级取源**（① 宿主全局默认模型 `ctx.agentDefaultModel.currentSelection()` ⇒ ② 该会话存档里最近一条 `request/header` 的 config ⇒ ③ 都没有就**不传、绝不猜**），并 best-effort 装 `setup`（模型选择 + 把该会话的 agentPreset 挂回去）。**回执如实报明用了哪条路**：`wakeWiring:{agentOptions:\"ctx.agentDefaultModel\"|\"session-header\"|\"none\", setup:\"applied\"|\"skipped\"|\"failed\", setupError}`（`wake:\"probe\"` 也带这个字段，用来预览\"真拉活会用哪条路\"）。**取不到接线时绝不裸拉**：要真跑回合的档（`followup`/`steer`，即 mode≠`inject`）**一律拒绝拉活**，回 `reason:\"no-wake-wiring\"` + hint 指替代路（`create_domain_session`，或让人在 GUI 点开那条会话）；`mode:\"inject\"` 不跑回合、`wake:\"probe\"` 只探测，两者不受这道安全门影响。这道安全门**不看 `force`**（`force` 放行的是「暂停」这条政策，不是它）。`probe` 档本来就不跑回合，所以以前也发现不了那个坑。注意：重启后「列表里有」≠「在线」，只有被「用到」的会话才有活 Agent。**v0.4.0 起「已暂停」｜v0.4.2 推广到四级**：暂停是**政策轴**（人给、可逆），`set_domain_state` 支持 `scope` 取 domain / session（主＝单会话暂停）/ project / global——域级键＝`项目:域`（**要求已有在任声明**），会话级键＝完整会话 id，项目级键＝项目名小写，全局＝唯一键 `*`（按/解都要 `confirm:true` 防误触）。判定是 **OR 叠加**：任一级被按下就拦，回执给出**全部**命中级别（`pausedScopes` / `pausedByScopes`）；**两端都查**（接收端：目标域键 / 目标会话 / 目标会话的项目 / global；发送端：本会话 / 本会话的项目 / global），**刻意不含**「本会话自己持有的域被暂停」。暂停**不改在任身份**（声明册里 sessionId 一个字节不动）。暂停期间本工具**不投递、也不替你找人顶上**：消息**落到插件自己的落盘队列**（`<stateDir>/inbox/<key>.jsonl`，一行一条，dsh 重启不丢；**入队键＝被投递目标自身的键**——目标是域就落域键、是会话 id 就落会话键），回执明说「被谁在何时按下 ＋ 已入队（可撤回）」，`reason=domain-paused`、`queued=true`（**绝不会**再笼统报 `unreachable`，也**绝不会**静默降级换人）。`wake` 也一并被拦（`wakeBlocked=domain-paused`：把已按下的目标拉活正是暂停要禁止的事）。要撤回：`withdraw_domain_message(id=…)`；要恢复：`set_domain_state(scope=…, domain=…, state=active)`——恢复时**重新评估 OR**：只重投「现在不再被任何一级压着」的 pending，仍被别的级压着的**保持 pending** 并如实报（`drain.stillPausedBy`）。真要越过暂停：传 `force=true`（回执带 `pausedOverride`，暂停状态本身不变；这道 force **不看**拉活接线那道安全门）。**边界**：插件只管插件介导的路径——人自己点开那条会话、或宿主自己 resume，插件拦不住，那正是「人工手动唤起」。',\n    {\n      target: { type: 'string', description: '域（asr / misas:asr / …）或会话 id（sess-xxxxxxxx 或完整 session id）' },\n      message: { type: 'string', description: '要投递的正文（纯文本）' },\n      mode: { type: 'string', description: 'followup（默认，普通下一轮，会唤醒对方开一轮）| steer（对方正在跑时中途纠偏）| inject（＝入队：不跑回合，消息进对方 inbox，对方\"下次有人用到它\"的那一轮才读到）' },\n      dryRun: { type: 'boolean', description: 'true = 只解析目标并回报，不真投递（默认 false）' },\n      wake: { type: 'string', description: \"v0.3.4 起可选：'' / 'false' ＝ 不叫醒（默认，保持「离线不排队」）｜'probe' ＝ 只把目标从存档拉活并回报（不投递、不跑模型；真机验证用）｜'true' ＝ **已启用（v0.3.6）**：先拉活再投；**投后行为看 mode**——inject＝零成本入队（不跑回合，对方「下次有人用到它」的那一轮才读到，可能一直没人读），followup/steer＝真唤醒跑一轮（有成本、当场就动）。**v0.4.1**：拉活会带上接线（provider/model 分级取源 + best-effort setup），回执带 `wakeWiring` 说明用的是哪条路；**取不到接线时，会真跑回合的档一律拒绝拉活**（`reason:'no-wake-wiring'`，不会裸拉——裸拉起来 100ms 内就崩），`mode:'inject'` 与 `wake:'probe'` 不受影响。另：**wake 只认完整 session id**，短号拉不活（回 no-wake-candidate）。只有显式传才生效。\" },\n      replyTo: { type: 'string', description: '可选：希望对方回复时使用的寻址键（默认自动填入本会话 id）' },\n      force: { type: 'boolean', description: 'v0.4.0 可选：默认 false。目标被**任一级**（域/主/项目/全局，OR 叠加）按下时，投递会被拦下并**入落盘队列**；显式传 force=true ＝ 明知已暂停仍要放行（照常投递、不入队，wake 也一并放行）。对**未暂停**的目标是个无害的空操作（行为与 v0.3.6 逐字一致）。' },\n    },\n    async (args, exec) => {\n      const index = loadIndex(config.indexFile)\n      // ── F-04（鲁棒性审计 2026-10-23）：**所有权敏感路径必须 fail-closed**。\n      // 旧行为：域名册读不懂时 loadDeclarations 把它折成\"空册\" ⇒ 下面的「声明优先」解析退化成\n      // matchedBy=index-label（或 unreachable），干跑/真投都照走 —— 等于册子坏了当没人在任。\n      // 现在：target 是**域名/项目形态**（要查\"谁在任\"）⇒ 一律拒绝并说明原因；`sess-…` / `session-…`\n      // 形态的 target 直接按会话 id 寻址、不做所有权判断，因此不受这条限制（否则会误伤正常直投）。\n      const ownersBook = readOwnersBook(config.domainsFile)\n      const wantedTarget = String(args.target ?? '').trim()\n      if (!ownersBook.ok && wantedTarget && !isSessionIdLike(wantedTarget)) {\n        warn(\n          `[${TRACE_ID}] 拒绝投递：域名册读不懂（${ownersBook.file}）：${ownersBook.detail}` +\n            ` ⇒ 不做所有权判断，target=${wantedTarget} 按 fail-closed 拒绝。`,\n        )\n        return {\n          delivered: false,\n          queued: false,\n          ...(args.dryRun === true ? { dryRun: true } : {}),\n          reason: 'domains-unreadable',\n          detail: ownersBook.detail,\n          target: wantedTarget,\n          declarationsFile: config.domainsFile,\n          self: describe(exec?.agent, index),\n          hint:\n            '域名册读不懂（' + ownersBook.detail + '）⇒ 本次**不做所有权判断、不投递**（旧行为会在册子坏掉时按索引标注照投，绕过在任声明）。' +\n            '请先人工修好 ' + config.domainsFile + ' 再发。文件不存在＝正常空册，不会被这条拦住；按会话 id 直投（sess-… / session-…）也不受影响。',\n        }\n      }\n      const declarations = ownersBook.ok ? ownersBook.book : loadDeclarations(config.domainsFile)\n      const duties = dutyMap(declarations)\n      const self = describe(exec?.agent, index, duties)\n\n      // ── v0.4.0/v0.4.2：暂停拦截必须发生在**叫醒之前**。wake 的用途是把离线目标拉活，而\"已暂停\"\n      // 的语义正是\"不许把它拉活\"；写在投递点就等于绕过了这条政策。\n      // v0.4.2：这里是**唯一的 OR 判定入口**，而且**两端都查**——接收端（目标域键/目标会话/\n      // 目标会话的项目/global）与发送端（本会话/本会话的项目/global）。\n      const rowsEarly = liveTopLevel(ctx, index, duties)\n      const pauseEval = pausedTargetOf(config, declarations, args.target, { ctx, rows: rowsEarly, self, index })\n      const pausedOverride = pauseEval.hits.length > 0 && args.force === true\n      const unresolvedNote = pauseEval.unresolved.length ? { unresolved: pauseEval.unresolved } : {}\n      // v0.4.2（降级不静默）：状态文件读不懂 ⇒ 不拦，但**必须**把文件名带出来（只在非空时出现，\n      // 这样\"什么都没坏\"的投递回执仍是 v0.3.6 的键集）。\n      const unreadableNote = pauseEval.unreadable.length\n        ? { unreadableStateFiles: pauseEval.unreadable }\n        : {}\n      if (pauseEval.hits.length > 0 && !pausedOverride) {\n        const pausedRows = rowsEarly\n        const queueKey = pauseEval.queueKey\n        const inbox = loadInbox(config.stateDir, queueKey)\n        const facts = pausedFactsOf({\n          config,\n          declarations,\n          ctx,\n          rows: pausedRows,\n          evaluated: pauseEval,\n          domainKey: pauseEval.domainKey,\n          fallbackKey: queueKey,\n        })\n        const wakeRawEarly = String(args.wake ?? '').trim().toLowerCase()\n        const wakeEarly =\n          wakeRawEarly === 'probe' ? 'probe' : ['true', 'yes', 'wake', 'on', '1'].includes(wakeRawEarly) ? 'on' : 'off'\n        const pausedFacts = {\n          scope: facts.scope,\n          domain: facts.domain,\n          queueKey,\n          queueScope: queueScopeOf(queueKey),\n          derivedState: facts.derivedState,\n          online: facts.online,\n          paused: true,\n          pausedAt: facts.pausedAt,\n          pausedBy: facts.pausedBy,\n          pauseNote: facts.pauseNote,\n          matchedBy: facts.matchedBy,\n          sessionId: facts.sessionId,\n          pending: inbox.pending,\n          pausedScopes: facts.pausedScopes,\n          pausedByScopes: facts.pausedByScopes,\n          pausedNotice: facts.pausedNotice,\n        }\n        warn(\n          `[${TRACE_ID_V042}] 拦截投递：target=${String(args.target ?? '')} 被 ${facts.pausedScopes.join('+')} 压着` +\n            `（${pausedScopesWords(pauseEval.hits)}）；入队键=${queueKey}，mode=${String(args.mode ?? 'followup')}，` +\n            `wake=${wakeEarly} ⇒ 不投递、不找人顶上。`,\n        )\n        // 探测档：只回答\"能不能拉活\"。已暂停 ⇒ **不拉**（要拉得显式 force），也不入队（probe 从不投递）。\n        if (wakeEarly === 'probe') {\n          return {\n            delivered: false,\n            probe: true,\n            queued: false,\n            reason: 'domain-paused',\n            target: String(args.target ?? ''),\n            ...pausedFacts,\n            ...unresolvedNote,\n          ...unreadableNote,\n            wakeBlocked: 'domain-paused',\n            // v0.4.1：probe 回执恒带 wakeWiring（这里一个都没接 ⇒ 如实报 none/skipped）。\n            wakeWiring: { agentOptions: 'none', setup: 'skipped', setupError: null },\n            woke: {\n              attempted: false,\n              sessionId: null,\n              via: 'domain-paused',\n              ok: false,\n              reason: 'domain-paused',\n              error: null,\n              ms: 0,\n              liveBefore: false,\n              liveAfter: false,\n              wakeWiring: { agentOptions: 'none', setup: 'skipped', setupError: null },\n            },\n            onlineTopLevel: pausedRows.map((row) => row.info),\n            declarationsFile: config.domainsFile,\n            self,\n            hint:\n              `探测档 + 已暂停：target 被 ${pausedScopesWords(pauseEval.hits)} 压着，` +\n              `所以**没有去拉活**——把已被按下的目标拉活正是暂停要禁止的事。要强行拉活：force=true（同时也会照常投递）。`,\n          }\n        }\n        const mode = String(args.mode ?? 'followup').toLowerCase()\n        const text = String(args.message ?? '')\n        const replyKey = String(args.replyTo ?? self.id ?? '')\n        const envelope = domainEnvelope({ self, text, replyKey, mode, label: '域间消息' })\n        const record = queuedRecord({\n          self,\n          key: queueKey,\n          mode,\n          envelope,\n          text,\n          replyTo: replyKey,\n          pausedByScopes: facts.pausedByScopes,\n        })\n        if (args.dryRun === true) {\n          return {\n            delivered: false,\n            dryRun: true,\n            queued: false,\n            reason: 'domain-paused',\n            target: String(args.target ?? ''),\n            ...pausedFacts,\n            ...unresolvedNote,\n          ...unreadableNote,\n            wakeBlocked: wakeEarly === 'off' ? null : 'domain-paused',\n            wouldQueue: {\n              key: queueKey,\n              scope: queueScopeOf(queueKey),\n              domain: facts.domain,\n              mode,\n              envelope,\n              from: self.id ?? null,\n              withdrawable: true,\n              file: inbox.file,\n            },\n            declarationsFile: config.domainsFile,\n            self,\n            hint:\n              `演练：**没有投递、也没有写队列**。真跑的话这条消息会以 pending 落进 ${inbox.file}（入队键＝${queueKey}），` +\n              `可用 withdraw_domain_message 撤回；恢复要先解开**按着它的每一级**（见 pausedByScopes），` +\n              `恢复时会重新评估 OR。`,\n          }\n        }\n        const enqueued = appendInboxRecord(config.stateDir, queueKey, record)\n        if (!enqueued.ok) {\n          return {\n            delivered: false,\n            queued: false,\n            reason: 'queue-write-failed',\n            error: enqueued.error,\n            target: String(args.target ?? ''),\n            ...pausedFacts,\n            ...unresolvedNote,\n          ...unreadableNote,\n            wakeBlocked: wakeEarly === 'off' ? null : 'domain-paused',\n            queueFile: enqueued.file,\n            declarationsFile: config.domainsFile,\n            self,\n            hint:\n              `target 已被按下（${pausedScopesWords(pauseEval.hits)}），本该把这条消息落盘入队，` +\n              `但**写队列失败**（${enqueued.error}）⇒ 消息**没有入队、也没有投递**。请修好磁盘权限后重试；` +\n              `本次什么都没落地，别以为它排上了。`,\n          }\n        }\n        return {\n          delivered: false,\n          queued: true,\n          reason: 'domain-paused',\n          target: String(args.target ?? ''),\n          ...pausedFacts,\n          ...unresolvedNote,\n          ...unreadableNote,\n          wakeBlocked: wakeEarly === 'off' ? null : 'domain-paused',\n          queue: {\n            id: record.id,\n            at: record.at,\n            mode,\n            key: queueKey,\n            scope: queueScopeOf(queueKey),\n            domain: facts.domain,\n            status: INBOX_PENDING,\n            pending: inbox.pending + 1,\n            total: inbox.total + 1,\n            file: enqueued.file,\n            withdrawable: true,\n            withdrawTool: 'withdraw_domain_message',\n          },\n          declarationsFile: config.domainsFile,\n          self,\n          hint: pausedSendHint(\n            { ...facts, key: facts.domain ?? queueKey, queueKey, pending: inbox.pending + 1, pausedHits: pauseEval.hits },\n            record.id,\n          ),\n        }\n      }\n\n      // ── v0.4.0：force=true + 已暂停 ＝ 显式放行。只在此时出现；未暂停的域是空对象\n      // （保证「非暂停域行为与 v0.3.6 逐字一致」——连一个键都不多）。\n      const overrideNote = pausedOverride\n        ? {\n            pausedOverride: true,\n            pausedOverrideDomain: primaryPauseHit(pauseEval.hits)?.key ?? pauseEval.queueKey,\n            pausedOverrideScopes: pausedScopesOf(pauseEval.hits),\n            pausedOverrideHint:\n              `⚠️ 明知目标被 ${pausedScopesWords(pauseEval.hits)} 压着，你传了 force=true ⇒ 本次按你的意思**放行**` +\n              `（照常投递/拉活，**不入队**）。暂停本身没有被解除：要恢复请把**按着它的每一级**都解开` +\n              `（见 pausedByScopes；域级＝set_domain_state(domain=…, state='active')，global＝` +\n              `set_domain_state(scope='global', state='active', confirm=true)）。`,\n          }\n        : {}\n\n      // ── v0.3.4：叫醒必须发生在**解析之前**。原因：resolveTarget 只在\"在线行\"里找目标，\n      // 离线会话连\"目标\"都算不上（直接 unreachable），声明负责人离线也直接\n      // declared-owner-offline —— 把叫醒写在投递点等于死代码。\n      const wakeRaw = String(args.wake ?? '').trim().toLowerCase()\n      const wakeMode = wakeRaw === 'probe' ? 'probe' : ['true', 'yes', 'wake', 'on', '1'].includes(wakeRaw) ? 'on' : 'off'\n      // v0.4.1 安全门：只有「真会跑回合」的档才强制要接线（inject 不跑回合、probe 不投递）。\n      // mode 的归一化口径与 deliverToAgent 一致：steer=steer、inject=inject、其余一律 followup（跑回合）。\n      const modeEarly = String(args.mode ?? 'followup').toLowerCase()\n      const wakeRunsTurn = modeEarly !== 'inject'\n      // v0.4.2：复用暂停判定那一刻的在线行（同一轮里没有任何东西会改变\"谁在线\"，\n      // 除非下面真的拉活成功——那时会重取）。\n      let rows = rowsEarly\n      let woke = null\n      if (wakeMode !== 'off') {\n        const candidate = offlineCandidateId(args.target, declarations)\n        if (candidate.id) {\n          const wiring = await resolveWakeWiring(ctx, candidate.id)\n          woke = await resumeSession(ctx, candidate.id, wiring, {\n            requireWiring: wakeMode === 'on' && wakeRunsTurn,\n          })\n          woke.via = candidate.why\n          // 拉活成功才值得重取在线列表（重取本身是只读但会创建对象）。\n          if (woke.ok && !woke.liveBefore) rows = liveTopLevel(ctx, index, duties)\n        } else {\n          woke = {\n            attempted: false,\n            sessionId: null,\n            via: candidate.why,\n            ok: false,\n            reason: 'no-wake-candidate',\n            error: null,\n            ms: 0,\n            liveBefore: false,\n            liveAfter: false,\n            wakeWiring: { agentOptions: 'none', setup: 'skipped', setupError: null },\n          }\n        }\n      }\n\n      // ── v0.4.1：要真跑回合、却拼不出 provider/model ⇒ **明确拒绝拉活**，一次 resume 都不调。\n      // （`force` 放行的是「暂停」这条政策，不是这道安全门：裸拉起来 100ms 后就崩，放行等于骗人。）\n      if (wakeMode === 'on' && woke && woke.reason === 'no-wake-wiring') {\n        warn(\n          `[${TRACE_ID_V041}] 拒绝拉活：${String(args.target ?? '')} ⇒ 候选=${woke.sessionId}，mode=${modeEarly}，` +\n            `接线取源=agentOptions:none；裸 resume 会在 100ms 内崩（{{model}} 无值），所以不拉。`,\n        )\n        return {\n          delivered: false,\n          reason: 'no-wake-wiring',\n          target: String(args.target ?? ''),\n          mode: modeEarly,\n          woke,\n          wakeWiring: woke.wakeWiring,\n          onlineTopLevel: rows.map((row) => row.info),\n          declarationsFile: config.domainsFile,\n          ...overrideNote,\n          ...unresolvedNote,\n          ...unreadableNote,\n          self,\n          hint:\n            `**没有拉活**：这次 mode='${modeEarly}' 真会跑回合，而拉活必须先接好 provider/model —— ` +\n            `否则裸 resume 起来的会话 100 ms 内就会崩（真机错误一字不差：prompt variable \"{{model}}\" has no ` +\n            `value for this assembly (section \"deployment:persona-prefix\")）。这次两条取源都是空的：` +\n            `① 宿主全局默认模型（ctx.agentDefaultModel.currentSelection）取不到；` +\n            `② 该会话存档里也读不到最近一条 request/header 的 config。` +\n            `**不能猜一个模型硬按上去** ⇒ 按规矩拒绝（拉起来也是白拉，还会把那条会话搞成\"看起来在线、其实跑不动\"）。` +\n            `仍然可用的两条路：mode='inject'（只入队、不跑回合，可以拉）、wake='probe'（只探测、不投递）。` +\n            `要真派活请改用 create_domain_session（宿主建的会话装配完整），或让人在 GUI 点开 ` +\n            `${shortId(woke.sessionId) || woke.sessionId || '那条会话'}。`,\n        }\n      }\n\n      const resolved = resolveTarget(rows, args.target, declarations, ctx, index)\n\n      if (wakeMode === 'probe') {\n        // 探测档：只回报\"能不能把它从存档拉活\"，**不投递任何消息、不跑任何一轮**。\n        // v0.4.1：probe **不需要接线**（不跑回合）⇒ 安全门对它不生效；但仍然如实报出\n        // `wakeWiring` —— 这正是\"真拉活那天会用哪条路\"的预览。\n        const probeWiring = woke?.wakeWiring ?? { agentOptions: 'none', setup: 'skipped', setupError: null }\n        return {\n          delivered: false,\n          probe: true,\n          target: String(args.target ?? ''),\n          woke,\n          wakeWiring: probeWiring,\n          liveAfter: Boolean(woke && woke.liveAfter),\n          resolved: resolved.ok ? resolved.row.info : null,\n          resolveReason: resolved.ok ? null : resolved.reason,\n          onlineTopLevel: rows.map((row) => row.info),\n          declarationsFile: config.domainsFile,\n          ...overrideNote,\n          ...unresolvedNote,\n          ...unreadableNote,\n          self,\n          hint:\n            woke && woke.ok\n              ? `探测档：已从存档把 ${woke.sessionId} 拉活（**没有投递任何消息、没有跑任何一轮**）。` +\n                `接线取源 agentOptions=${probeWiring.agentOptions}、setup=${probeWiring.setup}。` +\n                `接着看：它是否出现在 onlineTopLevel 里、它的存档有没有新增 turn（新增＝拉活会自己干活，那样就得改成\"拉活后再投\"的策略）。`\n              : `探测档：没能拉活（${woke ? woke.reason : 'unknown'}${woke && woke.via ? '，判定依据=' + woke.via : ''}）。常见原因：这条不是顶层会话（子代理会话会被核心直接拒：ApiSessionSubagentOwnership）、target 不是完整会话 id（短号无法直接 resume）、或它真的不存在。`,\n        }\n      }\n\n      if (!resolved.ok) {\n        const base = {\n          delivered: false,\n          reason: resolved.reason,\n          ...overrideNote,\n          ...unresolvedNote,\n          ...unreadableNote,\n          self,\n        }\n        if (resolved.reason === 'declared-owner-offline') {\n          return {\n            ...base,\n            declaredOwner: resolved.declaredOwner,\n            otherOnlineWithIndexLabel: resolved.otherOnlineWithIndexLabel,\n            onlineTopLevel: resolved.candidates ?? [],\n            declarationsFile: config.domainsFile,\n            hint:\n              '该域的在任声明负责人当前不在线（离线不排队，本工具不替你挑人）。这里只回报「谁在任」+「索引标注恰好是这个域、当前在线的人」：要投给谁由你决定——可用 send_to_domain(target=<会话id>) 直投，或先 claim_domain(force:true) 交接。',\n          }\n        }\n        if (resolved.reason === 'ambiguous-declarations') {\n          return {\n            ...base,\n            declarations: resolved.declarations,\n            onlineTopLevel: resolved.candidates ?? [],\n            declarationsFile: config.domainsFile,\n            hint: '同名域有多条在任声明：请用「项目:域」的完整写法指定是哪一个（本工具不猜）。',\n          }\n        }\n        return {\n          ...base,\n          onlineTopLevel: resolved.candidates ?? [],\n          hint: RESOLVE_FAILURE_HINTS[resolved.reason] ?? null,\n        }\n      }\n\n      const targetInfo = resolved.row.info\n      const text = String(args.message ?? '')\n      const replyKey = String(args.replyTo ?? self.id ?? '')\n      const mode = String(args.mode ?? 'followup').toLowerCase()\n      // Shared builder (v0.3): create_domain_session builds its startup message the same way.\n      const envelope = domainEnvelope({ self, text, replyKey, mode, label: '域间消息' })\n      const resolution = { matchedBy: resolved.matchedBy }\n      if (resolved.declaration) resolution.declaration = resolved.declaration\n      if (resolved.hint) resolution.hint = resolved.hint\n\n      if (args.dryRun === true) {\n        return {\n          delivered: false,\n          dryRun: true,\n          wouldDeliverTo: targetInfo,\n          ...resolution,\n          mode,\n          ...overrideNote,\n          ...unresolvedNote,\n          ...unreadableNote,\n          self,\n          envelope,\n        }\n      }\n\n      // 竞态兜底：解析时在线、投递那一刻已关。开了叫醒（wake='true'）就再拉一次。\n      let agent = ctx?.agents?.get?.(targetInfo.id) ?? null\n      let wokeAtDelivery = null\n      if (!agent && wakeMode === 'on') {\n        // v0.4.1：这条兜底路也要接线（否则同样裸拉 ⇒ 100ms 崩），并且同样过安全门。\n        const wiringAtRace = await resolveWakeWiring(ctx, targetInfo.id)\n        wokeAtDelivery = await resumeSession(ctx, targetInfo.id, wiringAtRace, { requireWiring: wakeRunsTurn })\n        if (wokeAtDelivery.ok) agent = ctx?.agents?.get?.(targetInfo.id) ?? null\n      }\n      if (!agent) {\n        // ⚠️ 没开叫醒时返回体必须与 v0.3.3 逐字一致（`woke` 只在开了叫醒时才出现）。\n        return {\n          delivered: false,\n          reason: 'unreachable-race',\n          target: targetInfo,\n          ...(wokeAtDelivery ? { woke: wokeAtDelivery } : {}),\n          ...overrideNote,\n          ...unresolvedNote,\n          ...unreadableNote,\n          self,\n          hint: wokeAtDelivery\n            ? wokeAtDelivery.reason === 'no-wake-wiring'\n              ? '解析时它还在线，投递那一刻已经没了；本来要拉活，但**拼不出 provider/model**（接线取源 none）⇒ 按规矩没有裸拉（裸拉起来 100 ms 内就崩）。离线不排队：mode=inject 可以拉、或改用 create_domain_session / 让人在 GUI 点开那条会话。'\n              : '解析时它还在线，投递那一刻已经没了，再拉一次也没拉起来（原因见 woke）；离线不排队，请重试或换人。'\n            : '解析时它还在线，真正投递那一刻窗口已关（竞态）；离线不排队，请重试或换人。',\n        }\n      }\n\n      // Shape lives in exactly one place - see the v4 warnings on domainMessage().\n      const payload = domainMessage({ self, envelope })\n\n      // v0.3.6: 投递出口抽成共享 helper（deliverToAgent），停机通知走同一个 inject 分支。\n      const attempt = deliverToAgent(agent, mode, payload)\n      if (!attempt.ok) {\n        return {\n          delivered: false,\n          reason: attempt.reason,\n          target: targetInfo,\n          ...overrideNote,\n          ...unresolvedNote,\n          ...unreadableNote,\n          self,\n        }\n      }\n\n      return {\n        delivered: true,\n        mode,\n        ...resolution,\n        target: targetInfo,\n        // v0.4.1: 只在这一轮**真的拉过活**（liveBefore=false 且成功）时才多这个键 ——\n        // 目标本来就在线时，回执与 v0.3.6 逐字一致（一个键都不多）。\n        ...(woke && woke.attempted && !woke.liveBefore ? { woke } : {}),\n        ...(wokeAtDelivery ? { wokeAtDelivery } : {}),\n        ...overrideNote,\n        ...unresolvedNote,\n          ...unreadableNote,\n        self,\n        note: '已接受进对方 inbox（本调用只返回\"已送达\"，不会返回对方的回复；对方会另发一条消息回来）。',\n      }\n    },\n  )\n}\n\n// ── v0.3.3 helpers: 标题 + 权限档（两个服务都按 v0.3.2 的同一套契约取用：不注入、调用时解析、\n//    缺失即降级、永不抛错。依据见 CHANGELOG.md v0.3.3 段）。\n"
    },
    {
      "path": "plugins/dsh-domain-bridge/lib/core/pause.js",
      "content": "/**\n * dsh-domain-bridge — the four-level pause policy, its persisted state records and queue drain/withdraw.\n *\n * Split out of the single-file lib/bridge.js in v0.6.3 (pure move: no behaviour change).\n * The package entry point stays lib/bridge.js, which re-exports this module.\n */\n\nimport fs from 'node:fs'\nimport path from 'node:path'\nimport { TRACE_ID_V040, TRACE_ID_V041, TRACE_ID_V042, SCOPE_DOMAIN, SCOPE_SESSION, SCOPE_PROJECT, SCOPE_GLOBAL, PAUSE_SCOPES, GLOBAL_KEY, SCOPE_ALIASES, STATE_POLICY_PAUSED, STATE_POLICY_ACTIVE, STATE_ONLINE_ACTIVE, STATE_ONLINE_PAUSED, STATE_OFFLINE_ACTIVE, STATE_OFFLINE_PAUSED, STATE_TERMINATED, DERIVED_STATE_LEGEND, loadIndex, emptyIndex, shortId, describe, liveTopLevel, dutyMap, isSessionOnline, stateDirs, stateFileFor, queueScopeOf, isFullSessionId, isSessionIdLike, messageOf } from './shared.js'\nimport { warn, tool } from './tools.js'\n// 唯一名 tmp + rename 重试的写盘通道：**复用 registrations.js 的那一份**（勿在本模块另写一套）。\n// 固定名 `<file>.tmp` 在两进程并发写同一状态文件时会静默丢写（审计 P1-02 已复现：期望 120 实际 70）。\nimport { writeAtomicUnique } from './registrations.js'\nimport { INBOX_PENDING, INBOX_DELIVERED, INBOX_FAILED, INBOX_WITHDRAWN, INBOX_DELIVERING, DELIVERING_STALE_MS, loadInbox, updateInboxStatus, claimInboxDelivery, isStaleDelivering, loadInboxes, domainMessage, deliverToAgent, withFileLock } from './messaging.js'\nimport { loadDeclarations, readDeclarationsForWrite, checkName, projectFromCwd, resolveDomainKeyForState, matchDeclaration, resolveTarget } from './declaration.js'\nimport { clipToBytes, liveAgentOf, resolveWakeWiring, resumeSession } from './session-factory.js'\n\nexport function emptyDomainState(file) {\n  return {\n    scope: null,\n    key: null,\n    paused: false,\n    pausedAt: null,\n    pausedBy: null,\n    note: null,\n    resumedAt: null,\n    resumedBy: null,\n    terminatedAt: null,\n    terminatedBy: null,\n    updatedAt: null,\n    file: file ?? null,\n    existed: false,\n    error: null,\n  }\n}\n\nexport function normalizeDomainState(raw, file) {\n  const out = emptyDomainState(file)\n  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return out\n  out.scope = typeof raw.scope === 'string' && raw.scope ? raw.scope : null\n  out.key = typeof raw.key === 'string' && raw.key ? raw.key : null\n  out.paused = raw.paused === true\n  out.pausedAt = typeof raw.pausedAt === 'string' ? raw.pausedAt : null\n  out.pausedBy = typeof raw.pausedBy === 'string' ? raw.pausedBy : null\n  out.note = typeof raw.note === 'string' ? raw.note : null\n  out.resumedAt = typeof raw.resumedAt === 'string' ? raw.resumedAt : null\n  out.resumedBy = typeof raw.resumedBy === 'string' ? raw.resumedBy : null\n  out.terminatedAt = typeof raw.terminatedAt === 'string' ? raw.terminatedAt : null\n  out.terminatedBy = typeof raw.terminatedBy === 'string' ? raw.terminatedBy : null\n  out.updatedAt = typeof raw.updatedAt === 'string' ? raw.updatedAt : null\n  out.existed = true\n  return out\n}\n\n/**\n * Read-only load of ONE domain's state record. Missing file / unreadable / malformed all degrade to\n * \"no state record\" (paused:false) **without throwing** - a broken optional store must never block\n * delivery. `error` is reported so a caller can tell \"never stored\" from \"store is broken\".\n */\n/**\n * Read-only load of ONE state record, for one (key, scope) pair. Missing file / unreadable /\n * malformed all degrade to \"no state record\" (paused:false) **without throwing** - a broken\n * optional store must never block delivery. `error` is reported so a caller can tell \"never\n * stored\" from \"store is broken\".\n * `scope` 缺省＝按键形状判（见 queueScopeOf）；显式 scope 一律优先（global 的键 `*` 必须显式给）。\n */\nexport function loadDomainState(stateDir, key, scope) {\n  const real = String(scope ?? '').trim().toLowerCase() || queueScopeOf(key)\n  const file = stateFileFor(stateDir, key, real)\n  let raw\n  try {\n    raw = fs.readFileSync(file, 'utf8')\n  } catch (error) {\n    if (error && error.code === 'ENOENT') return emptyDomainState(file)\n    return { ...emptyDomainState(file), error: error?.message || String(error) }\n  }\n  try {\n    const parsed = JSON.parse(raw)\n    const record = normalizeDomainState(parsed, file)\n    record.key = record.key ?? String(key ?? '')\n    record.scope = record.scope ?? real\n    return record\n  } catch (error) {\n    return { ...emptyDomainState(file), existed: true, error: error?.message || String(error) }\n  }\n}\n\n/** 状态记录里的**真实** scope：缺字段＝v0.4.0/v0.4.1 写下的域级记录（那时只有域级）。 */\nexport function scopeOfRecord(record) {\n  const raw = String(record?.scope ?? '').trim().toLowerCase()\n  return PAUSE_SCOPES.includes(raw) ? raw : SCOPE_DOMAIN\n}\n\n/** Every state record in the store, keyed by lower-cased key (legacy readers) + (scope,key) 精确表. */\nexport function loadDomainStates(stateDir) {\n  const out = {\n    dir: stateDirs(stateDir).domains,\n    byKey: new Map(),\n    // v0.4.2：`<scope>\\u0000<key 小写>` -> 记录。跨 scope 的**同名字符串**必须能分开取，\n    // 否则\"哪个 scope 被按下\"会被另一级的记录顶掉。\n    byScopeKey: new Map(),\n    entries: [],\n    error: null,\n    unreadable: [],\n  }\n  let names = []\n  try {\n    names = fs.readdirSync(out.dir)\n  } catch (error) {\n    if (!error || error.code !== 'ENOENT') out.error = error?.message || String(error)\n    return out\n  }\n  for (const name of names.sort()) {\n    if (!String(name).endsWith('.json')) continue\n    const file = path.join(out.dir, name)\n    let parsed\n    try {\n      parsed = JSON.parse(fs.readFileSync(file, 'utf8'))\n    } catch {\n      // 一份读不懂的状态文件不该让整店崩掉，但**也不能静默**：如实列进 unreadable，\n      // 由 list_* 的 domainState.unreadableDegraded 暴露出来（降级不静默，是这插件的一贯口径）。\n      out.unreadable.push(String(name))\n      continue\n    }\n    const record = normalizeDomainState(parsed, file)\n    if (!record.key) {\n      out.unreadable.push(String(name))\n      continue\n    }\n    const scope = scopeOfRecord(record)\n    record.scope = scope\n    out.entries.push(record)\n    const lower = String(record.key).toLowerCase()\n    if (!out.byKey.has(lower)) out.byKey.set(lower, record)\n    out.byScopeKey.set(scope + '\\u0000' + lower, record)\n  }\n  return out\n}\n\n/**\n * 只为这批候选键读记录（**不扫全目录**）：send / create / set / drain 这些热路径用。\n * 返回的形状与 loadDomainStates 一致（byKey / byScopeKey / entries / unreadable），\n * 这样 OR 判定与 list 路径共用同一套查找（lookupPauseRecord）。\n */\nexport function loadPauseStateMap(config, candidates) {\n  const byKey = new Map()\n  const byScopeKey = new Map()\n  const entries = []\n  const unreadable = []\n  const seen = new Set()\n  for (const candidate of candidates || []) {\n    if (!candidate || !candidate.key) continue\n    const scope = String(candidate.scope ?? '').trim().toLowerCase() || SCOPE_DOMAIN\n    const lower = String(candidate.key).toLowerCase()\n    const cursor = scope + '\\u0000' + lower\n    if (seen.has(cursor)) continue\n    seen.add(cursor)\n    const record = loadDomainState(config.stateDir, candidate.key, scope)\n    // 记录里的 scope 与它所属的 scope 不一致（手改过文件）⇒ 不当命中，也不静默。\n    if (record.existed && record.scope && String(record.scope).toLowerCase() !== scope) {\n      unreadable.push({\n        scope,\n        key: candidate.key,\n        file: record.file,\n        error: `记录里的 scope（${record.scope}）与它所属的 scope（${scope}）不一致（按\"不是这条记录\"处理）`,\n      })\n      continue\n    }\n    if (record.error) unreadable.push({ scope, key: candidate.key, file: record.file, error: record.error })\n    byScopeKey.set(cursor, record)\n    if (!byKey.has(lower)) byKey.set(lower, record)\n    if (record.existed) entries.push(record)\n  }\n  return { byKey, byScopeKey, entries, unreadable, error: null }\n}\n\n/**\n * Read-modify-write one state record under BOTH guarantees:\n *   ① 跨进程互斥：整段\"读旧记录 → 合并 patch → 写新记录\"在 `withFileLock(<file>.lock)` 里\n *      （锁粒度＝每个状态文件一把；`withFileLock` 就是 registrations.js 的 `withDomainsLock`，\n *      不重造）。⚠️ 锁**不可重入**——临界区里不要再取同一把锁。\n *   ② 原子落盘：UNIQUE tmp name (`<file>.<pid>.<rand>.tmp`) + rename with retries, through\n *      `writeAtomicUnique()` from registrations.js (one implementation, not a second copy).\n * A file that exists but cannot be parsed ABORTS the write - never overwrite somebody's state\n * blindly. `patch` keys are merged over the existing record（合并发生在锁内 ⇒ 看到的是最新记录）。\n */\nexport function writeDomainStateAtomic(stateDir, key, patch, scope) {\n  const real = String(scope ?? '').trim().toLowerCase() || queueScopeOf(key)\n  const file = stateFileFor(stateDir, key, real)\n  // 锁粒度＝**每个状态文件一把**（`<file>.lock`），包住\"读旧记录 → 合并 patch → 写新记录\"整段。\n  // 只锁写那一步没用：两进程都拿旧记录打底、后写覆盖先写 ⇒ 静默丢字段（审计 P1-02 第二半：\n  // 2×60 次只落到 73，两边各自都回 ok:60/failed:0）。\n  // 锁＝messaging.js 的 withFileLock（与 registrations.js 同一份实现）；**不可重入**，\n  // 所以临界区本体 applyDomainStateWrite() 里不得再取锁。\n  const locked = withFileLock(file, () => applyDomainStateWrite({ file, real, key, patch }))\n  if (locked.ok) return locked.value\n  return { ok: false, reason: locked.reason === 'locked' ? 'locked' : 'lock-failed', error: locked.error, file }\n}\n\n/** `writeDomainStateAtomic()` 的临界区本体：**只许在持锁时调用**（它自己不加锁）。 */\nfunction applyDomainStateWrite({ file, real, key, patch }) {\n  let existing = new emptyDomainState(file)\n  let raw\n  try {\n    raw = fs.readFileSync(file, 'utf8')\n  } catch (error) {\n    if (!error || error.code !== 'ENOENT') {\n      return { ok: false, reason: 'state-read-failed', error: error?.message || String(error), file }\n    }\n  }\n  if (raw !== undefined) {\n    try {\n      existing = normalizeDomainState(JSON.parse(raw), file)\n    } catch (error) {\n      return { ok: false, reason: 'state-file-unreadable', error: error?.message || String(error), file }\n    }\n    // 防御：文件里的 scope 与本次要写的 scope 不一致 ⇒ **绝不用别人的记录打底**。\n    // （v0.4.2 起非域级记录各有自己的文件名，正常路径撞不上；这条只挡手改/旧命名残留。）\n    if (existing.existed && existing.scope && String(existing.scope).toLowerCase() !== real) {\n      return {\n        ok: false,\n        reason: 'scope-conflict',\n        error: `记录里的 scope（${existing.scope}）与本次要写的 scope（${real}）不一致`,\n        file,\n      }\n    }\n  }\n  const next = {\n    ...existing,\n    schemaVersion: 1,\n    scope: real,\n    key: String(key),\n    ...patch,\n    // 运行期字段一律不落盘（lossless 输出用的，不是数据）。\n    file: undefined,\n    existed: undefined,\n    error: undefined,\n    updatedAt: new Date().toISOString(),\n  }\n  const body = JSON.stringify(next, null, 2) + '\\n'\n  try {\n    // 唯一名 tmp（`<file>.<pid>.<rand>.tmp`）+ rename 重试 ≤10 次 × 10ms：与\n    // registrations.js:281-308 的 writeAtomicUnique **同款，勿各写一套**。\n    // 旧写法（固定名 `<file>.tmp` + 单次 rename）在两进程并发写同一状态文件时会 ENOENT 或\n    // 静默覆盖别人的写（审计 P1-02/P2-01 已复现：120 次自增只落到 70）。\n    const written = writeAtomicUnique(file, body)\n    return { ok: true, file, bytes: written.bytes, record: normalizeDomainState(next, file) }\n  } catch (error) {\n    return { ok: false, reason: 'write-failed', error: messageOf(error), file }\n  }\n}\n\n// --- persisted inbox (the queue that makes \"paused but queued\" survive a dsh restart) ---\n\nexport function deriveDomainState({ hasDeclaration, online, paused, terminated }) {\n  if (hasDeclaration) {\n    if (online) return paused ? STATE_ONLINE_PAUSED : STATE_ONLINE_ACTIVE\n    return paused ? STATE_OFFLINE_PAUSED : STATE_OFFLINE_ACTIVE\n  }\n  if (terminated) return STATE_TERMINATED\n  return null\n}\n\n/**\n * 一个 `项目:域` 的完整快照（只读；域名册 + 状态目录 + 队列，三处都降级）。\n * 派生状态只在这里算，调用方只管展示。\n *\n * v0.4.2：`paused` / `state` 变成**有效暂停**（OR 叠加：域级 / 它负责人的会话级 / 它的项目级 / global\n * 任一级按下都算）——这正是「会话行/声明行的派生状态必须体现所有级命中」那条硬要求。\n * 四级里只有域级记录时，结果与 v0.4.1 **逐字相同**（所以旧用例一个字节都不用改）。\n * `pausedAt/pausedBy/pauseNote` 优先给**域级自己那条记录**（旧字段语义不变），域级没记录时退回\n * 第一条命中记录，让\"谁按下的\"永远有人可指；**全部**命中在 `pausedScopes` / `pausedByScopes` 里。\n */\nexport function domainSnapshot({ declarations, states, inboxes, ctx, rows, key, inbox, hits }) {\n  const lower = String(key ?? '').toLowerCase()\n  const entry = declarations?.byKey?.get(lower) || null\n  const evaluated = Array.isArray(hits)\n    ? { hits }\n    : pauseHitsOfMap(states, pauseCandidatesForDomain(declarations, key, {}).concat(pauseCandidatesGlobal()))\n  const hitList = evaluated.hits || []\n  const own = lookupPauseRecord(states, SCOPE_DOMAIN, key) || null\n  const spokes = own && own.existed ? own : hitList[0]?.record ?? own\n  const queueRaw = inbox || (inboxes ? inboxes.byKey.get(lower) : null) || []\n  const queue = Array.isArray(queueRaw) ? queueRaw : queueRaw.records || []\n  const pending = queue.filter((item) => item.status === INBOX_PENDING).length\n  const sessionId = entry?.sessionId ?? null\n  const online = entry ? isSessionOnline(ctx, sessionId, rows) : false\n  const paused = hitList.length > 0\n  const terminatedAt = own?.terminatedAt ?? spokes?.terminatedAt ?? null\n  return {\n    key: entry?.key ?? own?.key ?? String(key ?? ''),\n    scope: SCOPE_DOMAIN,\n    inBook: Boolean(entry),\n    sessionId,\n    online,\n    paused,\n    // 该域**自己那一级**（scope=domain）的记录是否被按下（\"我这一级现在是什么\"）。\n    scopePaused: Boolean(own?.paused),\n    pausedAt: spokes?.pausedAt ?? null,\n    pausedBy: spokes?.pausedBy ?? null,\n    pauseNote: spokes?.note ?? null,\n    resumedAt: own?.resumedAt ?? null,\n    terminatedAt,\n    terminatedBy: own?.terminatedBy ?? null,\n    state: entry\n      ? deriveDomainState({ hasDeclaration: true, online, paused, terminated: Boolean(terminatedAt) })\n      : own || spokes\n        ? deriveDomainState({ hasDeclaration: false, online: false, paused, terminated: Boolean(terminatedAt) })\n        : null,\n    pending,\n    queuedTotal: queue.length,\n    // v0.4.2：四级命中全量（OR）——\"是哪几级按下的\"必须一眼看得出（不许只报一个）。\n    pausedScopes: pausedScopesOf(hitList),\n    pausedByScopes: pausedByScopesOf(hitList),\n  }\n}\n\n/** 命中集合 ⇒ scope 名（排序去重）——对外一律用这个表达\"哪几级按着\"。 */\nexport function pausedScopesOf(hits) {\n  return [...new Set((hits || []).map((hit) => String(hit.scope)))].sort()\n}\n\n/** 命中集合 ⇒ 逐条\"谁在何时按下\"（含 via / 发送端还是接收端），**全量**、不许只报一个。 */\nexport function pausedByScopesOf(hits) {\n  return (hits || []).map((hit) => ({\n    scope: hit.scope,\n    key: String(hit.key ?? ''),\n    via: hit.via ?? null,\n    side: hit.side ?? null,\n    pausedAt: hit.record?.pausedAt ?? null,\n    pausedBy: hit.record?.pausedBy ?? null,\n    pauseNote: hit.record?.note ?? null,\n  }))\n}\n\n/** 一句话说清\"被哪几级按着\"（回执/hint 共用）。 */\nexport function pausedScopesWords(hits) {\n  return (hits || [])\n    .map((hit) => {\n      const who = shortId(hit.record?.pausedBy) || hit.record?.pausedBy || '（未记录是谁按下的）'\n      const at = hit.record?.pausedAt ?? '（未记录时间）'\n      return `${scopeWords(hit.scope)}「${hit.key}」（${hit.via ?? 'unknown'}；${who} 于 ${at} 按下）`\n    })\n    .join('；')\n}\n\n/** scope 的中文说法（机器面一律四个英文字面量）。 */\nexport function scopeWords(scope) {\n  if (scope === SCOPE_SESSION) return '主（单会话暂停）'\n  if (scope === SCOPE_PROJECT) return '项目'\n  if (scope === SCOPE_GLOBAL) return '全局'\n  return '域'\n}\n\n/** 大白话：谁、在什么时候按下的（\"其他会话知道它的状态\"就靠这个）。 */\nexport function pausedWhoWords(snapshot) {\n  const who = shortId(snapshot?.pausedBy) || snapshot?.pausedBy || '（未记录是谁按下的）'\n  const at = snapshot?.pausedAt ?? '（未记录时间）'\n  const note = String(snapshot?.pauseNote ?? '').trim()\n  return `${who} 于 ${at} 按下${note ? `（note：「${clipToBytes(note, 60)}」）` : ''}`\n}\n\n/** list_* 共用的 `domainState` 段：四级作用域 + 五态字典 + 已终结（墓碑）清单 + 四级在案记录。 */\nexport function domainStateSection(config, declarations, states, inboxes, opts) {\n  const dirs = stateDirs(config.stateDir)\n  const declared = new Set((declarations?.entries || []).map((entry) => String(entry.key).toLowerCase()))\n  const terminated = (states?.entries || [])\n    .filter(\n      (record) =>\n        record.terminatedAt &&\n        scopeOfRecord(record) === SCOPE_DOMAIN &&\n        !declared.has(String(record.key).toLowerCase()),\n    )\n    .map((record) => ({\n      key: record.key,\n      scope: scopeOfRecord(record),\n      terminatedAt: record.terminatedAt,\n      terminatedBy: record.terminatedBy,\n      pausedWhenTerminated: Boolean(record.paused),\n      pending: (inboxes?.byKey.get(String(record.key).toLowerCase()) || []).filter((item) => item.status === INBOX_PENDING).length,\n      state: STATE_TERMINATED,\n    }))\n  // 四级里**所有被按下的记录**（含非域级）——这样\"有哪几级被按下\"不用翻目录就能看见。\n  const pausedRecords = (states?.entries || [])\n    .filter((record) => record.paused)\n    .map((record) => ({\n      scope: scopeOfRecord(record),\n      key: record.key,\n      paused: true,\n      pausedAt: record.pausedAt ?? null,\n      pausedBy: record.pausedBy ?? null,\n      pauseNote: record.note ?? null,\n      state:\n        scopeOfRecord(record) === SCOPE_DOMAIN || scopeOfRecord(record) === SCOPE_SESSION\n          ? deriveDomainState({ hasDeclaration: true, online: false, paused: true, terminated: false })\n          : STATE_POLICY_PAUSED,\n      updatedAt: record.updatedAt ?? null,\n    }))\n  // 被按下的**会话级**记录里，有几条推不出项目（拿不到 cwd、域名册里也没有它的声明）\n  // ⇒ 那一级这次判不成。**不拦**是刻意的失败方向，但必须说出来（降级不静默）。\n  const unresolved = []\n  for (const record of states?.entries || []) {\n    if (scopeOfRecord(record) !== SCOPE_SESSION || !record.paused) continue\n    const missed = pauseCandidatesForSession(declarations, opts?.ctx || null, record.key, {}).unresolved\n    for (const item of missed) unresolved.push({ ...item, scope: SCOPE_SESSION, key: record.key })\n  }\n  return {\n    // 兼容：这一段仍然是\"以域级行为主键\"的段（旧字段语义不变）；四级在 `scopes` / `pausedRecords` 里。\n    scope: SCOPE_DOMAIN,\n    scopes: PAUSE_SCOPES,\n    scopeHint:\n      'v0.4.2：暂停支持**四级**（`domain` 域 / `session` 主＝单会话 / `project` 项目 / `global` 全局）。' +\n      '判定是 **OR 叠加**：任一级被按下就拦，回执给出**全部**命中级别（`pausedScopes` / `pausedByScopes`）。' +\n      '两端都查——接收端（目标域键 / 目标会话 / 目标会话的项目 / global）与发送端（本会话 / 本会话的项目 / global）；' +\n      '**刻意不含**\"本会话自己持有的域被暂停\"（域级暂停只关那扇门，不禁言整个会话）。' +\n      'global 是保留键 `*`（唯一），按/解都要求 `confirm:true` 防误触。' +\n      '状态文件\"一 scope 一键一文件\"：域级沿用 `k-<flat>-<sha1>`，其余三级是 `<scope>-k-…`。',\n    scopeImplemented: [...PAUSE_SCOPES],\n    scopePlanned: [],\n    scopeNote:\n      '`在线·已暂停` / `离线·已暂停` 说不出\"是哪一级按下的\"——所以每条命中都另给 `pausedScopes`（级别名）' +\n      '与 `pausedByScopes`（逐条的 scope/key/via/side/谁在何时按下）。project / global 两级没有单个会话，' +\n      '所以它们的对外状态就是政策轴的两个词「已暂停」/「活动」（`STATE_POLICY_*`）。',\n    dir: dirs.base,\n    domainsDir: dirs.domains,\n    inboxDir: dirs.inbox,\n    error: states?.error ?? null,\n    count: states?.entries?.length ?? 0,\n    derivedStates: DERIVED_STATE_LEGEND,\n    terminated,\n    pausedRecords,\n    pausedRecordCount: pausedRecords.length,\n    // 降级**不静默**：状态文件/队列行读不懂时如实暴露（但绝不因此拦住投递）。\n    unreadableStateFiles: states?.unreadable ?? [],\n    degradedQueueFiles: inboxes?.degraded ?? [],\n    // v0.4.2：级联里判不成的那几级（例如会话 id 查不到 cwd ⇒ 推不出项目）——**不拦，但必须说出来**。\n    unresolved,\n    degradeNote:\n      '读不懂的状态文件按「没有这条记录」处理（＝政策轴上当作活动，**不拦投递**）：这是刻意的失败方向——' +\n      '一份坏文件不能让整个域永久排不上队。但降级不静默，读不懂的文件名列在上面两份清单里，请人工看一眼。',\n  }\n}\n\n/**\n * 会话行上的政策轴标注（v0.4.2：四级全查）。\n * 会话行本身的\"在线\"是既定事实（它就在在线列表里）⇒ 派生状态只可能是 `在线·活动` / `在线·已暂停`。\n * 查的级别：① 它**自己**的会话级 ② 它所在项目级 ③ 它持有的域级 ④ global。\n * `pausedDomains`（它持有的、被按下的域键）是 v0.4.0 就有的字段，语义不变；新增\n * `pausedScopes` / `pausedByScopes` 把\"到底是哪几级按着\"说全（会话行不许骗人）。\n */\nexport function sessionPauseFields(info, duties, states, opts) {\n  const o = opts || {}\n  const sessionId = info?.id ?? null\n  const candidates = []\n  if (sessionId) {\n    candidates.push(\n      ...pauseCandidatesForSession(o.declarations || null, o.ctx || null, sessionId, {\n        viaSession: 'self-session',\n        viaProject: 'self-project',\n        viaDomainFromSession: 'held-domain',\n        side: 'self',\n        projectHint: projectFromCwd(info?.cwd),\n        projectFrom: '这条会话活 Agent 的 cwd 目录名（小写）',\n      }).candidates,\n    )\n  }\n  candidates.push(...pauseCandidatesGlobal())\n  const { hits } = pauseHitsOfMap(states, candidates)\n  const pausedDomains = hits\n    .filter((hit) => hit.scope === SCOPE_DOMAIN)\n    .map((hit) => String(hit.key))\n    .sort()\n  return {\n    paused: hits.length > 0,\n    state: hits.length > 0 ? STATE_ONLINE_PAUSED : STATE_ONLINE_ACTIVE,\n    pausedDomains,\n    pausedScopes: pausedScopesOf(hits),\n    pausedByScopes: pausedByScopesOf(hits),\n  }\n}\n\n// --- v0.4.0/v0.4.2 interception: 「暂停 OR」的唯一判定入口 ---\n\n/** 完整会话 id 的形状（宿主自建的会话一律 `session-<uuid>`）。 */\nexport function resolveSessionKeyForState(declarations, rows, rawSession) {\n  const text = String(rawSession ?? '').trim()\n  if (!text) return { error: 'session 键不能为空（完整会话 id，或唯一命中的短号）。' }\n  if (isFullSessionId(text)) return { id: text, from: '完整会话 id（原样使用，不要求它现在在线）' }\n  const known = new Map()\n  for (const row of rows || []) if (row?.info?.id) known.set(row.info.id, '在线顶层会话')\n  for (const entry of declarations?.entries || []) {\n    if (entry?.sessionId && !known.has(entry.sessionId)) known.set(entry.sessionId, '在任声明')\n  }\n  const needle = text.toLowerCase()\n  const hits = [...known.keys()].filter((id) => {\n    const lower = String(id).toLowerCase()\n    return lower === needle || lower.includes(needle) || String(shortId(id) || '').toLowerCase() === needle\n  })\n  if (hits.length === 1) return { id: hits[0], from: `短号/片段唯一命中（${known.get(hits[0])}）` }\n  if (hits.length === 0) {\n    return {\n      error: `没有已知会话能和「${text}」对上（在线顶层会话与域名册声明里都没有）⇒ 请写**完整**会话 id（session-<uuid>）。`,\n      reason: 'session-not-found',\n      candidates: [],\n    }\n  }\n  return {\n    error: `「${text}」命中 ${hits.length} 条会话，本工具不替你猜 ⇒ 请写**完整**会话 id。`,\n    reason: 'session-ambiguous',\n    candidates: hits.sort(),\n  }\n}\n\n/** 一个域键的项目名：域名册里的 `project` 优先，其次从键本体切（`项目:域`）。 */\nexport function projectOfDomainKey(declarations, key) {\n  const entry = declarations?.byKey?.get(String(key ?? '').toLowerCase()) || null\n  const fromEntry = String(entry?.project ?? '').trim()\n  if (fromEntry) return fromEntry.toLowerCase()\n  const raw = String(key ?? '')\n  if (!raw.includes(':')) return null\n  const project = raw.slice(0, raw.indexOf(':')).trim().toLowerCase()\n  return project || null\n}\n\n/** 一条会话在域名册里持有的声明能推出哪个项目（离线也能推——这就是它比 cwd 更可靠的地方）。 */\nexport function projectOfSessionDeclarations(declarations, sessionId) {\n  const list = dutyMap(declarations).get(sessionId) || []\n  for (const entry of list) {\n    const project = String(entry.project ?? '').trim()\n    if (project) return { project: project.toLowerCase(), from: `域名册里该会话持有的声明（${entry.key}）` }\n    const key = String(entry.key ?? '')\n    if (key.includes(':')) {\n      return { project: key.slice(0, key.indexOf(':')).trim().toLowerCase(), from: `域名册里该会话持有的声明键（${key}）` }\n    }\n  }\n  return null\n}\n\n/** 活 Agent 的 cwd（拿不到就是 null——**绝不猜**；查不到 cwd ⇒ 项目级不拦 + 标 unresolved）。 */\nexport function sessionCwdOf(ctx, sessionId) {\n  try {\n    const agent = ctx?.agents?.get?.(sessionId)\n    const cwd = agent?.session?.header?.cwd\n    if (typeof cwd === 'string' && cwd.trim()) return cwd.trim()\n  } catch {\n    /* 取不到就返回 null（降级不拦），不抛。 */\n  }\n  return null\n}\n\n/** 接收端：一个**域键**归到的级别（域级本身 + 它的项目 + 它负责人的会话）。global 由调用方补。 */\nexport function pauseCandidatesForDomain(declarations, key, opts) {\n  const o = opts || {}\n  const side = o.side || 'target'\n  const out = [\n    {\n      scope: SCOPE_DOMAIN,\n      key: String(key ?? ''),\n      via: o.via || 'target-domain',\n      legacyVia: o.legacyVia || 'declaration',\n      side,\n    },\n  ]\n  const project = projectOfDomainKey(declarations, key)\n  if (project) out.push({ scope: SCOPE_PROJECT, key: project, via: o.viaProject || 'target-project', side })\n  const entry = declarations?.byKey?.get(String(key ?? '').toLowerCase()) || null\n  if (entry?.sessionId) out.push({ scope: SCOPE_SESSION, key: entry.sessionId, via: o.viaSession || 'target-session', side })\n  return out\n}\n\n/**\n * 一条**会话**归到的级别：它自己的会话级 + 它所在的项目 + （可选）它在域名册里持有的域。\n * `includeHeldDomains:false` 用于**发送端**——S3 明确：本会话自己持有的域被暂停，**不禁言整个会话**\n * （域级暂停只关那扇门）。\n * 项目推不出来的失败方向：**不拦 + 记 unresolved**（S7：降级不静默、也不误拦）。\n */\nexport function pauseCandidatesForSession(declarations, ctx, sessionId, opts) {\n  const o = opts || {}\n  const side = o.side || 'target'\n  const candidates = [\n    { scope: SCOPE_SESSION, key: String(sessionId ?? ''), via: o.viaSession || 'target-session', side },\n  ]\n  const unresolved = []\n  let project = o.projectHint ? String(o.projectHint).trim().toLowerCase() : null\n  let projectFrom = project ? o.projectFrom || '调用方给的目录名（小写）' : null\n  if (!project) {\n    const fromDecl = projectOfSessionDeclarations(declarations, sessionId)\n    if (fromDecl) {\n      project = fromDecl.project\n      projectFrom = fromDecl.from\n    }\n  }\n  if (!project) {\n    const fromCwd = projectFromCwd(sessionCwdOf(ctx, sessionId))\n    if (fromCwd) {\n      project = fromCwd\n      projectFrom = '这条会话活 Agent 的 cwd 目录名（小写）'\n    }\n  }\n  if (project) {\n    candidates.push({ scope: SCOPE_PROJECT, key: project, via: o.viaProject || 'target-project', side, projectFrom })\n  } else {\n    unresolved.push({\n      level: 'project',\n      scope: SCOPE_PROJECT,\n      via: o.viaProject || 'target-project',\n      key: String(sessionId ?? ''),\n      reason: 'project-unresolved',\n      detail:\n        '这条会话现在没有活 Agent 的 cwd、域名册里也没有它的声明 ⇒ **项目级这次判不成（按\"不拦\"处理）**；' +\n        '要严格判项目级，请先把它的 cwd 变得可见，或改用「项目:域」完整写法走域级。',\n    })\n  }\n  if (o.includeHeldDomains !== false) {\n    for (const entry of dutyMap(declarations).get(sessionId) || []) {\n      candidates.push({\n        scope: SCOPE_DOMAIN,\n        key: entry.key,\n        via: o.viaDomainFromSession || 'target-domain',\n        legacyVia: 'session-id',\n        side,\n      })\n    }\n  }\n  return { candidates, unresolved }\n}\n\n/** global 是唯一键 `*`（第四级）。 */\nexport function pauseCandidatesGlobal(side) {\n  return [{ scope: SCOPE_GLOBAL, key: GLOBAL_KEY, via: 'global', side: side || 'global' }]\n}\n\n/** 同一 (scope,key) 只留一条（`via` 合成 `vias`，并把 side 升成 both）——不许重复报一个级别。 */\nexport function dedupePauseHits(hits) {\n  const out = []\n  const index = new Map()\n  for (const hit of hits || []) {\n    const cursor = String(hit.scope) + '\\u0000' + String(hit.key).toLowerCase()\n    const prior = index.get(cursor)\n    if (!prior) {\n      const copy = { ...hit, vias: [hit.via] }\n      index.set(cursor, copy)\n      out.push(copy)\n      continue\n    }\n    if (!prior.vias.includes(hit.via)) prior.vias.push(hit.via)\n    if (prior.side !== hit.side) prior.side = 'both'\n  }\n  return out\n}\n\n/**\n * 按 (scope, key) 精确取一条状态记录：\n *   ① 优先用 `byScopeKey`（v0.4.2 起 list 路径与按需读共用同一套精确查找）；\n *   ② 没有精确表时退回 `byKey`，并**校验 scope**（跨 scope 的同名字符串不许互相顶掉）。\n */\nexport function lookupPauseRecord(states, scope, key) {\n  const lower = String(key ?? '').toLowerCase()\n  const real = String(scope ?? '').trim().toLowerCase() || SCOPE_DOMAIN\n  const exact = states?.byScopeKey?.get(real + '\\u0000' + lower)\n  if (exact) return exact\n  const loose = states?.byKey?.get(lower)\n  if (!loose) return null\n  return scopeOfRecord(loose) === real ? loose : null\n}\n\n/**\n * 一组候选键 → 命中（**OR 叠加**）。数据源是已经读进来的 states（list 路径）。\n * `lookupPauseRecord` 按 (scope,key) 精确取 ⇒ 跨 scope 同名字符串也不会互相顶掉。\n */\nexport function pauseHitsOfMap(states, candidates) {\n  const hits = []\n  for (const candidate of candidates || []) {\n    if (!candidate || !candidate.key) continue\n    const record = lookupPauseRecord(states, candidate.scope, candidate.key)\n    if (record && record.paused === true) hits.push({ ...candidate, record })\n  }\n  return { hits: dedupePauseHits(hits), unreadable: [] }\n}\n\n/** 一组候选键 → 命中（OR）。数据源是**磁盘**（按需逐键读，不扫全目录）。 */\nexport function pauseHitsOfDisk(config, candidates) {\n  const hits = []\n  const unreadable = []\n  const seen = new Set()\n  for (const candidate of candidates || []) {\n    if (!candidate || !candidate.key) continue\n    const scope = String(candidate.scope ?? '').trim().toLowerCase() || SCOPE_DOMAIN\n    const cursor = scope + '\\u0000' + String(candidate.key).toLowerCase()\n    if (seen.has(cursor)) continue\n    seen.add(cursor)\n    const record = loadDomainState(config.stateDir, candidate.key, scope)\n    if (record.existed && record.scope && String(record.scope).toLowerCase() !== scope) {\n      unreadable.push({\n        scope,\n        key: candidate.key,\n        file: record.file,\n        error: `记录里的 scope（${record.scope}）与它所属的 scope（${scope}）不一致（按\"不是这条记录\"处理）`,\n      })\n      continue\n    }\n    if (record.error) {\n      unreadable.push({ scope, key: candidate.key, file: record.file, error: record.error })\n      continue\n    }\n    if (record.paused === true) hits.push({ ...candidate, record })\n  }\n  return { hits: dedupePauseHits(hits), unreadable }\n}\n\n/**\n * 暂停拦截的**唯一**判定入口（v0.4.2：四级 + OR + 两端）。\n *\n * 接收端（target 能归到的所有级别）：\n *   ① target 就是那个域（短名 / 「项目:域」）⇒ 域键；② target 是会话 id / 短号 ⇒ 那条会话\n *   （它自己 + 它的项目 + 它在域名册里持有的域——v0.4.1「按会话 id 直投也绕不开域级暂停」的语义保留）；\n *   ③ 目标会话所属项目；④ global。\n * 发送端（本会话）：① 本会话 id ② 本会话所属项目 ③ global。\n *   **刻意不含**「本会话自己持有的域被暂停」——域级暂停只关那扇门，不禁言整个会话\n *   （这条边界是为了让域级行为与 v0.4.1 逐字一致）。\n *\n * 返回**永远**是对象：`hits` 为空＝没被任何一级按下（`unresolved` / `unreadable` 仍要如实带出去）。\n * `queueKey` ＝ S5 的入队键（**被投递目标自身的键**：target 是域 ⇒ 域键；target 是会话 ⇒ 会话 id）。\n */\nexport function pausedTargetOf(config, declarations, rawTarget, opts) {\n  const o = opts || {}\n  const rows = Array.isArray(o.rows) ? o.rows : []\n  const ctx = o.ctx || null\n  const self = o.self || null\n  const index = o.index || null\n  const target = String(rawTarget ?? '').trim()\n  const candidates = []\n  const unresolved = []\n  let domainKey = null\n  let domainFromDeclaration = false\n  let targetSessionId = null\n  if (target) {\n    const colon = target.indexOf(':')\n    const domainPart = (colon === -1 ? target : target.slice(colon + 1)).trim()\n    const declared = matchDeclaration(declarations, target, domainPart)\n    if (declared.status === 'declared') {\n      domainKey = declared.entry.key\n      domainFromDeclaration = true\n      if (declared.entry.sessionId) targetSessionId = declared.entry.sessionId\n      candidates.push(\n        ...pauseCandidatesForDomain(declarations, domainKey, { via: 'target-domain', legacyVia: 'declaration' }),\n      )\n    } else if (colon !== -1) {\n      // 「项目:域」完整写法：即使册子里没有这条声明，也认这个 key（状态记录可能还在）。\n      domainKey = target\n      candidates.push(\n        ...pauseCandidatesForDomain(declarations, domainKey, { via: 'target-domain', legacyVia: 'declaration' }),\n      )\n    } else if (declared.status === 'ambiguous') {\n      unresolved.push({\n        level: 'domain',\n        scope: SCOPE_DOMAIN,\n        via: 'target-domain',\n        key: target,\n        reason: 'ambiguous-declarations',\n        detail: `同名域有 ${declared.entries.length} 条在任声明 ⇒ 域级这次判不成（不猜、按\"不拦\"处理）。`,\n        candidates: declared.entries.map((entry) => entry.key).sort(),\n      })\n    }\n    const asSession = resolveSessionKeyForState(declarations, rows, target)\n    if (asSession.id) {\n      if (!targetSessionId) targetSessionId = asSession.id\n      const forSession = pauseCandidatesForSession(declarations, ctx, asSession.id, {\n        viaSession: 'target-session',\n        side: 'target',\n      })\n      candidates.push(...forSession.candidates)\n      unresolved.push(...forSession.unresolved)\n    } else if (asSession.error && !targetSessionId) {\n      // ── v0.4.2 修 F1：**裸短名 / 册子里没有声明**的 target —— 先按 `send_to_domain` 将来那套\n      // 解析（会话 id 片段 / **索引标注**）试着把目标落到**一条在线会话**上：\n      //   · 解析得到 ⇒ 用这条会话算 ②会话级 ③它的项目 ④global，**命中即拦**\n      //     （与\"直接写会话 id\"完全一致；否则\"项目被按下 + 裸短名\"就能绕过暂停）；\n      //   · 解析不到 ⇒ **不拦**，但**必须** push `unresolved`（写明哪几级判不成）——\n      //     「判不出 ⇒ 不拦但必须标」这条对两条路径一致（会话侧原先就有，裸短名这条原先没有）。\n      const viaIndex =\n        declared.status === 'none' ? resolveTarget(rows, target, declarations, ctx, index) : null\n      if (viaIndex && viaIndex.ok && viaIndex.row?.info?.id) {\n        targetSessionId = viaIndex.row.info.id\n        const forSession = pauseCandidatesForSession(declarations, ctx, targetSessionId, {\n          viaSession: 'target-session',\n          side: 'target',\n        })\n        candidates.push(...forSession.candidates)\n        unresolved.push(...forSession.unresolved)\n      } else {\n        const resolveReason = viaIndex && !viaIndex.ok ? viaIndex.reason : null\n        const looksLikeSession = isSessionIdLike(target)\n        unresolved.push({\n          level: 'session',\n          scope: SCOPE_SESSION,\n          via: 'target-session',\n          key: target,\n          reason: resolveReason || asSession.reason || 'session-not-found',\n          detail:\n            `「${target}」${looksLikeSession ? '看起来是在说会话' : '既不在域名册里'}，也没能按会话 id 片段或` +\n            `索引标注解析成**一条**在线会话（解析结果=${resolveReason || asSession.reason || 'not-found'}）` +\n            `⇒ **会话级这一级判不成（按\"不拦\"处理）**。`,\n        })\n        unresolved.push({\n          level: 'project',\n          scope: SCOPE_PROJECT,\n          via: 'target-project',\n          key: target,\n          reason: 'project-unresolved',\n          detail:\n            '同上：目标会话没定下来 ⇒ 推不出它属于哪个项目（按\"不拦\"处理）。' +\n            '要严格判项目级，请先补 claim_domain，或改用**完整会话 id** / 「项目:域」完整写法。',\n        })\n      }\n    }\n    candidates.push(...pauseCandidatesGlobal())\n  }\n  if (self && self.id) {\n    const forSelf = pauseCandidatesForSession(declarations, ctx, self.id, {\n      side: 'self',\n      viaSession: 'self-session',\n      viaProject: 'self-project',\n      includeHeldDomains: false,\n      projectHint: projectFromCwd(self.cwd),\n      projectFrom: '本会话 cwd 的目录名（小写）',\n    })\n    candidates.push(...forSelf.candidates)\n    unresolved.push(...forSelf.unresolved)\n  } else if (self) {\n    unresolved.push({\n      level: 'session',\n      scope: SCOPE_SESSION,\n      via: 'self-session',\n      key: null,\n      reason: 'self-session-id-missing',\n      detail: '本会话拿不到 id ⇒ 发送端这一级判不成（按\"不拦\"处理）。',\n    })\n  }\n  const evaluated = pauseHitsOfDisk(config, candidates)\n  // S5：入队键＝**被投递目标自身的键**（域 ⇒ 域键；会话 ⇒ 会话 id）。\n  const targetIsSessionOnly = Boolean(targetSessionId) && !domainFromDeclaration && !target.includes(':')\n  return {\n    hits: evaluated.hits,\n    unreadable: evaluated.unreadable,\n    unresolved,\n    candidates,\n    domainKey,\n    domainFromDeclaration,\n    targetSessionId,\n    queueKey: targetIsSessionOnly ? targetSessionId : domainKey || targetSessionId || target,\n  }\n}\n\n/**\n * 一个 (scope, key) 记录**自身那一级**连同\"会压着它\"的其它级别（OR 全量）。\n *   domain  ⇒ 域级 + 该域的项目 + 该域负责人的会话 + global\n *   session ⇒ 会话级 + 该会话的项目 + 该会话持有的域 + global\n *   project ⇒ 项目级 + global\n *   global  ⇒ global\n */\nexport function pauseCandidatesForScopeKey(declarations, ctx, scope, key) {\n  if (scope === SCOPE_SESSION) {\n    return pauseCandidatesForSession(declarations, ctx, key, { side: 'target' }).candidates.concat(\n      pauseCandidatesGlobal(),\n    )\n  }\n  if (scope === SCOPE_PROJECT) {\n    return [{ scope: SCOPE_PROJECT, key: String(key ?? ''), via: 'target-project', side: 'target' }].concat(\n      pauseCandidatesGlobal(),\n    )\n  }\n  if (scope === SCOPE_GLOBAL) return pauseCandidatesGlobal()\n  return pauseCandidatesForDomain(declarations, key, {}).concat(pauseCandidatesGlobal())\n}\n\n/** 该 (scope,key) 在队列目录里**自己那个键**的 pending 条数（project/global 没有自己的队列 ⇒ 0）。 */\nexport function pendingOfOwnQueue(config, scope, key) {\n  if (scope !== SCOPE_DOMAIN && scope !== SCOPE_SESSION) return 0\n  return loadInbox(config.stateDir, key).pending\n}\n\n/** 同上，但给总行数（pending + delivered + failed + withdrawn）。 */\nexport function recordsOfOwnQueue(config, scope, key) {\n  if (scope !== SCOPE_DOMAIN && scope !== SCOPE_SESSION) return 0\n  return loadInbox(config.stateDir, key).total\n}\n\n/**\n * 现在被**这一级**压着、因而投不出去的 pending 总条数（逐条重评 OR）。\n * 这是恢复时真正要看的数（project/global 没有\"自己的队列\"，所以不能用 loadInbox(key)）。\n */\nexport function pendingPressedByScope(config, declarations, ctx, scope, key) {\n  const wanted = String(key ?? '').toLowerCase()\n  const inboxes = loadInboxes(config.stateDir)\n  let pending = 0\n  const queues = []\n  for (const [queueKey, records] of inboxes.byKey) {\n    const press = pausePressersOfQueueKey(config, declarations, ctx, queueKey)\n    const hit = press.hits.some((item) => item.scope === scope && String(item.key).toLowerCase() === wanted)\n    if (!hit) continue\n    const count = records.filter((record) => record.status === INBOX_PENDING).length\n    if (count > 0) {\n      pending += count\n      queues.push(queueKey)\n    }\n  }\n  return { pending, queues: queues.sort() }\n}\n\n/** 命中块里\"主命中\"（报兼容字段用）：优先级 域 > 会话 > 项目 > global。 */\nexport function primaryPauseHit(hits) {\n  for (const scope of [SCOPE_DOMAIN, SCOPE_SESSION, SCOPE_PROJECT, SCOPE_GLOBAL]) {\n    const hit = (hits || []).find((item) => item.scope === scope)\n    if (hit) return hit\n  }\n  return (hits || [])[0] || null\n}\n\n/**\n * 被暂停时的**公共事实块**（send / create / probe / dryRun 共用）：\n * 旧字段（`scope` / `derivedState` / `paused*` / `matchedBy` / `domain` / `sessionId`）逐字保留，\n * 另给四级全量（`pausedScopes` / `pausedByScopes` / `pausedNotice`）——**不许只报一个级别**。\n */\nexport function pausedFactsOf({ config, declarations, ctx, rows, evaluated, domainKey, fallbackKey }) {\n  const hits = evaluated.hits || []\n  const primary = primaryPauseHit(hits)\n  const key = domainKey ?? (primary && primary.scope === SCOPE_DOMAIN ? primary.key : fallbackKey ?? null)\n  let snapshot = null\n  if (key && !String(key).toLowerCase().startsWith('session-')) {\n    snapshot = domainSnapshot({\n      declarations,\n      states: loadPauseStateMap(\n        config,\n        pauseCandidatesForDomain(declarations, key, {}).concat(pauseCandidatesGlobal()),\n      ),\n      ctx,\n      rows,\n      key,\n      inbox: loadInbox(config.stateDir, key),\n      hits,\n    })\n  }\n  const online = snapshot?.online ?? (primary?.scope === SCOPE_SESSION ? isSessionOnline(ctx, primary.key, rows) : null)\n  const state =\n    snapshot?.state ??\n    (online === null\n      ? hits.length\n        ? STATE_POLICY_PAUSED\n        : STATE_POLICY_ACTIVE\n      : deriveDomainState({ hasDeclaration: true, online, paused: hits.length > 0, terminated: false }))\n  return {\n    scope: primary?.scope ?? SCOPE_DOMAIN,\n    domain: snapshot?.key ?? (primary?.scope === SCOPE_DOMAIN ? primary?.key ?? null : null),\n    derivedState: state,\n    online,\n    paused: hits.length > 0,\n    pausedAt: primary?.record?.pausedAt ?? null,\n    pausedBy: primary?.record?.pausedBy ?? null,\n    pauseNote: primary?.record?.note ?? null,\n    matchedBy:\n      primary?.scope === SCOPE_DOMAIN && primary?.legacyVia === 'session-id'\n        ? 'session-id-holds-paused-domain'\n        : 'declaration',\n    sessionId: snapshot?.sessionId ?? evaluated.targetSessionId ?? null,\n    pausedScopes: pausedScopesOf(hits),\n    pausedByScopes: pausedByScopesOf(hits),\n    pausedNotice: `当前被按下的是：${pausedScopesWords(hits)}。`,\n  }\n}\n\n/**\n * 被暂停时的大白话 hint（send_to_domain 用）：现状 + 消息在哪 + 怎么恢复 + 怎么撤回。\n * v0.4.2：现状要说出**全部**命中级别（OR），恢复入口按 scope 给（域 / 会话 / 项目 / 全局）。\n */\nexport function pausedSendHint(snapshot, queueId) {\n  const hits = snapshot.pausedHits || []\n  const releaseLines = (hits.length ? hits : [{ scope: SCOPE_DOMAIN, key: snapshot.key }]).map((hit) =>\n    hit.scope === SCOPE_GLOBAL\n      ? `set_domain_state(scope='global', state='active', confirm=true)`\n      : `set_domain_state(scope='${hit.scope}', domain='${hit.key}', state='active')`,\n  )\n  return (\n    `「${snapshot.queueKey ?? snapshot.key}」这次**发不出去**（该目标**已暂停**）：按着它的是 ${pausedScopesWords(hits)}` +\n    `——**本工具没有投递，也没有替你找人顶上**：消息已经落盘入队（id=${queueId}，pending=${snapshot.pending}），` +\n    `dsh 重启也不会丢（注入式入队不持久：dsh 一退出，未读的注入会被整体取消，所以这里必须落盘）。` +\n    `可撤回：withdraw_domain_message(id='${queueId}')。要恢复投递：人手动唤起 ⇒ ` +\n    `把**按着它的每一级**都解开（${[...new Set(releaseLines)].join('、')}）——` +\n    `恢复时会**重新评估 OR**：只有**不再被任何一级压着**的 pending 才会按原 mode 重投。` +\n    `插件只管插件介导的路径：人自己点开那条会话、或宿主自己 resume，插件拦不住——那正是「人工手动唤起」。`\n  )\n}\n\n/** 被暂停时的 hint（create_domain_session 用）。 */\nexport function pausedCreateHint(facts) {\n  const hits = facts.pausedHits || []\n  const releaseLines = (hits.length ? hits : [{ scope: SCOPE_DOMAIN, key: facts.key }]).map((hit) =>\n    hit.scope === SCOPE_GLOBAL\n      ? `set_domain_state(scope='global', state='active', confirm=true)`\n      : `set_domain_state(scope='${hit.scope}', domain='${hit.key}', state='active')`,\n  )\n  return (\n    `这次**没有新建任何会话**：被按下的是 ${pausedScopesWords(hits)}` +\n    `（对外状态＝${facts.state}）——暂停期间不新开、也不唤醒这个域，这正是\"暂停\"的意义。` +\n    `要开工二选一：① 先把**按着它的每一级**解开（${[...new Set(releaseLines)].join('、')}），再重跑本工具；` +\n    `② 换一个域/项目（不要往一个已被按下的域里再塞会话）。`\n  )\n}\n\n/**\n * claim_domain / release_domain 共用的「该域仍处已暂停」提示（v0.4.2：四级 OR）。\n * **未暂停时返回空对象**——一个键都不多，保证「非暂停域行为与 v0.3.6 逐字一致」。\n * 依据（用户拍板）：换人（claim force）/ 退役（release）**都不等于解暂停**。\n */\nexport function pausedNoticeOf(config, key, declarations) {\n  const candidates = pauseCandidatesForDomain(declarations, key, {}).concat(pauseCandidatesGlobal())\n  const { hits } = pauseHitsOfDisk(config, candidates)\n  if (hits.length === 0) return {}\n  const domainHit = hits.find((hit) => hit.scope === SCOPE_DOMAIN) || null\n  const who = pausedWhoWords({\n    pausedBy: domainHit?.record?.pausedBy,\n    pausedAt: domainHit?.record?.pausedAt,\n    pauseNote: domainHit?.record?.note,\n  })\n  const releaseLines = hits.map((hit) =>\n    hit.scope === SCOPE_GLOBAL\n      ? `set_domain_state(scope='global', state='active', confirm=true)`\n      : `set_domain_state(scope='${hit.scope}', domain='${hit.key}', state='active')`,\n  )\n  return {\n    paused: true,\n    pausedAt: domainHit?.record?.pausedAt ?? null,\n    pausedBy: domainHit?.record?.pausedBy ?? null,\n    pauseNote: domainHit?.record?.note ?? null,\n    pausedScopes: pausedScopesOf(hits),\n    pausedByScopes: pausedByScopesOf(hits),\n    pausedNotice:\n      `注意：该域**仍处已暂停**（${who}）——认领 / 交接 / 退役都**不会**解除暂停（换人 ≠ 解暂停）。` +\n      `按着它的级别：${pausedScopesWords(hits)}。`,\n    pausedHint: `要恢复活动：${[...new Set(releaseLines)].join('、')}（恢复时会把队列里的 pending 按原 mode 重新投递）。`,\n  }\n}\n\n// --------------------------------------------------------------- argument helpers\n\n/**\n * F-18（2026-10-24）**进程内投递租约**：同一进程里两路 drain 可能拿到**同一份** pending 快照\n * （目标离线且可唤醒时，两路都在 `resolveWakeWiring` / `resumeSession` 的 `await` 处汇合，醒来后\n * 各自把同一条投一遍 —— 真机复现：agent 收到 2 条）。这里用模块级 `Set` 记\"本进程正在投的 id\"：\n * 后到的那一路直接跳过（记 `skipped-inflight`），**绝不重复投**。\n *\n * 三条纪律：\n *  ① **配对**：`add` 之后无论成功 / 失败 / 抛错，`finally` 里一定 `delete`（绝不泄漏，否则这条消息\n *     本进程再也投不出去）。\n *  ② **只管同进程**：跨进程（两个 dsh 实例）的重复投**不在本租约的范围**里；那一层由\n *     `claimInboxDelivery()` 的落盘 `delivering` 认为兜底（同一份 pending 快照的第二路会读到它）。\n *  ③ **不会漏投**：集合只在\"这一条已经在投\"的极短窗口内命中；集合本身不拦任何**后续** drain\n *     （下一路读到的是终态或过期租约，按正常路径投/重投）。\n */\nconst deliveringIds = new Set()\n\n/** 测试钩子：当前进程内正在投的 id 数（必须恒在投递结束后回到 0）。不要在生产代码里依赖它。 */\nexport function __inflightSize() {\n  return deliveringIds.size\n}\n\n/**\n * 把队列里 pending 的消息按**原 mode** 重投一遍（`set_domain_state(state='active')` 的恢复动作）。\n *\n * 并发契约（F-18）：两路 drain 同时对同一条 key 跑 ⇒ **每条消息只投一次**、队列终态 `delivered`、\n * 不留 `delivering`；后到的那一路在 `skippedInflight` 里如实记账（不假装投成功、也不报错）。\n */\nexport async function drainInbox(ctx, config, key, self) {\n  const inbox = loadInbox(config.stateDir, key)\n  const nowMs = Date.now()\n  // 候选＝pending ＋ **过期**的 delivering 租约（上一个投递者崩了/写终态连续失败 ⇒ 这里接管重投）。\n  // 未过期的 delivering 不算候选：另一个投递者正在投它（同进程的另一路，或本进程重启前的自己）。\n  const pending = inbox.records.filter(\n    (record) => record.status === INBOX_PENDING || isStaleDelivering(record, nowMs, DELIVERING_STALE_MS),\n  )\n  const inflightOnDisk = inbox.records.filter(\n    (record) => record.status === INBOX_DELIVERING && !isStaleDelivering(record, nowMs, DELIVERING_STALE_MS),\n  )\n  const out = {\n    attempted: true,\n    // v0.4.2：队列 key 的**目标自身 scope**（域键 ⇒ domain；会话 id ⇒ session）——S5 的入队键口径。\n    scope: queueScopeOf(key),\n    key: String(key),\n    file: inbox.file,\n    ownerSessionId: null,\n    ownerOnline: false,\n    wake: null,\n    pendingBefore: pending.length,\n    delivered: [],\n    failed: [],\n    stillPending: [],\n    stillPausedBy: [],\n    statusWriteFailures: [],\n    // F-18：本次**没有经我投递**的 id（另一路正在投 / 已被另一路处理 / 认领拿不到锁）。\n    // 每条 `{id, reason, error, status}`；`reason` ∈ inflight | delivering-not-stale | not-pending |\n    // not-found | locked | lock-failed | write-failed。**不是错误**：它们没有被重复投，也没有丢。\n    skippedInflight: inflightOnDisk.map((record) => ({\n      id: record.id,\n      reason: 'delivering-not-stale',\n      error: null,\n      status: INBOX_DELIVERING,\n    })),\n    reason: null,\n    error: null,\n    hint: null,\n  }\n  /**\n   * 本次**一条都不投**时（仍被压着 / 负责人离线）把**过期**的 `delivering` 租约退回 `pending`：\n   * 否则崩溃遗留的中间态会一直悬着（`pending` 计数漏掉它、`withdraw` 也碰不到它），\n   * 而它本来就不该在这次 pass 里被投。返回退回的条数（供 hint 如实说明）。\n   */\n  const releaseStaleClaims = () => {\n    let reverted = 0\n    for (const record of pending) {\n      if (!isStaleDelivering(record, nowMs, DELIVERING_STALE_MS)) continue\n      const wrote = updateInboxStatus(config.stateDir, key, record.id, INBOX_PENDING, {\n        deliveringAt: null,\n        deliveringBy: null,\n      })\n      if (wrote.ok) reverted += 1\n      else out.statusWriteFailures.push({ id: record.id, status: INBOX_PENDING, error: wrote.error ?? wrote.reason })\n    }\n    return reverted\n  }\n  if (pending.length === 0) {\n    out.attempted = false\n    out.reason = 'nothing-pending'\n    out.hint =\n      '这个域的队列里没有待投消息，无需重投。' +\n      (out.skippedInflight.length\n        ? `（另有 ${out.skippedInflight.length} 条正在投递中——它们由另一个投递者负责，未过 ${Math.round(DELIVERING_STALE_MS / 60000)} 分钟前不会被抢走。）`\n        : '')\n    return out\n  }\n  const declarations = loadDeclarations(config.domainsFile)\n  // ── v0.4.2：**重评 OR**（drain 的正确性来源）。一条 pending 能不能投，只看它目标**当下**的判定，\n  // 与当初被哪一级拦下无关；仍被任何一级压着 ⇒ **保持 pending**，并说清是被谁压着。\n  const press = pausePressersOfQueueKey(config, declarations, ctx, key)\n  // 降级不静默：这条队列目标的状态文件读不懂 ⇒ 不拦（照常投），但把文件名带出来。\n  if (press.unreadable.length) out.unreadableStateFiles = press.unreadable\n  if (press.hits.length > 0) {\n    out.attempted = false\n    out.reason = 'still-pressed'\n    out.stillPending = pending.map((record) => record.id)\n    out.stillPausedBy = press.hits.map((hit) => ({\n      scope: hit.scope,\n      key: String(hit.key ?? ''),\n      via: hit.via ?? null,\n      side: hit.side ?? null,\n      pausedAt: hit.record?.pausedAt ?? null,\n      pausedBy: hit.record?.pausedBy ?? null,\n    }))\n    if (press.unreadable.length) out.unreadableStateFiles = press.unreadable\n    const revertedByPress = releaseStaleClaims()\n    out.hint =\n      `这 ${pending.length} 条消息**仍被压着，没有投出去**（原样保留 pending）：` +\n      `${pausedScopesWords(press.hits)}。` +\n      (revertedByPress ? `其中 ${revertedByPress} 条是上次崩溃遗留的 delivering 租约，已退回 pending。` : '') +\n      `要投它们，得把**所有**压着它目标的那几级都解开（解一级不够——判定是 OR 叠加）；` +\n      `解开任意一级后再调一次 set_domain_state(state='active')，它会**重新评估**。`\n    warn(\n      `[${TRACE_ID_V042}] 恢复重评：${key} 仍被 ${pausedScopesOf(press.hits).join('+')} 压着 ⇒ ` +\n        `${pending.length} 条保持 pending（不投）。`,\n    )\n    return out\n  }\n  // 队列 key 就是目标自身的键：会话键的\"负责人\"就是这条会话；域键才去域名册里找负责人。\n  const entry = queueScopeOf(key) === SCOPE_SESSION ? null : declarations.byKey.get(String(key).toLowerCase()) || null\n  const ownerSessionId = queueScopeOf(key) === SCOPE_SESSION ? String(key) : entry?.sessionId ?? null\n  out.ownerSessionId = ownerSessionId\n  let agent = liveAgentOf(ctx, ownerSessionId)\n  out.ownerOnline = Boolean(agent)\n  if (!agent) {\n    // v0.4.1：**允许尝试唤醒**（人的显式动作）。只要队列里有任何一条是\"真会跑回合\"的档\n    // （mode≠inject），拉活就必须带接线 —— 没接线就不裸拉（安全门在 resumeSession 里）。\n    const wakeRunsTurn = pending.some((record) => String(record.mode ?? 'followup').toLowerCase() !== 'inject')\n    const wiring = ownerSessionId ? await resolveWakeWiring(ctx, ownerSessionId) : null\n    out.wake = ownerSessionId\n      ? await resumeSession(ctx, ownerSessionId, wiring, { requireWiring: wakeRunsTurn })\n      : null\n    if (out.wake && out.wake.ok) agent = liveAgentOf(ctx, ownerSessionId)\n    out.ownerOnline = Boolean(agent)\n    warn(\n      `[${TRACE_ID_V041}] 恢复时尝试唤醒 ${key}：候选=${shortId(ownerSessionId) || '（无）'}，` +\n        `结果=${out.wake ? (out.wake.ok ? '已拉活' : out.wake.reason) : 'no-owner-declared'}，` +\n        `接线=agentOptions:${out.wake?.wakeWiring?.agentOptions ?? 'none'}/setup:${out.wake?.wakeWiring?.setup ?? 'skipped'}。`,\n    )\n  }\n  if (!agent) {\n    out.reason = 'owner-offline'\n    out.stillPending = pending.map((record) => record.id)\n    const revertedByOffline = releaseStaleClaims()\n    const wakeReason = out.wake ? out.wake.reason : 'no-owner-declared'\n    out.hint =\n      `目标会话 ${shortId(ownerSessionId) || ownerSessionId || '（无在任负责人）'} 当前没有活 Agent ⇒ ` +\n      `这 ${pending.length} 条消息**原样保留 pending**（没有假装投成功）。` +\n      (revertedByOffline ? `其中 ${revertedByOffline} 条是上次崩溃遗留的 delivering 租约，已退回 pending。` : '') +\n      `恢复时**已经试过拉活**（结果=${wakeReason}` +\n      `${out.wake && out.wake.error ? '：' + out.wake.error : ''}）⇒ ` +\n      (wakeReason === 'no-wake-wiring'\n        ? `拉活要先接好 provider/model，这次两条取源都空（agentOptions:none）⇒ **没有裸拉**：` +\n          `裸 resume 起来的会话 100ms 内就崩（prompt variable \"{{model}}\" has no value …persona-prefix）。`\n        : `它没被拉起来。`) +\n      `要真派活，请用 create_domain_session，或人在 GUI 点开那条会话；它一活过来，` +\n      `再调一次 set_domain_state(state='active') 就能把这批消息投出去。`\n    return out\n  }\n  for (const record of pending) {\n    const id = record.id\n    // ── F-18：同一进程里另一路 drain 正在投它 ⇒ 直接跳过（**不**重复投，也不报错）。\n    if (deliveringIds.has(id)) {\n      out.skippedInflight.push({ id, reason: 'inflight', error: null, status: INBOX_DELIVERING })\n      continue\n    }\n    deliveringIds.add(id)\n    try {\n      // ── 落盘认领（pending ⇒ delivering）：锁内 CAS，是\"这条归我投\"的唯一裁决。\n      // 另一路（同进程的、或跨进程的）读到 delivering/终态就回 not-pending ⇒ 只会有一个投递者。\n      const claimed = claimInboxDelivery(config.stateDir, key, id, {\n        staleMs: DELIVERING_STALE_MS,\n        by: self?.id ?? null,\n      })\n      if (!claimed.ok) {\n        out.skippedInflight.push({\n          id,\n          reason: claimed.reason ?? 'unknown',\n          error: claimed.error ?? null,\n          status: claimed.status ?? null,\n        })\n        continue\n      }\n      const mode = String(record.mode ?? 'followup').toLowerCase()\n      let attempt\n      try {\n        const envelope = String(record.content ?? '')\n        const payload = domainMessage({ self: { id: record.from ?? null, domains: [] }, envelope })\n        attempt = deliverToAgent(agent, mode, payload)\n      } catch (error) {\n        attempt = { ok: false, reason: 'deliver-threw', error: messageOf(error) }\n      }\n      if (attempt.ok) {\n        const wrote = updateInboxStatus(config.stateDir, key, id, INBOX_DELIVERED, {\n          deliveredAt: new Date().toISOString(),\n          deliveredBy: self?.id ?? null,\n          // 终态不保留租约字段：队列里\"已投递\"的记录不该看起来像还在投。\n          deliveringAt: null,\n          deliveringBy: null,\n        })\n        out.delivered.push(id)\n        // 消息**确实投出去了**，但状态没写进去 ⇒ 如实记账（下次恢复可能重投一次，重复优于丢消息）。\n        if (!wrote.ok) out.statusWriteFailures.push({ id, status: INBOX_DELIVERED, error: wrote.error ?? wrote.reason })\n      } else {\n        const wrote = updateInboxStatus(config.stateDir, key, id, INBOX_FAILED, {\n          failedReason: attempt.reason,\n          failedAt: new Date().toISOString(),\n          deliveringAt: null,\n          deliveringBy: null,\n        })\n        out.failed.push({ id, mode, reason: attempt.reason ?? 'unknown' })\n        if (!wrote.ok) out.statusWriteFailures.push({ id, status: INBOX_FAILED, error: wrote.error ?? wrote.reason })\n      }\n    } finally {\n      // 成功 / 失败 / 抛错都释放：漏一次 delete 就等于这条消息在本进程再也投不出去。\n      deliveringIds.delete(id)\n    }\n  }\n  out.reason = out.failed.length\n    ? out.delivered.length\n      ? 'partial'\n      : 'all-failed'\n    : out.delivered.length\n      ? 'delivered'\n      : out.skippedInflight.length\n        ? 'skipped-inflight'\n        : 'nothing-pending'\n  out.hint = out.failed.length\n    ? `恢复了 ${out.delivered.length} 条，${out.failed.length} 条**投递失败**（已标 failed，不会自动重试；原因见 failed）。`\n    : out.delivered.length\n      ? `队列里 ${out.delivered.length} 条 pending 已按原 mode 全部投出去（已标 delivered）。`\n      : '本次一条都没有投出去（每一条都被另一个投递者认领走了，见 skippedInflight）——它们不会被重复投。'\n  if (out.skippedInflight.length) {\n    out.hint +=\n      `另有 ${out.skippedInflight.length} 条**未经本次投递**：同时/更早还有一路在投它们（F-18 的进程内租约与` +\n      `队列里的 delivering 认领挡住了重复投），它们要么已被那一路投成 delivered，要么仍在投递窗口中（见 skippedInflight）。`\n  }\n  if (out.statusWriteFailures.length) {\n    out.hint +=\n      `⚠️ 另有 ${out.statusWriteFailures.length} 条**投出去了但状态没写进队列文件**（原因见 statusWriteFailures）⇒` +\n      `下次恢复可能重复投一次（重复优于丢消息），请人工看一眼队列文件。`\n  }\n  if (out.failed.length) {\n    warn(\n      `[${TRACE_ID_V040}] 恢复重投 ${key}：delivered=${out.delivered.length}，failed=${out.failed.length}` +\n        `（${out.failed.map((item) => item.reason).join('/')}）。`,\n    )\n  }\n  return out\n}\n\n/**\n * 一条队列 key 现在还被哪些级别压着（v0.4.2 的**逐条重评 OR**，drain 的正确性来源）。\n * 队列 key 只有两种（S5：**被投递目标自身的键**）：域键（`项目:域`）或完整会话 id。\n */\nexport function pausePressersOfQueueKey(config, declarations, ctx, key) {\n  const text = String(key ?? '').trim()\n  const candidates =\n    queueScopeOf(text) === SCOPE_SESSION\n      ? pauseCandidatesForSession(declarations, ctx, text, { viaSession: 'target-session', side: 'target' }).candidates\n      : pauseCandidatesForDomain(declarations, text, { via: 'target-domain', side: 'target' })\n  return pauseHitsOfDisk(config, candidates.concat(pauseCandidatesGlobal()))\n}\n\n/** 把若干条队列的 drain 结果聚成一个 `drain` 段（单条时**逐字**返回那一条，兼容旧回执）。 */\nexport function aggregateDrains({ scope, key, allKeys, selected, skipped, results }) {\n  const flat = (field) => results.flatMap((item) => item[field] || [])\n  const delivered = flat('delivered')\n  const failed = flat('failed')\n  const stillPending = flat('stillPending')\n  const statusWriteFailures = flat('statusWriteFailures')\n  // F-18：多队列聚合时把\"没经我投、被另一路认领走\"的 id 也带上来（不丢信息，也不冒充成功）。\n  const skippedInflight = flat('skippedInflight')\n  const stillPausedBy = results.flatMap((item) =>\n    (item.stillPausedBy || []).map((hit) => ({ ...hit, queueKey: item.key })),\n  )\n  if (results.length === 0) {\n    return {\n      attempted: false,\n      resumedScope: scope,\n      resumedKey: String(key ?? ''),\n      multi: false,\n      keys: selected,\n      skipped,\n      allKeys,\n      delivered,\n      failed,\n      stillPending,\n      statusWriteFailures,\n      skippedInflight,\n      stillPausedBy,\n      deliveredCount: 0,\n      failedCount: 0,\n      stillPendingCount: 0,\n      skippedInflightCount: 0,\n      wake: null,\n      reason: 'nothing-in-scope',\n      error: null,\n      hint: `恢复 ${scopeWords(scope)}「${key}」：队列目录里没有任何属于它的队列文件，无需重投。`,\n    }\n  }\n  if (results.length === 1) {\n    return {\n      ...results[0],\n      resumedScope: scope,\n      resumedKey: String(key ?? ''),\n      multi: false,\n      keys: selected,\n      skipped,\n      allKeys,\n    }\n  }\n  const pressedWords = [...new Set(stillPausedBy.map((hit) => `${scopeWords(hit.scope)}「${hit.key}」`))].join('、')\n  return {\n    attempted: results.some((item) => item.attempted),\n    resumedScope: scope,\n    resumedKey: String(key ?? ''),\n    multi: true,\n    keys: selected,\n    skipped,\n    allKeys,\n    queues: results.map((item) => ({\n      key: item.key,\n      scope: item.scope,\n      reason: item.reason,\n      delivered: item.delivered.length,\n      failed: item.failed.length,\n      stillPending: item.stillPending.length,\n      skippedInflight: (item.skippedInflight || []).length,\n      stillPausedBy: item.stillPausedBy || [],\n    })),\n    delivered,\n    failed,\n    stillPending,\n    statusWriteFailures,\n    skippedInflight,\n    stillPausedBy,\n    deliveredCount: delivered.length,\n    failedCount: failed.length,\n    stillPendingCount: stillPending.length,\n    skippedInflightCount: skippedInflight.length,\n    wake: results.find((item) => item.wake)?.wake ?? null,\n    reason: failed.length\n      ? 'partial'\n      : stillPending.length\n        ? 'still-pending'\n        : delivered.length\n          ? 'delivered'\n          : skippedInflight.length\n            ? 'skipped-inflight'\n            : 'nothing-pending',\n    error: null,\n    hint:\n      `恢复 ${scopeWords(scope)}「${key}」：队列目录里 ${allKeys.length} 个队列，选中 ${selected.length} 个 ⇒ ` +\n      `**投出 ${delivered.length} 条 / 失败 ${failed.length} 条 / 仍被压着保留 pending ${stillPending.length} 条**` +\n      `${pressedWords ? `（压着它们的还是：${pressedWords}）` : ''}` +\n      `${skippedInflight.length ? `；另有 ${skippedInflight.length} 条被另一路投递者认领（见 skippedInflight，未重复投）` : ''}` +\n      `${skipped.length ? `；另有 ${skipped.length} 个队列判不出归属（见 skipped，按\"不投、不乱投\"处理）` : ''}。`,\n  }\n}\n\n/**\n * v0.4.2：按**恢复动作的 scope**决定扫哪些队列（扫哪些只是优化，正确性来自逐条重评 OR）：\n *   · `global`       ⇒ inbox 目录**全量**\n *   · `project:P`    ⇒ `P:*` 域键 ＋ 属于项目 P 的会话键（判不出归属的记进 `skipped`，不投）\n *   · `session:sid`  ⇒ 该会话键 ＋ **该会话持有的域键**\n *   · `domain:k`     ⇒ 该键\n * 每条都再过一遍 drainInbox 的\"重评 OR\"闸：仍被别的级压着 ⇒ 保持 pending 并给 `stillPausedBy`。\n */\nexport async function drainScopeQueues(ctx, config, scope, key, self) {\n  const declarations = loadDeclarations(config.domainsFile)\n  const inboxes = loadInboxes(config.stateDir)\n  const allKeys = [...inboxes.byKey.keys()].sort()\n  const wanted = String(key ?? '').toLowerCase()\n  const selected = []\n  const skipped = []\n  if (scope === SCOPE_GLOBAL) {\n    selected.push(...allKeys)\n  } else if (scope === SCOPE_PROJECT) {\n    for (const queueKey of allKeys) {\n      if (queueScopeOf(queueKey) === SCOPE_DOMAIN) {\n        if (queueKey.startsWith(wanted + ':')) selected.push(queueKey)\n        continue\n      }\n      const forSession = pauseCandidatesForSession(declarations, ctx, queueKey, {})\n      const projectHit = forSession.candidates.find((candidate) => candidate.scope === SCOPE_PROJECT)\n      if (projectHit && projectHit.key.toLowerCase() === wanted) selected.push(queueKey)\n      else if (!projectHit) skipped.push({ key: queueKey, reason: 'project-unresolved' })\n    }\n  } else if (scope === SCOPE_SESSION) {\n    const held = (dutyMap(declarations).get(String(key)) || []).map((entry) => String(entry.key).toLowerCase())\n    selected.push(wanted)\n    for (const heldKey of held) if (!selected.includes(heldKey)) selected.push(heldKey)\n  } else {\n    selected.push(wanted)\n  }\n  const results = []\n  for (const queueKey of selected) results.push(await drainInbox(ctx, config, queueKey, self))\n  return aggregateDrains({ scope, key, allKeys, selected, skipped, results })\n}\n\n// --------------------------------------------------------------- session factory helpers\n\n/**\n * Optional lookup of the host session factory. The service is NEVER hard-injected: if this\n * deployment does not mount it, the plugin must still load and the tool must still answer.\n * `ctx.get(name)` is the optional accessor used by dsh's own code; the property read is a\n * fallback for realms whose ctx proxy resolves services directly.\n */\nexport function buildSetDomainStateTool(ctx, config) {\n  return tool(\n    'set_domain_state',\n    '**把某一级（域 / 主 / 项目 / 全局）的政策轴设成「已暂停」或「活动」**（v0.4.2：四级；v0.4.0 只有域级）。模型是**两个轴 + 生命周期**：事实轴＝**在线/离线**（宿主给、只读）；政策轴＝**活动/已暂停**（人给、可逆，字段 `paused`）；生命周期＝在用/**已终结**（`release_domain`）。对外给**派生状态**（`在线·活动` / `在线·已暂停` / `离线·活动` / `离线·已暂停` / `已终结`；project / global 没有单个会话，所以它们的对外状态就是政策轴的两个词「已暂停」/「活动」）。**四级与键**：`scope=\\'domain\\'`（默认）键＝`项目:域`，**要求域名册里已有一条在任声明**（用户拍板的「承认现状」，v0.4.0 语义一字不改）；`scope=\\'session\\'`（＝中文的「主（单会话暂停）」）键＝**完整会话 id**（`session-<uuid>`；短号 `sess-xxxxxxxx` 只在唯一命中一条已知会话时接受）；`scope=\\'project\\'` 键＝**项目名小写**（某会话 cwd 的目录名小写）；`scope=\\'global\\'` 键＝保留键 `*`（唯一）。后三级**不要求**有在任声明。**判定是 OR 叠加**：任一级被按下就拦，回执给出**全部**命中级别（`pausedScopes` / `pausedByScopes`）。**两端都查**：接收端（目标域键 / 目标会话 / 目标会话的项目 / global）＋发送端（本会话 / 本会话的项目 / global）；**刻意不含**「本会话自己持有的域被暂停」——域级暂停只关那扇门，不禁言整个会话。**global 防误触**：`scope=\\'global\\'` 必须带 `confirm:true`，缺了直接拒绝（`reason:\\'global-needs-confirm\\'`）且**一个文件都不写**。**暂停不改在任身份**（域名册一个字节不动）；暂停期间所有**插件介导**的路径都被拦——`send_to_domain` 不投递、消息**落盘入队**（可撤回；入队键＝被投递目标**自身**的键），`create_domain_session` 被拒（`reason=domain-paused`），`wake` 不许把目标拉活（除非显式 `force`）；`claim_domain` / `release_domain` **照常允许**（换人 / 退役 ≠ 解暂停）。`state=\\'active\\'` ＝ **人手动唤起**：解开这一级后**重新评估 OR**——只重投\"现在不再被任何一级压着\"的 pending，**仍被别的级压着的保持 pending** 并如实报（`drain.stillPausedBy`）；驱动范围：global 扫 inbox 全量、project 扫 `P:*` 与属于 P 的会话键、session 扫该会话键＋它持有的域键、domain 扫该键。目标离线时**允许尝试唤醒**（拉活带接线：provider/model 分级取源 + best-effort setup），唤得起来就按原 mode 重投、唤不起来保留 pending（见回执 `drain.wake`）。只有队列里有 mode≠inject 的 pending 时，唤醒才要求接线（否则拒绝裸拉）。⚠️ 只有人显式调 `active` 才尝试唤醒——**被按下的目标不会被别人自动叫醒**。**向后兼容**：不传 `scope` ⇒ 走 `domain` 级，旧字段（`key` / `domain` / `state` / `paused` / `pausedAt` / `pausedBy` / `pauseNote` / `drain` …）语义不变，新字段只新增。**边界**：本工具只管插件介导的路径——人自己点开那条会话、或宿主自己 resume，插件拦不住，那正是「人工手动唤起」。',\n    {\n      domain: { type: 'string', description: \"要动的那个**键**（按 scope 解释）：scope='domain'（默认）⇒ 域短名（asr）或「项目:域」（misas:asr），短名优先用域名册里唯一的那条同名声明；scope='session' ⇒ 完整会话 id（session-<uuid>）或唯一命中的短号（sess-xxxxxxxx）；scope='project' ⇒ 项目名（小写，如 misas）；scope='global' ⇒ 不要给（键固定是 *）。\" },\n      scope: { type: 'string', description: \"'domain'（默认，域＝域名册里的一个 key）| 'session'（主＝单会话暂停，键＝完整会话 id）| 'project'（项目，键＝项目名小写）| 'global'（全局，键＝*，需要 confirm）。中文别名：域 / 主 / 会话 / 项目 / 全局。**不传＝domain**（旧调用语义逐字不变）。\" },\n      confirm: { type: 'boolean', description: \"只有 scope='global' 需要它：必须显式 true 才真的按/解全局（防误触）。缺了 ⇒ 拒绝，reason='global-needs-confirm'，**一个文件都不写**。其余 scope 不要求。\" },\n      state: { type: 'string', description: \"'paused' ＝ 按下暂停（政策轴，可逆）；'active' ＝ 恢复活动（＝人手动唤起：恢复时**重新评估 OR**，只把「现在不再被任何一级压着」的 pending 按原 mode 重投）。\" },\n      note: { type: 'string', description: '可选：为什么按下（写进状态记录；回执与 list_* 里都会显示「谁、何时按下」＋这条 note）。恢复时不清除它（保留为历史）。' },\n      dryRun: { type: 'boolean', description: 'true = 只回报将会怎么改（含\"会重投几条\"、\"现在被哪几级压着\"），不写任何文件、也不重投（默认 false）。' },\n    },\n    async (args, exec) => {\n      const index = loadIndex(config.indexFile)\n      const declarations = loadDeclarations(config.domainsFile)\n      const duties = dutyMap(declarations)\n      const self = describe(exec?.agent, index, duties)\n      const rawState = String(args.state ?? '').trim().toLowerCase()\n      const wanted = ['paused', 'pause', '暂停'].includes(rawState)\n        ? 'paused'\n        : ['active', 'resume', 'resumed', '活动', '恢复'].includes(rawState)\n          ? 'active'\n          : null\n      if (!wanted) {\n        return {\n          action: 'set_domain_state',\n          outcome: 'invalid',\n          reason: 'invalid-state',\n          self,\n          hint: `state 只能是 'paused'（按下暂停）或 'active'（恢复活动＝人手动唤起）；收到的是 ${JSON.stringify(String(args.state ?? ''))}。`,\n        }\n      }\n      // ── v0.4.2 入口：先定 scope（缺省＝domain ⇒ 旧调用语义逐字不变）。\n      const rawScope = String(args.scope ?? '').trim().toLowerCase()\n      const scope = rawScope ? SCOPE_ALIASES[rawScope] ?? null : SCOPE_DOMAIN\n      if (!scope) {\n        return {\n          action: 'set_domain_state',\n          outcome: 'invalid',\n          reason: 'invalid-scope',\n          scope: rawScope || null,\n          accepted: PAUSE_SCOPES,\n          self,\n          hint:\n            `scope 只能是 ${PAUSE_SCOPES.join(' | ')}（中文别名：域 / 主 / 会话 / 项目 / 全局）；` +\n            `收到的是 ${JSON.stringify(String(args.scope ?? ''))}。不给 scope ＝ domain（旧语义）。`,\n        }\n      }\n      // ── S4：global 是\"整台机器\"级开关，防误触 ⇒ **必须 confirm:true**；缺了就拒绝，**一个文件都不写**。\n      if (scope === SCOPE_GLOBAL && args.confirm !== true) {\n        return {\n          action: 'set_domain_state',\n          outcome: 'invalid',\n          reason: 'global-needs-confirm',\n          scope,\n          key: GLOBAL_KEY,\n          wanted,\n          wrote: false,\n          wroteNothing: true,\n          file: null,\n          self,\n          hint:\n            `global（全局）是唯一键 \\`${GLOBAL_KEY}\\` 的**整台机器**级开关：按/解都要求显式 \\`confirm:true\\` 防误触。` +\n            `本次**没有写任何文件、也没有重投任何消息**。确实要动全局，请重发一次并带上 confirm:true。`,\n        }\n      }\n\n      // ── 按键解析（按 scope 分叉）。⚠️ **只有 domain 级要求域名册里有这个 key**（用户拍板的\n      // D2=A「承认现状」，v0.4.0 起的语义一字不改）；session / project / global 三级**不受它约束**，\n      // 它们本来就不挂在声明册上。\n      let key = null\n      let resolution = { domain: null, project: null, projectFrom: null, sessionFrom: null }\n      if (scope === SCOPE_DOMAIN) {\n        const resolvedKey = resolveDomainKeyForState(declarations, args.domain, self.cwd)\n        if (resolvedKey.error) {\n          return {\n            action: 'set_domain_state',\n            outcome: 'invalid',\n            reason: resolvedKey.error,\n            candidates: resolvedKey.candidates ?? null,\n            self,\n          }\n        }\n        key = resolvedKey.key\n        resolution = {\n          domain: resolvedKey.domain,\n          project: resolvedKey.project ?? null,\n          projectFrom: resolvedKey.projectFrom,\n          sessionFrom: null,\n        }\n        const read = readDeclarationsForWrite(config.domainsFile)\n        if (read.parseError) {\n          return {\n            action: 'set_domain_state',\n            outcome: 'aborted',\n            reason: 'declarations-file-unreadable',\n            error: read.parseError,\n            key,\n            file: config.domainsFile,\n            self,\n            hint: '声明文件已存在但读不懂：为了不误判「这个域到底有没有在任负责人」，本次没有写任何文件。请先人工看一眼那份文件。',\n          }\n        }\n        const entry = Object.prototype.hasOwnProperty.call(read.data.owners, key) ? read.data.owners[key] : null\n        if (!entry) {\n          return {\n            action: 'set_domain_state',\n            outcome: 'no-declaration',\n            key,\n            scope: SCOPE_DOMAIN,\n            file: config.domainsFile,\n            writableKeys: Object.keys(read.data.owners).sort(),\n            self,\n            hint:\n              `域名册里没有「${key}」这条在任声明 ⇒ **没有可暂停的域**（域级暂停挂在声明册的一个 key 上，` +\n              `它不是\"整台机器\"或\"某个项目\"级别的开关）。先 claim_domain 认领，或改用「项目:域」的完整写法。` +\n              `（要按\"整台机器\"或\"某个项目\"，请用 scope='global' 或 scope='project'——那两级不要求有在任声明。）`,\n          }\n        }\n      } else if (scope === SCOPE_GLOBAL) {\n        const given = String(args.domain ?? '').trim()\n        if (given && given !== GLOBAL_KEY) {\n          return {\n            action: 'set_domain_state',\n            outcome: 'invalid',\n            reason: 'global-key-is-star',\n            scope,\n            key: GLOBAL_KEY,\n            self,\n            hint: `global 是唯一键 \\`${GLOBAL_KEY}\\`（给 domain 参数没有意义）：请写 scope='global' 且**不要**给 domain（或给 '${GLOBAL_KEY}'）。`,\n          }\n        }\n        key = GLOBAL_KEY\n        resolution = { projectFrom: `global 的保留键 ${GLOBAL_KEY}（唯一）` }\n      } else if (scope === SCOPE_PROJECT) {\n        const raw = String(args.domain ?? '').trim()\n        const problems = [checkName(raw, '项目')].filter(Boolean)\n        if (problems.length) {\n          return { action: 'set_domain_state', outcome: 'invalid', reason: problems.join('；'), scope, self }\n        }\n        if (raw === GLOBAL_KEY) {\n          return {\n            action: 'set_domain_state',\n            outcome: 'invalid',\n            reason: 'project-key-reserved',\n            scope,\n            self,\n            hint: `项目名不能是 \\`${GLOBAL_KEY}\\`（那是 global 的保留键）。`,\n          }\n        }\n        key = raw.toLowerCase()\n        resolution = { project: key, projectFrom: '调用方写的项目名（小写化）' }\n      } else {\n        const rowsForSession = liveTopLevel(ctx, index, duties)\n        const resolvedSession = resolveSessionKeyForState(declarations, rowsForSession, args.domain)\n        if (resolvedSession.error) {\n          return {\n            action: 'set_domain_state',\n            outcome: 'invalid',\n            reason: resolvedSession.reason ?? resolvedSession.error,\n            candidates: resolvedSession.candidates ?? null,\n            scope,\n            self,\n            hint: resolvedSession.error,\n          }\n        }\n        key = resolvedSession.id\n        resolution = { sessionFrom: resolvedSession.from }\n      }\n\n      const rowsBefore = liveTopLevel(ctx, index, duties)\n      const ownBefore = loadDomainState(config.stateDir, key, scope)\n      const candidatesOf = () => pauseCandidatesForScopeKey(declarations, ctx, scope, key)\n      const unresolvedOf = () =>\n        scope === SCOPE_SESSION\n          ? pauseCandidatesForSession(declarations, ctx, key, { side: 'target' }).unresolved\n          : []\n      const snapshotOf = (record, rowsNow) => {\n        const rowsForSnapshot = Array.isArray(rowsNow) ? rowsNow : rowsBefore\n        if (scope === SCOPE_DOMAIN) {\n          return domainSnapshot({\n            declarations,\n            states: loadPauseStateMap(config, candidatesOf()),\n            inbox: loadInbox(config.stateDir, key),\n            ctx,\n            rows: rowsForSnapshot,\n            key,\n          })\n        }\n        const press = pauseHitsOfDisk(config, candidatesOf())\n        const online = scope === SCOPE_SESSION ? isSessionOnline(ctx, key, rowsForSnapshot) : null\n        return {\n          scope,\n          key,\n          online,\n          paused: press.hits.length > 0,\n          scopePaused: Boolean(record?.paused),\n          pausedAt: record?.pausedAt ?? press.hits[0]?.record?.pausedAt ?? null,\n          pausedBy: record?.pausedBy ?? press.hits[0]?.record?.pausedBy ?? null,\n          pauseNote: record?.note ?? press.hits[0]?.record?.note ?? null,\n          state:\n            scope === SCOPE_SESSION\n              ? deriveDomainState({ hasDeclaration: true, online, paused: press.hits.length > 0, terminated: false })\n              : press.hits.length > 0\n                ? STATE_POLICY_PAUSED\n                : STATE_POLICY_ACTIVE,\n          pausedScopes: pausedScopesOf(press.hits),\n          pausedByScopes: pausedByScopesOf(press.hits),\n          pending: pendingOfOwnQueue(config, scope, key),\n          queuedTotal: recordsOfOwnQueue(config, scope, key),\n        }\n      }\n      const beforeSnapshot = snapshotOf(ownBefore)\n      const at = new Date().toISOString()\n      const note = typeof args.note === 'string' ? args.note : ownBefore.note ?? null\n      const patch =\n        wanted === 'paused'\n          ? { paused: true, pausedAt: at, pausedBy: self.id ?? null, note }\n          : { paused: false, resumedAt: at, resumedBy: self.id ?? null }\n      const scenario = {\n        action: 'set_domain_state',\n        key,\n        scope,\n        wanted,\n        domain: resolution.domain ?? null,\n        project: resolution.project ?? null,\n        projectFrom: resolution.projectFrom ?? null,\n        sessionFrom: resolution.sessionFrom ?? null,\n      }\n      const pressSummary = () => {\n        const press = pauseHitsOfDisk(config, candidatesOf())\n        const missed = unresolvedOf()\n        return {\n          pausedScopes: pausedScopesOf(press.hits),\n          pausedByScopes: pausedByScopesOf(press.hits),\n          ...(missed.length ? { unresolved: missed } : {}),\n          ...(press.unreadable.length ? { unreadableStateFiles: press.unreadable } : {}),\n        }\n      }\n      warn(\n        `[${TRACE_ID_V042}] 入口：set_domain_state scope=${scope} key=${key} wanted=${wanted} 按人=${self.id ?? '（未知会话）'}；` +\n          `当前命中=${pressSummary().pausedScopes.join('+') || '（无）'}${args.dryRun === true ? '，dryRun' : ''}。`,\n      )\n\n      if (args.dryRun === true) {\n        return {\n          ...scenario,\n          outcome: wanted === 'paused' ? 'would-pause' : 'would-resume',\n          dryRun: true,\n          alreadyInThatState: wanted === 'paused' ? ownBefore.paused : !ownBefore.paused,\n          state: beforeSnapshot.state,\n          scopePaused: ownBefore.paused,\n          paused: beforeSnapshot.paused,\n          pausedAt: ownBefore.pausedAt,\n          pausedBy: ownBefore.pausedBy,\n          pauseNote: ownBefore.pauseNote,\n          ...pressSummary(),\n          wouldWrite: patch,\n          file: ownBefore.file,\n          pending: beforeSnapshot.pending,\n          pendingPressedByThisScope: pendingPressedByScope(config, declarations, ctx, scope, key),\n          self,\n          hint:\n            wanted === 'paused'\n              ? `演练：会把 ${scopeWords(scope)}「${key}」按成**已暂停**（当前 ${beforeSnapshot.state}），写进 ${ownBefore.file}。`\n              : `演练：会把 ${scopeWords(scope)}「${key}」恢复成**活动**（当前 ${beforeSnapshot.state}），` +\n                `并**重新评估 OR**：只重投\"现在不再被任何一级压着\"的 pending（${beforeSnapshot.pending} 条在同名队列里）。` +\n                `**没有写文件、也没有投递**。`,\n        }\n      }\n\n      // 幂等：本来就是这个状态 ⇒ 不重复写。恢复档仍走\"重评 OR + 重投\"（可能是上次没投完的遗留）。\n      if (wanted === 'paused' && ownBefore.paused) {\n        return {\n          ...scenario,\n          outcome: 'already-paused',\n          state: beforeSnapshot.state,\n          scopePaused: true,\n          paused: true,\n          pausedAt: ownBefore.pausedAt,\n          pausedBy: ownBefore.pausedBy,\n          pauseNote: ownBefore.pauseNote,\n          ...pressSummary(),\n          pending: beforeSnapshot.pending,\n          pendingPressedByThisScope: pendingPressedByScope(config, declarations, ctx, scope, key),\n          file: ownBefore.file,\n          wrote: false,\n          self,\n          hint:\n            `${scopeWords(scope)}「${key}」本来就是**已暂停**（${pausedWhoWords(ownBefore)}），本次没有改动。` +\n            `要恢复：set_domain_state(scope='${scope}', domain='${key}', state='active')。`,\n        }\n      }\n      if (wanted === 'active' && !ownBefore.paused) {\n        const drain = await drainScopeQueues(ctx, config, scope, key, self)\n        return {\n          ...scenario,\n          outcome: 'already-active',\n          state: beforeSnapshot.state,\n          scopePaused: false,\n          paused: beforeSnapshot.paused,\n          pausedAt: ownBefore.pausedAt,\n          pausedBy: ownBefore.pausedBy,\n          pauseNote: ownBefore.pauseNote,\n          ...pressSummary(),\n          pending: beforeSnapshot.pending,\n          pendingPressedByThisScope: pendingPressedByScope(config, declarations, ctx, scope, key),\n          file: ownBefore.file,\n          wrote: false,\n          drain,\n          self,\n          hint: `${scopeWords(scope)}「${key}」本来就是活动状态（${beforeSnapshot.state}），没有改动。${drain.hint ?? ''}`,\n        }\n      }\n\n      const written = writeDomainStateAtomic(config.stateDir, key, patch, scope)\n      if (!written.ok) {\n        return {\n          ...scenario,\n          outcome: 'write-failed',\n          reason: written.reason,\n          error: written.error ?? null,\n          file: written.file,\n          wrote: false,\n          self,\n          hint:\n            written.reason === 'state-file-unreadable'\n              ? `状态文件已存在但读不懂（${written.error}）：为避免覆盖它，本次**没有写任何文件**。请先人工看一眼 ${written.file}。`\n              : written.reason === 'scope-conflict'\n                ? `这份状态记录里的 scope 与本次要写的 scope 不一致（${written.error}）：为避免覆盖别人的记录，本次**没有写任何文件**。请先人工看一眼 ${written.file}。`\n                : `写状态记录失败（${written.error}）：政策轴**没有变**，一切照旧。`,\n        }\n      }\n      const after = written.record\n      // ── S6：恢复＝**重评 OR**（只重投\"现在不再被任何一级压着\"的 pending）；驱动范围按 scope 定。\n      const drain = wanted === 'active' ? await drainScopeQueues(ctx, config, scope, key, self) : null\n      const ownAfter = loadDomainState(config.stateDir, key, scope)\n      // v0.4.1 同款：恢复可能刚拉活过目标 ⇒ 重取在线行再算派生状态（这里只读、不写）。\n      const afterSnapshot = snapshotOf(\n        ownAfter,\n        liveTopLevel(ctx, index, dutyMap(loadDeclarations(config.domainsFile))),\n      )\n      const pressedAfter = pendingPressedByScope(config, declarations, ctx, scope, key)\n      warn(\n        `[${TRACE_ID_V042}] 结果：${wanted === 'paused' ? '按下暂停' : '恢复活动'} scope=${scope} key=${key}：` +\n          `${beforeSnapshot.state} ⇒ ${afterSnapshot.state}；本 scope 记录 paused=${ownAfter.paused}；` +\n          `命中级别=${afterSnapshot.pausedScopes.join('+') || '（无）'}；` +\n          `被本 scope 压着的 pending=${pressedAfter.pending}` +\n          `${drain ? `；重投 delivered=${drain.delivered.length}，failed=${drain.failed.length}，stillPending=${drain.stillPending.length}` : ''}。`,\n      )\n      const pauseHint =\n        `已按下暂停：${scopeWords(scope)}「${key}」现在**本级别=已暂停**，对外状态＝**${afterSnapshot.state}**` +\n        `（${pausedWhoWords({ pausedBy: afterSnapshot.pausedBy, pausedAt: afterSnapshot.pausedAt, pauseNote: afterSnapshot.pauseNote })}` +\n        `${afterSnapshot.pausedScopes.length > 1 ? `；同时被 ${afterSnapshot.pausedScopes.join('+')} 压着` : ''}）。` +\n        `从现在起：send_to_domain 会把消息**落盘入队**（可撤回）、create_domain_session **被拒**、` +\n        `wake **被拦**（除非显式 force）；claim_domain / release_domain 仍允许（换人 / 退役 ≠ 解暂停）。` +\n        `恢复：set_domain_state(scope='${scope}', domain='${key}', state='active')。` +\n        `⚠️ 插件只管插件介导的路径：人自己点开那条会话、或宿主自己 resume，插件拦不住——那正是「人工手动唤起」。`\n      const resumeHint =\n        `已恢复活动：${scopeWords(scope)}「${key}」现在**本级别=活动**，对外状态＝**${afterSnapshot.state}**` +\n        `${afterSnapshot.pausedScopes.length ? `（仍被 ${afterSnapshot.pausedScopes.join('+')} 压着）` : ''}。` +\n        (drain ? drain.hint ?? '' : '')\n      return {\n        ...scenario,\n        outcome: wanted === 'paused' ? 'paused' : 'resumed',\n        previousState: beforeSnapshot.state,\n        state: afterSnapshot.state,\n        scopePaused: ownAfter.paused,\n        paused: afterSnapshot.paused,\n        online: afterSnapshot.online,\n        pausedAt: afterSnapshot.pausedAt,\n        pausedBy: afterSnapshot.pausedBy,\n        pauseNote: afterSnapshot.pauseNote,\n        pausedScopes: afterSnapshot.pausedScopes,\n        pausedByScopes: afterSnapshot.pausedByScopes,\n        ...(unresolvedOf().length ? { unresolved: unresolvedOf() } : {}),\n        resumedAt: after.resumedAt,\n        resumedBy: after.resumedBy,\n        wrote: true,\n        bytes: written.bytes,\n        file: written.file,\n        pending: afterSnapshot.pending,\n        queuedTotal: afterSnapshot.queuedTotal,\n        pendingPressedByThisScope: pressedAfter,\n        drain,\n        self,\n        hint: wanted === 'paused' ? pauseHint : resumeHint,\n      }\n    },\n  )\n}\n\n/**\n * v0.4.0：把**自己发的**一条队列消息撤回（默认只允许撤回自己发的；`force:true` 才动别人的）。\n * 只对 `status:'pending'` 的消息生效——已 delivered / failed / withdrawn 的不动（不假装收回）。\n */\n\n/**\n * 把「队列过滤参数」解析成一个队列 key（域键或会话键）。`withdraw_domain_message` 与\n * `list_domain_queue` **共用同一套解析**——两处各写一份，查到的和撤到的就可能不是同一条队列。\n * 返回 `{ok:true,key}` 或 `{ok:false,reason,candidates?,hint?}`；永不抛。\n */\nfunction resolveQueueKeyArg({ config, domainArg, self, ctx }) {\n  const rawWanted = String(domainArg ?? '').trim()\n  const wanted = rawWanted.toLowerCase()\n  if (!wanted) return { ok: false, reason: 'missing-domain', hint: 'domain 不能为空。' }\n  if (queueScopeOf(wanted) === SCOPE_SESSION || wanted.startsWith('sess')) {\n    // 只按会话 id 找队列 key，不需要体系索引（用空索引即可，别在这里读盘）。\n    const rows = liveTopLevel(ctx, emptyIndex())\n    const resolved = resolveSessionKeyForState(loadDeclarations(config.domainsFile), rows, rawWanted)\n    if (resolved.error) {\n      return { ok: false, reason: resolved.reason ?? resolved.error, candidates: resolved.candidates ?? null, hint: resolved.error }\n    }\n    return { ok: true, key: String(resolved.id).toLowerCase() }\n  }\n  const declarations = loadDeclarations(config.domainsFile)\n  const resolved = resolveDomainKeyForState(declarations, rawWanted, self.cwd)\n  if (resolved.error) {\n    return { ok: false, reason: resolved.error, candidates: resolved.candidates ?? null, hint: null }\n  }\n  return { ok: true, key: String(resolved.key).toLowerCase() }\n}\n\nexport function buildWithdrawMessageTool(ctx, config) {\n  return tool(\n    'withdraw_domain_message',\n    '**撤回一条还在队列里的域间消息**（v0.4.0）。`send_to_domain` 被「已暂停」拦下时，回执里的 `queue.id` 就是这里要的 `id`；消息在 `<stateDir>/inbox/<key>.jsonl` 里，一行一条、`status:pending`。默认**只允许撤回自己发的**（`from` 必须等于本会话 id）；`force:true` 才允许动别人发的（回执会标 `forced:true`）。只有 `pending` 能撤：已经 `delivered` / `failed` / `withdrawn` 的**不动**（如实回 `not-pending`，不假装收回）。撤回后该条变成 `status=withdrawn` 并留在文件里当留痕（不删行）。**边界**：这管不了\"人已经在对方窗口里看到的那条\"——它只管插件自己的落盘队列。',\n    {\n      id: { type: 'string', description: '要撤回的队列消息 id。**可省略**（v0.8.14）：只给 domain 时，撤该队列里**最新一条 pending**（默认只认本会话发的，force 才看别人的）。' },\n      domain: { type: 'string', description: '可选：按**队列 key** 过滤（更快、更明确）。v0.4.2 起队列按“被投递目标自身的键”分片，所以这里两种写法都认：域键（短名或「项目:域」）或**会话 id**（完整 id，或唯一命中的短号 sess-xxxxxxxx）。不给就扫全部队列文件。' },\n      force: { type: 'boolean', description: '默认 false ＝ 只允许撤回**自己发的**（from == 本会话 id）。true ＝ 也允许撤回别人发的（回执带 forced:true）。' },\n    },\n    async (args, exec) => {\n      const self = describe(exec?.agent, emptyIndex())\n      const domainArg = args.domain === undefined || args.domain === null ? '' : String(args.domain).trim()\n      let id = String(args.id ?? '').trim()\n      let pickedLatest = false\n      if (!id && !domainArg) {\n        return {\n          action: 'withdraw',\n          outcome: 'invalid',\n          reason: 'missing-id',\n          self,\n          hint:\n            'id 必填，或者给 domain 撤该队列**最新一条 pending**。想看有哪些：list_domain_queue（只读，列出 id / from / at / status）。',\n        }\n      }\n      const inboxes = loadInboxes(config.stateDir)\n      let keys = [...inboxes.byKey.keys()]\n      if (domainArg) {\n        // v0.4.2：队列按「被投递目标自身的键」分片 ⇒ `domain` 过滤要同时认两种键形状：\n        //   ① 域键（域短名 / `项目:域`）⇒ 走 v0.4.0 的域解析；\n        //   ② 会话键（完整 id 或短号，队列按会话 id 分片）⇒ 直接按队列 key 匹配。\n        // 撤回**不受 scope 影响**（它只改 status，不看政策轴）。\n        const resolved = resolveQueueKeyArg({ config, domainArg, self, ctx })\n        if (!resolved.ok) {\n          return {\n            action: 'withdraw',\n            outcome: 'invalid',\n            reason: resolved.reason,\n            ...(resolved.candidates ? { candidates: resolved.candidates } : {}),\n            self,\n            ...(resolved.hint ? { hint: resolved.hint } : {}),\n          }\n        }\n        keys = keys.filter((key) => key === resolved.key)\n      }\n\n      // v0.8.14：只给 domain 不给 id ⇒ 撤这个队列里**最新一条 pending**（默认只认自己的，force 才看别人的）。\n      // 起因：撤回要抄 id，而 id 只在\"发送被暂停拦下\"那一刻的回执里出现过，丢了就撤不回。\n      if (!id) {\n        const candidates = []\n        for (const key of keys) {\n          for (const record of inboxes.byKey.get(key) || []) {\n            if (record.status !== INBOX_PENDING) continue\n            if (args.force !== true && String(record.from ?? '') !== String(self.id ?? '')) continue\n            candidates.push({ key, record })\n          }\n        }\n        candidates.sort((a, b) => String(b.record.at ?? '').localeCompare(String(a.record.at ?? '')))\n        if (!candidates.length) {\n          return {\n            action: 'withdraw',\n            outcome: 'not-found',\n            domain: domainArg,\n            inboxDir: inboxes.dir,\n            queuedKeys: [...inboxes.byKey.keys()].sort(),\n            self,\n            hint:\n              `「${domainArg}」的队列里没有可撤的 pending` +\n              `${args.force === true ? '' : '（默认只看本会话发的；要看别人发的加 force=true）'}。` +\n              '想先看看有哪些：list_domain_queue。',\n          }\n        }\n        id = String(candidates[0].record.id)\n        pickedLatest = true\n      }\n\n      const hits = []\n      for (const key of keys) {\n        for (const record of inboxes.byKey.get(key) || []) {\n          if (record.id === id) hits.push({ key, record })\n        }\n      }\n      if (hits.length === 0) {\n        return {\n          action: 'withdraw',\n          outcome: 'not-found',\n          id,\n          domain: domainArg || null,\n          inboxDir: inboxes.dir,\n          inboxesError: inboxes.error,\n          queuedKeys: [...inboxes.byKey.keys()].sort(),\n          self,\n          hint: `队列里没有 id=${id} 这条消息${domainArg ? `（已按域 ${domainArg} 过滤）` : ''}。可能 id 抄错了，或它已经被 delivered / withdrawn（撤回只对 pending 生效）。`,\n        }\n      }\n      if (hits.length > 1) {\n        return {\n          action: 'withdraw',\n          outcome: 'ambiguous-id',\n          id,\n          keys: hits.map((hit) => hit.key).sort(),\n          self,\n          hint: '这个 id 在多个域的队列里都出现了（同一个 id 不该跨域重复）：请加 domain 参数指明是哪一个。',\n        }\n      }\n      const { key, record } = hits[0]\n      const from = record.from ?? null\n      const forced = args.force === true\n      const mine = Boolean(self.id) && from !== null && from === self.id\n      const fromShort = shortId(from) || from || '（未记录发件人）'\n      if (!mine && !forced) {\n        return {\n          action: 'withdraw',\n          outcome: 'not-owner',\n          id,\n          key,\n          scope: queueScopeOf(key),\n          status: record.status ?? null,\n          from,\n          fromShort,\n          self,\n          hint:\n            `这条不是本会话发的（发件人是 ${fromShort}）⇒ **没有撤回**。默认只允许撤回自己发的；` +\n            `确实要替它撤回：force=true（回执会标注 forced）。`,\n        }\n      }\n      if (record.status !== INBOX_PENDING) {\n        return {\n          action: 'withdraw',\n          outcome: 'not-pending',\n          id,\n          key,\n          scope: queueScopeOf(key),\n          status: record.status ?? null,\n          from,\n          fromShort,\n          deliveredAt: record.deliveredAt ?? null,\n          failedReason: record.failedReason ?? null,\n          self,\n          hint: `这条已经是 ${record.status}，**没有动它**（撤回只对 pending 生效）。`,\n        }\n      }\n      const at = new Date().toISOString()\n      const updated = updateInboxStatus(config.stateDir, key, id, INBOX_WITHDRAWN, {\n        withdrawnAt: at,\n        withdrawnBy: self.id ?? null,\n      })\n      if (!updated.ok) {\n        return {\n          action: 'withdraw',\n          outcome: 'write-failed',\n          id,\n          key,\n          scope: queueScopeOf(key),\n          reason: updated.reason,\n          error: updated.error ?? null,\n          file: updated.file,\n          self,\n          hint: `写队列失败（${updated.error ?? updated.reason}）：这条**没有被撤回**，仍是 pending。`,\n        }\n      }\n      const inbox = loadInbox(config.stateDir, key)\n      if (forced && !mine) {\n        warn(`[${TRACE_ID_V040}] 强制撤回（别人的消息）：${key} id=${id}，发件人=${fromShort}，操作人=${self.id ?? '（未知）'}。`)\n      }\n      return {\n        action: 'withdraw',\n        outcome: 'withdrawn',\n        id,\n        key,\n        scope: queueScopeOf(key),\n        status: INBOX_WITHDRAWN,\n        forced: forced && !mine,\n        from,\n        fromShort,\n        mode: record.mode ?? null,\n        queuedAt: record.at ?? null,\n        pickedLatest,\n        withdrawnAt: at,\n        withdrawnBy: self.id ?? null,\n        messagePreview: clipToBytes(record.message ?? '', 80),\n        pending: inbox.pending,\n        queuedTotal: inbox.total,\n        file: inbox.file,\n        wrote: true,\n        self,\n        hint:\n          `已撤回 id=${id}（「${key}」的队列，status=withdrawn；记录留在文件里当留痕）。` +\n          `这个域现在还有 ${inbox.pending} 条 pending。` +\n          (forced && !mine ? '（这次是 force 撤回**别人发的**消息。）' : ''),\n      }\n    },\n  )\n}\n\n// ------------------------------------------------- v0.8.14 list_domain_queue（只读队列查询）\n\n/**\n * 为什么有这个工具（2026-10-24，用户第 60 条「积压要看得见、撤得回」）：\n *   · `withdraw_domain_message` 要 id，而 id 只在\"发送被暂停拦下\"那一刻的回执里露过面——**丢了就撤不回**；\n *   · `list_domain_owners` 每行只有 `pending` 计数，看不到\"是哪几条、谁发的、什么时候\"。\n * 所以补一个**只读**的队列查询，与 withdraw 共用同一套 key 解析（`resolveQueueKeyArg`）。\n * **边界**：只管插件自己的落盘队列——宿主 composer 里那条「N 条排队消息」不在这里，插件也看不见。\n */\nexport function buildListDomainQueueTool(ctx, config) {\n  return tool(\n    'list_domain_queue',\n    '**只读：列出插件落盘队列里的消息**（v0.8.14）。发送被「已暂停」拦下时消息会落盘入队（`<stateDir>/inbox/<key>.jsonl`），这里能看见 id / 状态 / 发件人 / 入队时间 / mode / 正文摘要，配合 `withdraw_domain_message` 就能撤（也可以只给 domain 撤最新一条）。默认只看 `pending`；`status` 可给 pending / delivering / delivered / failed / withdrawn / all。`domain` 可写域短名、`项目:域`、或会话 id（短号也行）。**边界**：这只管插件自己的队列——宿主 composer 里显示的「N 条排队消息」不在里面，插件看不见也撤不回（宿主边界）。',\n    {\n      domain: { type: 'string', description: '可选：只看某个队列（域短名 / `项目:域` / 会话 id 或短号）。不给就扫全部队列。' },\n      status: { type: 'string', description: 'pending（默认）| delivering | delivered | failed | withdrawn | all。' },\n      mine: { type: 'boolean', description: '默认 false；true ＝ 只看本会话（调用者）发出的。' },\n      limit: { type: 'number', description: '最多返回多少条（默认 50，最大 200），按入队时间倒序。' },\n    },\n    async (args, exec) => {\n      const self = describe(exec?.agent, emptyIndex())\n      const statusArg = String(args.status ?? 'pending').trim().toLowerCase() || 'pending'\n      const allowed = [INBOX_PENDING, INBOX_DELIVERING, INBOX_DELIVERED, INBOX_FAILED, INBOX_WITHDRAWN, 'all']\n      if (!allowed.includes(statusArg)) {\n        return {\n          action: 'queue',\n          outcome: 'invalid',\n          reason: 'bad-status',\n          status: statusArg,\n          allowed,\n          self,\n          hint: 'status 只能是 pending / delivering / delivered / failed / withdrawn / all。',\n        }\n      }\n      const limitRaw = Number(args.limit ?? 50)\n      const limit = Number.isFinite(limitRaw) ? Math.min(200, Math.max(1, Math.trunc(limitRaw))) : 50\n      const mineOnly = args.mine === true\n      const domainArg = args.domain === undefined || args.domain === null ? '' : String(args.domain).trim()\n      const inboxes = loadInboxes(config.stateDir)\n      let keys = [...inboxes.byKey.keys()].sort()\n      if (domainArg) {\n        const resolved = resolveQueueKeyArg({ config, domainArg, self, ctx })\n        if (!resolved.ok) {\n          return {\n            action: 'queue',\n            outcome: 'invalid',\n            reason: resolved.reason,\n            ...(resolved.candidates ? { candidates: resolved.candidates } : {}),\n            self,\n            ...(resolved.hint ? { hint: resolved.hint } : {}),\n          }\n        }\n        keys = keys.filter((key) => key === resolved.key)\n      }\n\n      const queues = []\n      const entries = []\n      const pendingRecords = []\n      let pendingTotal = 0\n      let recordTotal = 0\n      for (const key of keys) {\n        const records = inboxes.byKey.get(key) || []\n        const pending = records.filter((record) => record.status === INBOX_PENDING).length\n        pendingTotal += pending\n        recordTotal += records.length\n        let lastAt = null\n        for (const record of records) {\n          if (!lastAt || String(record.at ?? '') > lastAt) lastAt = String(record.at ?? '') || lastAt\n          if (record.status === INBOX_PENDING) pendingRecords.push({ key, record })\n        }\n        queues.push({ key, scope: queueScopeOf(key), pending, total: records.length, lastAt })\n        for (const record of records) {\n          const status = record.status ?? null\n          if (statusArg !== 'all' && status !== statusArg) continue\n          if (mineOnly && String(record.from ?? '') !== String(self.id ?? '')) continue\n          entries.push({\n            id: record.id ?? null,\n            key,\n            scope: queueScopeOf(key),\n            status,\n            mode: record.mode ?? null,\n            from: record.from ?? null,\n            fromShort: shortId(record.from) ?? null,\n            replyTo: record.replyTo ?? null,\n            queuedAt: record.at ?? null,\n            preview: clipToBytes(String(record.message ?? record.content ?? ''), 80),\n            pausedByScopes: Array.isArray(record.pausedByScopes) ? record.pausedByScopes : null,\n            deliveredAt: record.deliveredAt ?? null,\n            failedReason: record.failedReason ?? null,\n            withdrawnAt: record.withdrawnAt ?? null,\n            withdrawnBy: record.withdrawnBy ?? null,\n          })\n        }\n      }\n      entries.sort((a, b) => String(b.queuedAt ?? '').localeCompare(String(a.queuedAt ?? '')))\n      const shown = entries.slice(0, limit)\n      pendingRecords.sort((a, b) => String(b.record.at ?? '').localeCompare(String(a.record.at ?? '')))\n      const latestPending = pendingRecords[0] ?? null\n      const latestMine = pendingRecords.find((item) => String(item.record.from ?? '') === String(self.id ?? '')) ?? null\n      return {\n        action: 'queue',\n        outcome: 'ok',\n        filters: { domain: domainArg || null, status: statusArg, mine: mineOnly, limit },\n        inboxDir: inboxes.dir,\n        inboxesError: inboxes.error ?? null,\n        totals: { queues: queues.length, pending: pendingTotal, records: recordTotal, matched: entries.length },\n        queues,\n        count: shown.length,\n        truncated: entries.length > shown.length,\n        latestId: latestPending?.record?.id ?? null,\n        latestKey: latestPending?.key ?? null,\n        latestMineId: latestMine?.record?.id ?? null,\n        latestMineKey: latestMine?.key ?? null,\n        entries: shown,\n        degraded: inboxes.degraded ?? [],\n        self,\n        hint:\n          `队列里现在有 ${pendingTotal} 条 pending。撤回：withdraw_domain_message(id=…)` +\n          `${latestMine ? `（最新一条你自己发的：id=${latestMine.record.id}；也可以只给 domain 撤最新一条）` : ''}。` +\n          '这只是**插件落盘队列**；宿主 composer 里显示的「N 条排队消息」不在里面，插件看不见、也撤不回（宿主边界）。',\n      }\n    },\n  )\n}\n\n// ------------------------------------------------- v0.6.0/v0.6.1 model dispatch (list_models / set_model / set_default_model)\n//\n// 事实依据（dsh 0.2.1-rc.2 读 asar 定案；v0.6.0 首次真机验证后的修正见下）：\n//   selectModel({sessionId, provider, model, reasoningEffort?}) 改该会话模型，**下一轮请求生效**；\n//   失败码 session/not-found | session/writer-held | session/model-unavailable。副作用：它会在后台\n//   把该选择写成**全局默认** ⇒ 本插件一律「先记 → 改 → 恢复」，并把 before/after/restored 如实回报。\n//   modelCatalog() **async**（lib/index.js:3121 → lib/types/catalog.js:10 buildModelCatalog）→\n//   {default, routableProviders, groups:[{id,name,models}], failures}；groups 空 ⇒ 退\n//   ctx.llm.listProviders() / listModels(provider)（catalog.js:11/14 自己就是这么组装的）。\n//   会话级模型选择投影：sessionController.projections({sessionId}, signal)（lib/index.js:3280，\n//   返回 {kind:'sequenced', asOfSeq, values}，values.modelSelection ＝ wire 视图 {lastUsed, next}）；\n//   退路 sessionProjections.stateOf(sessionObject, 'modelSelection')（宿主状态 {lastUsed, pending}）\n//   —— 注意它要 Session **对象**，传 id 字符串必抛。\n//   全局默认：agentDefaultModel.currentSelection() / saveSelection(next)（catalog.js:10 默认参数就在用它）。\n// 所有宿主 API 都在调用点做 `typeof` 探测：拿不到就回 {ok:false, reason:'api-unavailable'}，绝不抛。\n\n/** Normalize a {provider, model, reasoningEffort?} selection; null when it is not a usable pair. */\n"
